const lessonReplayAudioTicketSweepInterval = setInterval(() => {
  const nowMs = Date.now();
  lessonReplayAudioUploadTickets.forEach((ticket, audioId) => {
    if (Number(ticket?.expiresAt || 0) >= nowMs) return;
    if (!ticket?.completed && ticket?.storage === 'local' && ticket?.localFilePath) {
      try { fs.rmSync(ticket.localFilePath, { force: true }); } catch {
        // An expired partial upload may already have been removed.
      }
    }
    lessonReplayAudioUploadTickets.delete(audioId);
  });
}, 10 * 60 * 1000);
if (typeof lessonReplayAudioTicketSweepInterval.unref === 'function') {
  lessonReplayAudioTicketSweepInterval.unref();
}
const lessonReplaySessionSweepInterval = setInterval(() => {
  const nowMs = Date.now();
  activeLessonReplaySessions.forEach((session, sessionId) => {
    if (Number(session?.expiresAt || 0) < nowMs) activeLessonReplaySessions.delete(sessionId);
  });
  activeLessonReplayOccurrenceByStudentId.forEach((entry, studentId) => {
    if (nowMs - Number(entry?.lastSeenAt || 0) > LESSON_REPLAY_SESSION_TTL_MS) {
      activeLessonReplayOccurrenceByStudentId.delete(studentId);
    }
  });
}, 15 * 60 * 1000);
if (typeof lessonReplaySessionSweepInterval.unref === 'function') lessonReplaySessionSweepInterval.unref();

const parseEnabledEnv = (value, defaultValue = false) => {
  const raw = String(value || '').trim().toLowerCase();
  if (raw === '1' || raw === 'true' || raw === 'yes' || raw === 'on') return true;
  if (raw === '0' || raw === 'false' || raw === 'no' || raw === 'off') return false;
  return defaultValue;
};

const parseCsvEnv = (value) => String(value || '')
  .split(',')
  .map((entry) => entry.trim())
  .filter(Boolean);

const uniqueStrings = (values = []) => Array.from(new Set(
  (Array.isArray(values) ? values : []).map((entry) => String(entry || '').trim()).filter(Boolean)
));

const AUTH_COOKIE_SAME_SITE = (() => {
  const raw = String(process.env.AUTH_COOKIE_SAME_SITE || '').trim().toLowerCase();
  if (raw === 'strict') return 'Strict';
  if (raw === 'none') return 'None';
  return 'Lax';
})();

const AUTH_COOKIE_SECURE = (() => {
  const raw = String(process.env.AUTH_COOKIE_SECURE || '').trim().toLowerCase();
  if (raw === '1' || raw === 'true' || raw === 'yes' || raw === 'on') return true;
  if (raw === '0' || raw === 'false' || raw === 'no' || raw === 'off') return false;
  if (AUTH_COOKIE_SAME_SITE === 'None') return true;
  return String(process.env.NODE_ENV || '').toLowerCase() === 'production';
})();

const CORS_ALLOWED_ORIGINS = uniqueStrings([
  'http://localhost',
  'capacitor://localhost',
  'ionic://localhost',
  ...parseCsvEnv(process.env.CORS_ALLOWED_ORIGINS || process.env.APP_ALLOWED_ORIGINS),
]);

const appendVaryHeader = (res, value) => {
  const current = res.getHeader('Vary');
  const entries = uniqueStrings([
    ...(typeof current === 'string' ? current.split(',') : []),
    ...(Array.isArray(current) ? current.flatMap((entry) => String(entry || '').split(',')) : []),
    value,
  ]);
  if (entries.length > 0) {
    res.setHeader('Vary', entries.join(', '));
  }
};

const applyCorsHeaders = (req, res) => {
  const origin = typeof req.headers.origin === 'string' ? req.headers.origin.trim() : '';
  if (!origin || !CORS_ALLOWED_ORIGINS.includes(origin)) return false;
  res.setHeader('Access-Control-Allow-Origin', origin);
  res.setHeader('Access-Control-Allow-Credentials', 'true');
  res.setHeader('Access-Control-Allow-Methods', 'GET,HEAD,POST,PUT,PATCH,DELETE,OPTIONS');
  const requestedHeaders = typeof req.headers['access-control-request-headers'] === 'string'
    ? req.headers['access-control-request-headers'].trim()
    : '';
  res.setHeader(
    'Access-Control-Allow-Headers',
    requestedHeaders || 'Content-Type, Authorization, Cache-Control, Pragma, X-Requested-With'
  );
  res.setHeader(
    'Access-Control-Expose-Headers',
    'Content-Disposition, X-Workbook-Key, X-Workbook-Revision, X-Workbook-Content-Hash'
  );
  appendVaryHeader(res, 'Origin');
  appendVaryHeader(res, 'Access-Control-Request-Headers');
  return true;
};

