const getLessonReplayOccurrenceHash = (occurrenceKey) => (
  crypto.createHash('sha256').update(String(occurrenceKey || '')).digest('hex')
);

const persistLessonReplayStorageIndex = () => {
  lessonReplayStorageIndexPersistTimer = null;
  writeJsonFileAtomic(
    lessonReplayStorageIndexFile,
    serializeLessonReplayStorageIndex(lessonReplayStorageIndexByHash)
  );
  lessonReplayStorageIndexDirty = false;
};

const scheduleLessonReplayStorageIndexPersistence = (delayMs = 1500) => {
  if (lessonReplayStorageIndexPersistTimer) return;
  lessonReplayStorageIndexPersistTimer = setTimeout(() => {
    try {
      persistLessonReplayStorageIndex();
    } catch (error) {
      console.error('[lesson-replay] failed to persist storage index:', error?.message || error);
      scheduleLessonReplayStorageIndexPersistence(15_000);
    }
  }, Math.max(250, Number(delayMs) || 1500));
  if (typeof lessonReplayStorageIndexPersistTimer.unref === 'function') {
    lessonReplayStorageIndexPersistTimer.unref();
  }
};

const setLessonReplayStorageIndexByHash = (rawHash, patch = {}, increments = {}) => {
  const hash = String(rawHash || '').trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/.test(hash)) return null;
  const next = mergeLessonReplayStorageEntry(
    lessonReplayStorageIndexByHash.get(hash),
    { ...patch, updatedAt: new Date().toISOString() },
    increments
  );
  lessonReplayStorageIndexByHash.set(hash, next);
  lessonReplayStorageIndexDirty = true;
  lessonReplayStorageSummaryCacheByOccurrenceKey.forEach((_, occurrenceKey) => {
    if (getLessonReplayOccurrenceHash(occurrenceKey) === hash) {
      lessonReplayStorageSummaryCacheByOccurrenceKey.delete(occurrenceKey);
    }
  });
  scheduleLessonReplayStorageIndexPersistence();
  return next;
};

const updateLessonReplayStorageIndex = (occurrenceKey, patch = {}, increments = {}) => {
  const normalizedKey = String(occurrenceKey || '').trim();
  if (!normalizedKey) return null;
  const hash = getLessonReplayOccurrenceHash(normalizedKey);
  const next = mergeLessonReplayStorageEntry(
    lessonReplayStorageIndexByHash.get(hash),
    { ...patch, updatedAt: new Date().toISOString() },
    increments
  );
  lessonReplayStorageIndexByHash.set(hash, next);
  lessonReplayStorageIndexDirty = true;
  lessonReplayStorageSummaryCacheByOccurrenceKey.set(normalizedKey, next);
  scheduleLessonReplayStorageIndexPersistence();
  return next;
};

try {
  const parsedStorageIndex = JSON.parse(fs.readFileSync(lessonReplayStorageIndexFile, 'utf8'));
  normalizeLessonReplayStorageIndex(parsedStorageIndex).forEach((entry, hash) => {
    lessonReplayStorageIndexByHash.set(hash, entry);
  });
} catch (error) {
  if (error?.code !== 'ENOENT') {
    console.warn('[lesson-replay] failed to load storage index:', error?.message || error);
  }
}

process.on('exit', () => {
  if (!lessonReplayStorageIndexDirty) return;
  try {
    persistLessonReplayStorageIndex();
  } catch {
    // The media files remain authoritative and will rebuild the index next boot.
  }
});

const normalizeLessonReplayAudioId = (value) => {
  const normalized = String(value || '').trim().toLowerCase();
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(normalized)
    ? normalized
    : '';
};

const normalizeLessonReplayAudioMimeType = (value) => {
  const normalized = String(value || '').trim().toLowerCase();
  if (normalized.startsWith('audio/webm')) return 'audio/webm;codecs=opus';
  if (normalized.startsWith('audio/ogg')) return 'audio/ogg;codecs=opus';
  if (normalized.startsWith('audio/mp4')) return 'audio/mp4';
  return '';
};

const getLessonReplayAudioExtension = (mimeType) => {
  if (String(mimeType || '').startsWith('audio/ogg')) return 'ogg';
  if (String(mimeType || '').startsWith('audio/mp4')) return 'm4a';
  return 'webm';
};

const getLessonReplayAudioObjectKey = (occurrenceKey, audioId, mimeType) => {
  const normalizedId = normalizeLessonReplayAudioId(audioId);
  if (!normalizedId) return '';
  return [
    lessonReplayAudioS3Config.prefix,
    getLessonReplayOccurrenceHash(occurrenceKey),
    `${normalizedId}.${getLessonReplayAudioExtension(mimeType)}`,
  ].filter(Boolean).join('/');
};

const getLessonReplayAudioFolderPath = (occurrenceKey) => (
  path.join(lessonReplayAudioDir, getLessonReplayOccurrenceHash(occurrenceKey))
);

const getLessonReplayAudioLocalFilePath = (occurrenceKey, audioId, mimeType) => {
  const normalizedId = normalizeLessonReplayAudioId(audioId);
  if (!normalizedId) return '';
  return path.join(
    getLessonReplayAudioFolderPath(occurrenceKey),
    `${normalizedId}.${getLessonReplayAudioExtension(mimeType)}`
  );
};

const hasLessonReplayAudioDiskCapacity = (requiredBytes = 0) => {
  if (typeof fs.statfsSync !== 'function') return true;
  try {
    const stats = fs.statfsSync(lessonReplayAudioDir);
    const freeBytes = Number(stats.bavail) * Number(stats.bsize);
    return Number.isFinite(freeBytes)
      && freeBytes - Math.max(0, Number(requiredBytes) || 0) >= LESSON_REPLAY_AUDIO_MIN_FREE_BYTES;
  } catch {
    return true;
  }
};

const getLessonReplayFilePath = (occurrenceKey) => (
  path.join(lessonReplaysDir, `${getLessonReplayOccurrenceHash(occurrenceKey)}.json.gz`)
);

const getLessonReplaySnapshotFolderPath = (occurrenceKey) => (
  path.join(lessonReplaySnapshotsDir, getLessonReplayOccurrenceHash(occurrenceKey))
);

const normalizeLessonReplaySnapshotId = (value) => {
  const normalized = String(value || '').trim().toLowerCase();
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(normalized)
    ? normalized
    : '';
};

const getLessonReplaySnapshotExtension = (mimeType) => (
  String(mimeType || '').trim().toLowerCase() === 'image/jpeg' ? '.jpg' : '.webp'
);

const getLessonReplaySnapshotPath = (occurrenceKey, snapshotId, mimeType) => {
  const normalizedId = normalizeLessonReplaySnapshotId(snapshotId);
  if (!normalizedId) return '';
  return path.join(
    getLessonReplaySnapshotFolderPath(occurrenceKey),
    `${normalizedId}${getLessonReplaySnapshotExtension(mimeType)}`
  );
};

const getLessonReplayFolderUsageAsync = async (folderPath, filePattern) => {
  let entries = [];
  try {
    entries = await fs.promises.readdir(folderPath, { withFileTypes: true });
  } catch {
    return { count: 0, bytes: 0 };
  }
  const files = entries.filter((entry) => entry.isFile() && filePattern.test(entry.name));
  let bytes = 0;
  for (const entry of files) {
    try {
      const stats = await fs.promises.stat(path.join(folderPath, entry.name));
      bytes += Math.max(0, Number(stats.size) || 0);
    } catch {
      // Ignore a file that disappeared while the folder was inspected.
    }
  }
  return {
    count: files.length,
    bytes,
  };
};

const getLessonReplayCompressedBytesAsync = async (occurrenceKey) => {
  for (const candidate of [
    getLessonReplayFilePath(occurrenceKey),
    getLessonReplayBackupFilePath(occurrenceKey),
  ]) {
    try {
      const stats = await fs.promises.stat(candidate);
      return Math.max(0, Number(stats.size) || 0);
    } catch {
      // Try the backup or report an unknown size.
    }
  }
  return 0;
};

const reconcileLessonReplayStorageSummary = async (occurrenceKey) => {
  const normalizedKey = String(occurrenceKey || '').trim();
  if (!normalizedKey) return null;
  const occurrenceHash = getLessonReplayOccurrenceHash(normalizedKey);
  const [dataBytes, snapshotUsage, audioUsage] = await Promise.all([
    getLessonReplayCompressedBytesAsync(normalizedKey),
    getLessonReplayFolderUsageAsync(
      getLessonReplaySnapshotFolderPath(normalizedKey),
      /\.(?:webp|jpe?g)$/i
    ),
    getLessonReplayFolderUsageAsync(
      getLessonReplayAudioFolderPath(normalizedKey),
      /\.(?:webm|ogg|m4a)$/i
    ),
  ]);
  const latestIndexed = lessonReplayStorageIndexByHash.get(occurrenceHash);
  lessonReplayStorageReconciledHashes.add(occurrenceHash);
  return updateLessonReplayStorageIndex(normalizedKey, {
    dataBytes: Math.max(dataBytes, Number(latestIndexed?.dataBytes) || 0),
    snapshotBytes: Math.max(snapshotUsage.bytes, Number(latestIndexed?.snapshotBytes) || 0),
    audioBytes: Math.max(audioUsage.bytes, Number(latestIndexed?.audioBytes) || 0),
  });
};

const drainLessonReplayStorageReconcileQueue = async () => {
  if (lessonReplayStorageReconcileRunning) return;
  const next = lessonReplayStorageReconcileQueue.shift();
  if (!next) return;
  lessonReplayStorageReconcileRunning = true;
  try {
    await reconcileLessonReplayStorageSummary(next.occurrenceKey);
  } catch (error) {
    console.warn('[lesson-replay] failed to index stored media:', error?.message || error);
  } finally {
    lessonReplayStorageQueuedHashes.delete(next.hash);
    lessonReplayStorageReconcileRunning = false;
    lessonReplayStorageReconcileTimer = setTimeout(() => {
      lessonReplayStorageReconcileTimer = null;
      void drainLessonReplayStorageReconcileQueue();
    }, 25);
    if (typeof lessonReplayStorageReconcileTimer.unref === 'function') {
      lessonReplayStorageReconcileTimer.unref();
    }
  }
};

const queueLessonReplayStorageReconciliation = (occurrenceKey, options = {}) => {
  const normalizedKey = String(occurrenceKey || '').trim();
  if (!normalizedKey) return false;
  const hash = getLessonReplayOccurrenceHash(normalizedKey);
  if (
    lessonReplayStorageIndexByHash.has(hash)
    || lessonReplayStorageReconciledHashes.has(hash)
    || lessonReplayStorageQueuedHashes.has(hash)
  ) return false;
  lessonReplayStorageQueuedHashes.add(hash);
  const item = { occurrenceKey: normalizedKey, hash };
  if (options.priority === true) lessonReplayStorageReconcileQueue.unshift(item);
  else lessonReplayStorageReconcileQueue.push(item);
  if (!lessonReplayStorageReconcileRunning && !lessonReplayStorageReconcileTimer) {
    lessonReplayStorageReconcileTimer = setTimeout(() => {
      lessonReplayStorageReconcileTimer = null;
      void drainLessonReplayStorageReconcileQueue();
    }, 0);
    if (typeof lessonReplayStorageReconcileTimer.unref === 'function') {
      lessonReplayStorageReconcileTimer.unref();
    }
  }
  return true;
};

const ensureLessonReplaySnapshotCapacity = (requiredBytes, protectedOccurrenceKey = '') => {
  const required = Math.max(0, Number(requiredBytes) || 0);
  if (lessonReplaySnapshotStoredBytes + required <= LESSON_REPLAY_SNAPSHOT_MAX_TOTAL_BYTES) return true;
  lessonReplaySnapshotStoredBytes = getDirectorySizeBytes(lessonReplaySnapshotsDir);
  if (lessonReplaySnapshotStoredBytes + required <= LESSON_REPLAY_SNAPSHOT_MAX_TOTAL_BYTES) return true;

  const protectedHashes = new Set([
    getLessonReplayOccurrenceHash(protectedOccurrenceKey),
    ...Array.from(activeLessonReplaySessions.values())
      .map((session) => getLessonReplayOccurrenceHash(session?.occurrenceKey)),
  ].filter(Boolean));
  let candidates = [];
  try {
    candidates = fs.readdirSync(lessonReplaySnapshotsDir, { withFileTypes: true })
      .filter((entry) => entry.isDirectory() && /^[0-9a-f]{64}$/i.test(entry.name))
      .map((entry) => {
        const folderPath = path.resolve(lessonReplaySnapshotsDir, entry.name);
        try {
          return {
            hash: entry.name.toLowerCase(),
            folderPath,
            bytes: getDirectorySizeBytes(folderPath),
            modifiedAt: Number(fs.statSync(folderPath).mtimeMs) || 0,
          };
        } catch {
          return null;
        }
      })
      .filter(Boolean)
      .sort((left, right) => left.modifiedAt - right.modifiedAt);
  } catch {
    return false;
  }

  const rootPath = `${path.resolve(lessonReplaySnapshotsDir)}${path.sep}`;
  for (const candidate of candidates) {
    if (lessonReplaySnapshotStoredBytes + required <= LESSON_REPLAY_SNAPSHOT_MAX_TOTAL_BYTES) break;
    if (protectedHashes.has(candidate.hash) || !candidate.folderPath.startsWith(rootPath)) continue;
    try {
      fs.rmSync(candidate.folderPath, { recursive: true, force: true });
      setLessonReplayStorageIndexByHash(candidate.hash, { snapshotBytes: 0 });
      lessonReplaySnapshotStoredBytes = Math.max(
        0,
        lessonReplaySnapshotStoredBytes - candidate.bytes
      );
    } catch (error) {
      console.warn('[lesson-replay] failed to rotate old screen snapshots:', error?.message || error);
    }
  }
  return lessonReplaySnapshotStoredBytes + required <= LESSON_REPLAY_SNAPSHOT_MAX_TOTAL_BYTES;
};

const detectLessonReplaySnapshotMimeType = (buffer) => {
  if (!Buffer.isBuffer(buffer)) return '';
  const isWebp = buffer.length >= 12
    && buffer.subarray(0, 4).toString('ascii') === 'RIFF'
    && buffer.subarray(8, 12).toString('ascii') === 'WEBP';
  if (isWebp) return 'image/webp';
  const isJpeg = buffer.length >= 4
    && buffer[0] === 0xff
    && buffer[1] === 0xd8
    && buffer[buffer.length - 2] === 0xff
    && buffer[buffer.length - 1] === 0xd9;
  return isJpeg ? 'image/jpeg' : '';
};

const getLessonReplayBackupFilePath = (occurrenceKey) => `${getLessonReplayFilePath(occurrenceKey)}.bak`;

const withLessonReplayWriteLock = async (occurrenceKey, operation) => {
  const normalizedKey = String(occurrenceKey || '').trim();
  if (!normalizedKey) throw new Error('Lesson replay occurrence is required');
  const previous = lessonReplayWriteQueueByOccurrenceKey.get(normalizedKey) || Promise.resolve();
  const current = previous.catch(() => null).then(operation);
  lessonReplayWriteQueueByOccurrenceKey.set(normalizedKey, current);
  try {
    return await current;
  } finally {
    if (lessonReplayWriteQueueByOccurrenceKey.get(normalizedKey) === current) {
      lessonReplayWriteQueueByOccurrenceKey.delete(normalizedKey);
    }
  }
};

const readLessonReplayFile = (filePath, occurrenceKey) => {
  const compressed = fs.readFileSync(filePath);
  if (compressed.length > LESSON_REPLAY_MAX_COMPRESSED_BYTES) {
    throw new Error('Compressed lesson replay exceeds the storage limit');
  }
  const raw = zlib.gunzipSync(compressed, { maxOutputLength: LESSON_REPLAY_MAX_FILE_BYTES });
  if (raw.length > LESSON_REPLAY_MAX_FILE_BYTES) {
    throw new Error('Lesson replay exceeds the storage limit');
  }
  const parsed = JSON.parse(raw.toString('utf8'));
  const replay = normalizeLessonReplay(parsed);
  return replay.occurrence.key === occurrenceKey ? replay : null;
};

const readLessonReplay = (occurrenceKey) => {
  const normalizedKey = String(occurrenceKey || '').trim();
  if (!normalizedKey) return null;
  const cached = lessonReplayCacheByOccurrenceKey.get(normalizedKey);
  if (cached) return cached;
  const filePath = getLessonReplayFilePath(normalizedKey);
  const backupPath = getLessonReplayBackupFilePath(normalizedKey);
  for (const candidate of [filePath, backupPath]) {
    try {
      if (!fs.existsSync(candidate)) continue;
      const replay = readLessonReplayFile(candidate, normalizedKey);
      if (replay) return replay;
    } catch (error) {
      console.warn('[lesson-replay] failed to read replay file:', path.basename(candidate), error?.message || error);
    }
  }
  return null;
};

const getLessonReplayCompressedBytes = (occurrenceKey) => {
  for (const candidate of [
    getLessonReplayFilePath(occurrenceKey),
    getLessonReplayBackupFilePath(occurrenceKey),
  ]) {
    try {
      return fs.statSync(candidate).size;
    } catch {
      // Try the backup or report an unknown size.
    }
  }
  return 0;
};

const persistLessonReplay = (normalized) => {
  const startedAt = Date.now();
  const filePath = getLessonReplayFilePath(normalized.occurrence.key);
  const backupPath = getLessonReplayBackupFilePath(normalized.occurrence.key);
  const raw = Buffer.from(JSON.stringify(normalized), 'utf8');
  if (raw.length > LESSON_REPLAY_MAX_FILE_BYTES) throw new Error('Lesson replay exceeds the storage limit');
  // Replays are rewritten throughout a live lesson. Fast compression keeps the
  // single server CPU available for the call while retaining almost all gzip savings.
  const compressed = zlib.gzipSync(raw, { level: 1 });
  if (compressed.length > LESSON_REPLAY_MAX_COMPRESSED_BYTES) {
    throw new Error('Compressed lesson replay exceeds the storage limit');
  }
  const tempPath = `${filePath}.${process.pid}.${Date.now()}.${crypto.randomBytes(6).toString('hex')}.tmp`;
  fs.writeFileSync(tempPath, compressed);
  let previousMoved = false;
  try {
    if (fs.existsSync(filePath)) {
      if (fs.existsSync(backupPath)) fs.unlinkSync(backupPath);
      fs.renameSync(filePath, backupPath);
      previousMoved = true;
    }
    fs.renameSync(tempPath, filePath);
  } catch (error) {
    try {
      if (previousMoved && !fs.existsSync(filePath) && fs.existsSync(backupPath)) {
        fs.renameSync(backupPath, filePath);
      }
    } catch (restoreError) {
      console.error('[lesson-replay] failed to restore the previous replay:', restoreError?.message || restoreError);
    }
    try { if (fs.existsSync(tempPath)) fs.unlinkSync(tempPath); } catch {
      // A failed temporary-file cleanup does not replace the original write error.
    }
    throw error;
  }
  if (previousMoved && fs.existsSync(backupPath)) {
    try {
      fs.unlinkSync(backupPath);
    } catch (error) {
      console.warn('[lesson-replay] failed to remove an old replay backup:', error?.message || error);
    }
  }
  const occurrenceHash = getLessonReplayOccurrenceHash(normalized.occurrence.key);
  const existingStorage = lessonReplayStorageIndexByHash.get(occurrenceHash);
  const replayStorage = existingStorage
    ? { dataBytes: compressed.length }
    : summarizeLessonReplayStorage(normalized, {
        normalized: true,
        dataBytes: compressed.length,
      });
  updateLessonReplayStorageIndex(normalized.occurrence.key, replayStorage);
  lessonReplayStorageReconciledHashes.add(occurrenceHash);
  const elapsedMs = Date.now() - startedAt;
  if (elapsedMs >= 200) {
    console.warn(`[perf] lesson replay persist took ${elapsedMs}ms (${raw.length} raw, ${compressed.length} gzip)`);
  }
  return {
    replay: normalized,
    compressedBytes: compressed.length,
  };
};

const scheduleLessonReplayPersistence = (occurrenceKey) => {
  if (lessonReplayPersistTimerByOccurrenceKey.has(occurrenceKey)) return;
  const failure = lessonReplayPersistFailureByOccurrenceKey.get(occurrenceKey);
  const retryDelayMs = failure
    ? Math.max(0, Number(failure.nextRetryAt) - Date.now())
    : 0;
  const timer = setTimeout(() => {
    lessonReplayPersistTimerByOccurrenceKey.delete(occurrenceKey);
    void withLessonReplayWriteLock(occurrenceKey, () => {
      const latest = lessonReplayCacheByOccurrenceKey.get(occurrenceKey);
      return latest ? persistLessonReplay(latest) : null;
    }).then(() => {
      lessonReplayPersistFailureByOccurrenceKey.delete(occurrenceKey);
      const hasActiveOccurrenceSession = Array.from(activeLessonReplaySessions.values())
        .some((session) => session.occurrenceKey === occurrenceKey && !session.closing);
      if (!hasActiveOccurrenceSession) lessonReplayCacheByOccurrenceKey.delete(occurrenceKey);
    }).catch((error) => {
      console.error('[lesson-replay] deferred persistence failed:', error?.message || error);
      const previous = lessonReplayPersistFailureByOccurrenceKey.get(occurrenceKey);
      const attempts = Math.min(12, Math.max(0, Number(previous?.attempts) || 0) + 1);
      const delayMs = Math.min(
        LESSON_REPLAY_PERSIST_MAX_RETRY_MS,
        LESSON_REPLAY_PERSIST_INTERVAL_MS * (2 ** Math.min(4, attempts))
      );
      lessonReplayPersistFailureByOccurrenceKey.set(occurrenceKey, {
        attempts,
        nextRetryAt: Date.now() + delayMs,
      });
      scheduleLessonReplayPersistence(occurrenceKey);
    });
  }, Math.max(LESSON_REPLAY_PERSIST_INTERVAL_MS, retryDelayMs));
  if (typeof timer.unref === 'function') timer.unref();
  lessonReplayPersistTimerByOccurrenceKey.set(occurrenceKey, timer);
};

const writeLessonReplay = (replay, options = {}) => {
  const normalized = options.normalized === true
    ? replay
    : appendLessonReplayEvents(replay, [], {
      maxBytes: LESSON_REPLAY_MAX_FILE_BYTES,
    }).replay;
  const occurrenceKey = normalized.occurrence.key;
  if (!occurrenceKey || !normalized.occurrence.studentId) {
    throw new Error('Lesson replay occurrence is required');
  }
  lessonReplayStorageSummaryCacheByOccurrenceKey.delete(occurrenceKey);
  lessonReplayCacheByOccurrenceKey.set(occurrenceKey, normalized);
  if (options.deferred === true) {
    scheduleLessonReplayPersistence(occurrenceKey);
    return {
      replay: normalized,
      compressedBytes: getLessonReplayCompressedBytes(occurrenceKey),
      deferred: true,
    };
  }
  const pendingTimer = lessonReplayPersistTimerByOccurrenceKey.get(occurrenceKey);
  if (pendingTimer) clearTimeout(pendingTimer);
  lessonReplayPersistTimerByOccurrenceKey.delete(occurrenceKey);
  const stored = persistLessonReplay(normalized);
  lessonReplayPersistFailureByOccurrenceKey.delete(occurrenceKey);
  return stored;
};

const getLessonReplaySummary = (occurrenceKey, replayOverride = null) => {
  const replay = replayOverride || readLessonReplay(occurrenceKey);
  if (!replay) return { available: false, eventCount: 0, durationMs: 0, eventTypes: [], bytes: 0, updatedAt: '' };
  let compressedBytes = 0;
  try {
    compressedBytes = fs.statSync(getLessonReplayFilePath(occurrenceKey)).size;
  } catch {
    try {
      compressedBytes = fs.statSync(getLessonReplayBackupFilePath(occurrenceKey)).size;
    } catch {
      // A missing stat only means the compressed size is unknown.
    }
  }
  return summarizeLessonReplay(replay, compressedBytes, { normalized: true });
};

const getLessonReplayStorageSummary = (occurrenceKey, options = {}) => {
  const normalizedKey = String(occurrenceKey || '').trim();
  if (!normalizedKey) return null;
  const occurrenceHash = getLessonReplayOccurrenceHash(normalizedKey);
  if (lessonReplayStorageSummaryCacheByOccurrenceKey.has(normalizedKey)) {
    return lessonReplayStorageSummaryCacheByOccurrenceKey.get(normalizedKey);
  }
  const indexed = lessonReplayStorageIndexByHash.get(occurrenceHash);
  if (indexed) {
    lessonReplayStorageReconciledHashes.add(occurrenceHash);
    lessonReplayStorageSummaryCacheByOccurrenceKey.set(normalizedKey, indexed);
    return indexed;
  }
  queueLessonReplayStorageReconciliation(normalizedKey, options);
  return null;
};

