const withWorkbookSolutionWriteLock = async (solutionKey, operation) => {
  const normalizedKey = String(solutionKey || '').trim();
  if (!normalizedKey) throw new Error('Workbook solution key is required');
  const previous = workbookSolutionWriteQueues.get(normalizedKey) || Promise.resolve();
  const current = previous.catch(() => null).then(operation);
  workbookSolutionWriteQueues.set(normalizedKey, current);
  try {
    return await current;
  } finally {
    if (workbookSolutionWriteQueues.get(normalizedKey) === current) {
      workbookSolutionWriteQueues.delete(normalizedKey);
    }
  }
};

const getWorkbookStoredFilePath = (entry) => {
  const storageName = String(
    entry?.workbookQuestionVirtualSource === true
      ? entry?.workbookQuestionStorageName
      : entry?.storageName
  ).trim();
  const safeStorageName = path.basename(storageName);
  if (!safeStorageName || safeStorageName !== storageName) return '';
  const filePath = path.join(uploadsDir, safeStorageName);
  return fs.existsSync(filePath) ? filePath : '';
};

const getWorkbookFileContentHash = (entry) => {
  const storedHash = normalizeWorkbookContentHash(entry?.workbookContentHash);
  if (storedHash) return storedHash;
  const filePath = getWorkbookStoredFilePath(entry);
  if (!filePath) return '';
  return crypto.createHash('sha256').update(fs.readFileSync(filePath)).digest('hex');
};

const isWorkbookFileAccessibleToStudent = (student, entry) => {
  if (!student || !entry) return false;
  if (isLessonSharedFile(entry)) {
    return Boolean(
      normalizeTeacherId(student.teacherId)
      && normalizeTeacherId(entry.teacherId) === normalizeTeacherId(student.teacherId)
    );
  }
  return String(entry.studentId || '').trim() === String(student.id || '').trim();
};

const normalizeWorkbookSolutionKey = (value) => {
  const normalized = String(value || '').trim().toLowerCase();
  return /^[0-9a-f]{64}$/.test(normalized) ? normalized : '';
};

const findWorkbookSolutionEntry = (
  files,
  studentId,
  sourceFileId,
  solutionKey,
  solutionFileId = ''
) => {
  const normalizedStudentId = String(studentId || '').trim();
  const normalizedSourceFileId = String(sourceFileId || '').trim();
  const normalizedSolutionKey = normalizeWorkbookSolutionKey(solutionKey);
  const normalizedSolutionFileId = String(solutionFileId || '').trim();
  const legacySolutionKey = buildWorkbookSolutionKey(normalizedStudentId, normalizedSourceFileId);
  const list = Array.isArray(files) ? files : [];
  const candidates = list.filter((entry) => (
    !isLessonSharedFile(entry)
    && String(entry?.studentId || '').trim() === normalizedStudentId
    && String(entry?.workbookSourceFileId || '').trim() === normalizedSourceFileId
  ));
  const getCandidateKey = (entry) => (
    normalizeWorkbookSolutionKey(entry?.workbookSolutionKey) || legacySolutionKey
  );
  if (normalizedSolutionFileId) {
    const exact = candidates.find((entry) => String(entry?.id || '').trim() === normalizedSolutionFileId);
    if (!exact) return null;
    return !normalizedSolutionKey || getCandidateKey(exact) === normalizedSolutionKey ? exact : null;
  }
  if (!normalizedSolutionKey) return null;
  return candidates.find((entry) => getCandidateKey(entry) === normalizedSolutionKey) || null;
};

const resolveWorkbookSourceForStudent = (student, requestedFileId, filesOverride = null) => {
  const files = Array.isArray(filesOverride) ? filesOverride : readFilesDb();
  const requestedId = String(requestedFileId || '').trim();
  const launchFile = files.find((entry) => String(entry?.id || '').trim() === requestedId);
  if (!launchFile || !isWorkbookFileAccessibleToStudent(student, launchFile)) return null;
  const sourceFileId = String(launchFile.workbookSourceFileId || launchFile.id || '').trim();
  const sourceFile = files.find((entry) => String(entry?.id || '').trim() === sourceFileId);
  if (
    !sourceFile
    || !isWorkbookFileAccessibleToStudent(student, sourceFile)
    || !isWorkbookFileName(sourceFile.name)
    || !getWorkbookStoredFilePath(sourceFile)
  ) return null;
  const solutionFile = String(launchFile.workbookSourceFileId || '').trim()
    ? launchFile
    : null;
  const solutionKey = solutionFile
    ? (normalizeWorkbookSolutionKey(solutionFile.workbookSolutionKey)
      || buildWorkbookSolutionKey(student.id, sourceFile.id))
    : buildWorkbookSolutionKey(student.id, sourceFile.id);
  if (!solutionKey) return null;
  return {
    files,
    launchFile,
    sourceFile,
    sourceFileId: sourceFile.id,
    solutionKey,
    solutionFile,
    solutionFileId: String(solutionFile?.id || ''),
  };
};

const getWorkbookBindingState = (student, sourceFile, filesOverride = null, binding = {}) => {
  const files = Array.isArray(filesOverride) ? filesOverride : readFilesDb();
  const solutionKey = normalizeWorkbookSolutionKey(binding.solutionKey)
    || buildWorkbookSolutionKey(student?.id, sourceFile?.id);
  const solutionFileId = String(binding.solutionFileId || '').trim();
  const solutionFile = findWorkbookSolutionEntry(
    files,
    student?.id,
    sourceFile?.id,
    solutionKey,
    solutionFileId
  );
  const contentFile = solutionFile || sourceFile;
  const revision = solutionFile
    ? Math.max(0, Math.floor(Number(solutionFile.workbookRevision) || 0))
    : 0;
  return {
    files,
    solutionKey,
    solutionFileId: String(solutionFile?.id || solutionFileId),
    solutionFile,
    contentFile,
    revision,
    contentHash: getWorkbookFileContentHash(contentFile),
    fileName: String(solutionFile?.name || '').trim() || buildWorkbookSolutionName(sourceFile?.name),
    nameRequired: Boolean(binding.nameRequired && !solutionFile),
  };
};

const getWorkbookLaunchContent = (sourceFile, state, startsFresh = false) => {
  const launchFile = startsFresh ? sourceFile : state?.contentFile;
  const contentHash = getWorkbookFileContentHash(launchFile);
  return launchFile && getWorkbookStoredFilePath(launchFile) && contentHash
    ? { launchFile, contentHash }
    : null;
};

const normalizeWorkbookSolutionFolderName = (value) => String(value || '')
  .trim()
  .toLocaleLowerCase('ru-RU')
  .replace(/ё/g, 'е');

const ensureWorkbookSolutionFolder = ({ studentId, taskNumber, category }) => {
  const normalizedStudentId = String(studentId || '').trim();
  const normalizedCategory = String(category || '').trim();
  const normalizedTaskNumber = Number(taskNumber);
  if (!normalizedStudentId || !normalizedCategory || !Number.isFinite(normalizedTaskNumber)) {
    const error = new Error('Не удалось определить папку решения');
    error.statusCode = 400;
    throw error;
  }
  const folders = readFoldersDb();
  const targetName = normalizeWorkbookSolutionFolderName(WORKBOOK_HELPER_SOLUTION_FOLDER);
  const existing = folders.find((folder) => (
    String(folder?.studentId || '').trim() === normalizedStudentId
    && Number(folder?.taskNumber) === normalizedTaskNumber
    && String(folder?.category || '').trim() === normalizedCategory
    && !normalizeParentFolderId(folder?.parentFolderId)
    && normalizeWorkbookSolutionFolderName(folder?.name) === targetName
  ));
  if (existing) return existing;
  const created = {
    id: crypto.randomUUID(),
    studentId: normalizedStudentId,
    taskNumber: normalizedTaskNumber,
    category: normalizedCategory,
    parentFolderId: null,
    name: WORKBOOK_HELPER_SOLUTION_FOLDER,
    date: new Date().toLocaleDateString('ru-RU'),
  };
  folders.unshift(created);
  writeFoldersDb(folders);
  return created;
};

const createWorkbookHttpError = (statusCode, message, details = {}) => {
  const error = new Error(message);
  error.statusCode = statusCode;
  Object.assign(error, details);
  return error;
};

const WORKBOOK_QUESTION_CATEGORY = 'testing';
const WORKBOOK_QUESTION_TEXT_EXTENSIONS = new Set(['.txt', '.csv', '.tsv']);
const WORKBOOK_HELPER_SOURCE_TEXT_MAX_BYTES = 16 * 1024 * 1024;
const BLANK_QUESTION_FODS = `<?xml version="1.0" encoding="UTF-8"?>
<office:document xmlns:office="urn:oasis:names:tc:opendocument:xmlns:office:1.0" xmlns:table="urn:oasis:names:tc:opendocument:xmlns:table:1.0" xmlns:text="urn:oasis:names:tc:opendocument:xmlns:text:1.0" office:mimetype="application/vnd.oasis.opendocument.spreadsheet" office:version="1.3"><office:body><office:spreadsheet><table:table table:name="Лист1"><table:table-row><table:table-cell office:value-type="string"><text:p/></table:table-cell></table:table-row></table:table></office:spreadsheet></office:body></office:document>`;

const normalizeWorkbookQuestionValue = (value, maxLength = 240) => (
  String(value ?? '').replace(/\0/g, '').trim().slice(0, maxLength)
);

const isWorkbookQuestionVirtualSource = (entry) => (
  entry?.workbookQuestionVirtualSource === true
);

const isWorkbookTextAttachment = (taskNumber, fileName) => (
  [26, 27].includes(Number(taskNumber))
  && WORKBOOK_QUESTION_TEXT_EXTENSIONS.has(path.extname(String(fileName || '')).toLowerCase())
);

const workbookQuestionContextMatches = (value, target, { includeAttachment = true } = {}) => {
  const context = value && typeof value === 'object' && !Array.isArray(value) ? value : {};
  if (Number(context.taskNumber) !== Number(target?.taskNumber)) return false;
  if (String(context.levelId || '') !== String(target?.levelId || '')) return false;
  if (String(context.questionId || '') !== String(target?.questionId || '')) return false;
  return !includeAttachment
    || String(context.attachmentId || '') === String(target?.attachmentId || '');
};

const getWorkbookQuestionTarget = ({ student, taskNumber, levelId, questionId, attachmentId }) => {
  const taskNum = Number(taskNumber);
  const normalizedLevelId = normalizeWorkbookQuestionValue(levelId, 100);
  const normalizedQuestionId = normalizeWorkbookQuestionValue(questionId, 160);
  const requestedAttachmentId = normalizeWorkbookQuestionValue(attachmentId, 240);
  if (!Number.isFinite(taskNum) || !normalizedLevelId || !normalizedQuestionId || !requestedAttachmentId) {
    throw createWorkbookHttpError(400, 'Некорректные параметры задания');
  }
  const studentData = getStudentData(student.id);
  const testsDb = getTestsDbWithStudentMockFollowups(studentData);
  const { taskLevels, questions, question } = getQuestionEntryFromTestsDb(
    testsDb,
    taskNum,
    normalizedLevelId,
    normalizedQuestionId
  );
  if (!taskLevels) throw createWorkbookHttpError(404, 'Задание не найдено');
  if (!questions) throw createWorkbookHttpError(404, 'Уровень не найден');
  if (!question) throw createWorkbookHttpError(404, 'Вопрос не найден');
  const attachments = Array.isArray(question.files) ? question.files : [];
  const attachment = attachments.find((file) => {
    const ids = [file?.id, file?.storageName]
      .map((value) => normalizeWorkbookQuestionValue(value, 240))
      .filter(Boolean);
    return ids.includes(requestedAttachmentId);
  });
  if (!attachment) throw createWorkbookHttpError(404, 'Файл не найден в этом вопросе');
  const storageName = path.basename(String(attachment.storageName || '').trim());
  if (!storageName || storageName !== String(attachment.storageName || '').trim()) {
    throw createWorkbookHttpError(400, 'Некорректный файл задания');
  }
  const attachmentPath = path.join(uploadsDir, storageName);
  if (!fs.existsSync(attachmentPath)) {
    throw createWorkbookHttpError(410, 'Файл задания больше недоступен');
  }
  const attachmentName = path.basename(
    normalizeFileName(attachment.name || stripUploadIdPrefix(storageName)) || 'Задание'
  );
  const blankForTextTask = isWorkbookTextAttachment(taskNum, attachmentName);
  if (!isWorkbookFileName(attachmentName) && !blankForTextTask) {
    throw createWorkbookHttpError(415, 'Для этого файла доступно только скачивание');
  }
  const attachmentKey = normalizeWorkbookQuestionValue(attachment.id || storageName, 240);
  const questionIndex = questions.findIndex((entry) => (
    String(entry?.id ?? '').trim() === normalizedQuestionId
  ));
  return {
    attachment,
    attachmentName,
    attachmentPath,
    attachmentStorageName: storageName,
    blankForTextTask,
    context: {
      taskNumber: taskNum,
      levelId: normalizedLevelId,
      questionId: normalizedQuestionId,
      questionNumber: questionIndex >= 0 ? questionIndex + 1 : null,
      attachmentId: attachmentKey,
      attachmentName,
      mode: blankForTextTask ? 'text-to-workbook' : 'workbook',
    },
  };
};

const ensureWorkbookQuestionSource = ({ student, target }) => {
  let files = readFilesDb();
  const context = target.context;
  const sourceIndex = files.findIndex((entry) => (
    isWorkbookQuestionVirtualSource(entry)
    && String(entry?.studentId || '').trim() === String(student.id || '').trim()
    && workbookQuestionContextMatches(entry?.workbookQuestionContext, context)
  ));
  const existing = sourceIndex >= 0 ? files[sourceIndex] : null;
  let sourceStorageName = target.attachmentStorageName;
  let sourceName = target.attachmentName;
  if (target.blankForTextTask) {
    const existingStorageName = path.basename(String(existing?.workbookQuestionStorageName || '').trim());
    const existingPath = existingStorageName ? path.join(uploadsDir, existingStorageName) : '';
    if (existingPath && fs.existsSync(existingPath)) {
      sourceStorageName = existingStorageName;
    } else {
      sourceStorageName = `${crypto.randomUUID()}-task-${context.taskNumber}-${context.questionNumber || 'question'}.fods`;
      fs.writeFileSync(path.join(uploadsDir, sourceStorageName), BLANK_QUESTION_FODS, 'utf8');
    }
    sourceName = `Задание ${context.taskNumber}${context.questionNumber ? ` №${context.questionNumber}` : ''} — таблица.fods`;
  }
  const nowIso = new Date().toISOString();
  const source = {
    ...(existing || {}),
    id: existing?.id || crypto.randomUUID(),
    studentId: student.id,
    taskNumber: context.taskNumber,
    category: WORKBOOK_QUESTION_CATEGORY,
    folderId: null,
    folderName: null,
    name: sourceName,
    size: target.blankForTextTask ? formatSize(Buffer.byteLength(BLANK_QUESTION_FODS)) : String(target.attachment?.size || ''),
    sizeBytes: 0,
    originalSizeBytes: Math.max(0, Number(target.attachment?.sizeBytes) || 0),
    date: existing?.date || new Date(nowIso).toLocaleDateString('ru-RU'),
    createdAt: existing?.createdAt || nowIso,
    updatedAt: nowIso,
    source: 'test-question-workbook',
    workbookQuestionVirtualSource: true,
    workbookQuestionStorageName: sourceStorageName,
    workbookQuestionContext: context,
    memory: normalizeFileMemory({
      ...(existing?.memory && typeof existing.memory === 'object' ? existing.memory : {}),
      kind: 'workbook-question-source',
      source: 'test-question-workbook',
      title: sourceName.replace(/\.[^.]+$/, ''),
      taskNumber: context.taskNumber,
      createdAt: existing?.memory?.createdAt || existing?.createdAt || nowIso,
    }, {
      taskNumber: context.taskNumber,
      source: 'test-question-workbook',
      createdAt: existing?.createdAt || nowIso,
    }),
  };
  if (sourceIndex >= 0) files[sourceIndex] = source;
  else files.unshift(source);
  writeFilesDb(files);
  return { files, source };
};

const ensureWorkbookTextMaterialSource = ({ student, textFile, files: filesOverride }) => {
  const files = Array.isArray(filesOverride) ? filesOverride : readFilesDb();
  const sourceMarker = String(textFile?.id || '').trim();
  let source = files.find((entry) => (
    String(entry?.workbookTextSourceFileId || entry?.workbookTask26TextSourceFileId || '').trim() === sourceMarker
    && String(entry?.studentId || '').trim() === String(student?.id || '').trim()
  ));
  const storageName = path.basename(String(source?.workbookQuestionStorageName || '').trim())
    || `workbook-text-${crypto.randomUUID()}.fods`;
  const storagePath = path.join(uploadsDir, storageName);
  if (!fs.existsSync(storagePath)) fs.writeFileSync(storagePath, BLANK_QUESTION_FODS, 'utf8');
  const nowIso = new Date().toISOString();
  const sourceName = `${path.basename(String(textFile?.name || 'Задание'), path.extname(String(textFile?.name || '')))} — таблица.fods`;
  source = {
    ...(source || {}),
    id: source?.id || crypto.randomUUID(),
    studentId: String(student.id),
    taskNumber: Number(textFile?.taskNumber),
    category: String(textFile?.category || 'class'),
    folderId: textFile?.folderId || null,
    folderName: textFile?.folderName || null,
    name: sourceName,
    size: formatSize(Buffer.byteLength(BLANK_QUESTION_FODS)),
    sizeBytes: Buffer.byteLength(BLANK_QUESTION_FODS),
    date: source?.date || new Date(nowIso).toLocaleDateString('ru-RU'),
    createdAt: source?.createdAt || nowIso,
    updatedAt: nowIso,
    workbookQuestionVirtualSource: true,
    workbookQuestionStorageName: storageName,
    workbookTextSourceFileId: sourceMarker,
    workbookContentHash: crypto.createHash('sha256').update(BLANK_QUESTION_FODS).digest('hex'),
  };
  const sourceIndex = files.findIndex((entry) => entry?.id === source.id);
  if (sourceIndex >= 0) files[sourceIndex] = source;
  else files.unshift(source);
  writeFilesDb(files);
  return { files, source };
};

const resolveWorkbookHelperSourceText = ({ student, sourceFile, files: filesOverride }) => {
  if (!student || !sourceFile) return null;
  const files = Array.isArray(filesOverride) ? filesOverride : readFilesDb();
  const materialSourceFileId = String(
    sourceFile?.workbookTextSourceFileId || sourceFile?.workbookTask26TextSourceFileId || ''
  ).trim();
  if (materialSourceFileId) {
    const textFile = files.find((entry) => String(entry?.id || '').trim() === materialSourceFileId);
    if (
      !textFile
      || !isWorkbookFileAccessibleToStudent(student, textFile)
      || !isWorkbookTextAttachment(textFile.taskNumber, textFile.name)
    ) return null;
    const filePath = getWorkbookStoredFilePath(textFile);
    if (!filePath) return null;
    const stat = fs.statSync(filePath);
    if (!stat.isFile()) return null;
    return {
      filePath,
      fileName: path.basename(normalizeFileName(textFile.name) || `Задание ${textFile.taskNumber}.txt`),
      sizeBytes: stat.size,
    };
  }

  const context = sourceFile?.workbookQuestionContext;
  if (!['task-26-text', 'text-to-workbook'].includes(context?.mode)) return null;
  try {
    const target = getWorkbookQuestionTarget({
      student,
      taskNumber: context.taskNumber,
      levelId: context.levelId,
      questionId: context.questionId,
      attachmentId: context.attachmentId,
    });
    if (!target.blankForTextTask || !target.attachmentPath) return null;
    const stat = fs.statSync(target.attachmentPath);
    if (!stat.isFile()) return null;
    return {
      filePath: target.attachmentPath,
      fileName: path.basename(normalizeFileName(target.attachmentName) || `Задание ${context.taskNumber}.txt`),
      sizeBytes: stat.size,
    };
  } catch {
    return null;
  }
};

const serializeWorkbookHelperSourceText = async (sourceText) => {
  if (!sourceText) return null;
  if (sourceText.sizeBytes > WORKBOOK_HELPER_SOURCE_TEXT_MAX_BYTES) {
    throw createWorkbookHttpError(413, 'Текстовый файл больше допустимых 16 МБ');
  }
  return new Promise((resolve, reject) => {
    const hash = crypto.createHash('sha256');
    const stream = fs.createReadStream(sourceText.filePath);
    let sizeBytes = 0;
    stream.on('data', (chunk) => {
      sizeBytes += chunk.length;
      if (sizeBytes > WORKBOOK_HELPER_SOURCE_TEXT_MAX_BYTES) {
        stream.destroy(createWorkbookHttpError(413, 'Текстовый файл больше допустимых 16 МБ'));
        return;
      }
      hash.update(chunk);
    });
    stream.once('error', reject);
    stream.once('end', () => resolve({
      fileName: sourceText.fileName,
      sizeBytes,
      contentHash: hash.digest('hex'),
      contentPath: '/workbook-helper/v1/source-text',
    }));
  });
};

const MAX_WORKBOOK_QUESTION_SOLUTIONS = 3;

const buildWorkbookQuestionSolutionKey = (studentId, sourceFileId, slot = 1) => (
  Number(slot) <= 1
    ? buildWorkbookSolutionKey(studentId, sourceFileId)
    : buildWorkbookSolutionKey(studentId, `${sourceFileId}:question-solution:${slot}`)
);

const getWorkbookQuestionSolutionEntries = (files, studentId, sourceFileId) => {
  const usedSlots = new Set();
  return (Array.isArray(files) ? files : [])
    .filter((entry) => (
      entry?.workbookQuestionSolution === true
      && String(entry?.studentId || '').trim() === String(studentId || '').trim()
      && String(entry?.workbookSourceFileId || '').trim() === String(sourceFileId || '').trim()
    ))
    .sort((left, right) => (
      Date.parse(String(left?.createdAt || left?.updatedAt || ''))
      - Date.parse(String(right?.createdAt || right?.updatedAt || ''))
    ))
    .map((entry) => {
      let slot = Math.floor(Number(entry?.workbookQuestionSolutionSlot) || 0);
      if (slot < 1 || slot > MAX_WORKBOOK_QUESTION_SOLUTIONS || usedSlots.has(slot)) {
        slot = Array.from({ length: MAX_WORKBOOK_QUESTION_SOLUTIONS }, (_, index) => index + 1)
          .find((candidate) => !usedSlots.has(candidate)) || 0;
      }
      if (slot) usedSlots.add(slot);
      return { entry, slot };
    })
    .filter(({ slot }) => slot > 0);
};

const buildWorkbookQuestionSolutionName = (sourceName, slot = 1) => {
  const baseName = buildWorkbookSolutionName(sourceName);
  if (Number(slot) <= 1) return baseName;
  const extension = path.extname(baseName);
  return `${path.basename(baseName, extension)} ${slot}${extension}`;
};

const serializeWorkbookQuestionSolution = (entry, slot = entry?.workbookQuestionSolutionSlot || 1) => ({
  fileId: String(entry?.id || ''),
  sourceFileId: String(entry?.workbookSourceFileId || ''),
  attachmentId: String(entry?.workbookQuestionContext?.attachmentId || ''),
  name: String(entry?.name || ''),
  revision: Math.max(0, Math.floor(Number(entry?.workbookRevision) || 0)),
  slot: Math.max(1, Math.floor(Number(slot) || 1)),
  updatedAt: String(entry?.updatedAt || entry?.createdAt || ''),
});

const assertWorkbookSolutionCapacity = ({ files, existing, student, sourceFile, folder, sizeBytes }) => {
  const normalizedSizeBytes = Math.max(0, Number(sizeBytes) || 0);
  const fileLimitBytes = getUploadFileLimitBytes(false);
  if (!normalizedSizeBytes || normalizedSizeBytes > fileLimitBytes) {
    throw createWorkbookHttpError(413, getUploadFileLimitError(fileLimitBytes));
  }
  const currentTaskTotal = files
    .filter((entry) => (
      entry?.id !== existing?.id
      && String(entry?.studentId || '').trim() === String(student.id || '').trim()
      && Number(entry?.taskNumber) === Number(sourceFile.taskNumber)
    ))
    .reduce((sum, entry) => sum + getEntrySizeBytes(entry), 0);
  const taskLimitBytes = getTaskLimitBytes(false);
  if (currentTaskTotal + normalizedSizeBytes > taskLimitBytes) {
    throw createWorkbookHttpError(413, getTaskLimitError(taskLimitBytes));
  }
  const folderLimitBytes = getFolderLimitBytes(false);
  const currentFolderTotal = files
    .filter((entry) => entry?.id !== existing?.id && entry?.folderId === folder.id)
    .reduce((sum, entry) => sum + getEntrySizeBytes(entry), 0);
  if (currentFolderTotal + normalizedSizeBytes > folderLimitBytes) {
    throw createWorkbookHttpError(413, getFolderLimitError(folderLimitBytes));
  }
};

const removeWorkbookUploadedFile = (uploadedFile) => {
  const filePath = String(uploadedFile?.path || '').trim();
  if (!filePath) return;
  try {
    if (fs.existsSync(filePath)) fs.unlinkSync(filePath);
  } catch {
    // A failed temporary upload cleanup must not hide the original response.
  }
};

const upsertWorkbookSolutionContent = ({
  student,
  sourceFileId,
  uploadedFile,
  actor,
  source = 'workbook-auto-sync',
  memory: incomingMemory = {},
  expectedRevision,
  providedContentHash = '',
  solutionKey: requestedSolutionKey = '',
  solutionFileId: requestedSolutionFileId = '',
  solutionName: requestedSolutionName = '',
  requireSolutionName = false,
  requiredHelperSessionId = '',
  requiredHelperTokenHash = '',
} = {}) => {
  const requestedSourceFileId = String(sourceFileId || '').trim();
  const initialResolved = resolveWorkbookSourceForStudent(student, requestedSourceFileId);
  const normalizedSourceFileId = String(initialResolved?.sourceFile?.id || '').trim();
  const solutionKey = normalizeWorkbookSolutionKey(requestedSolutionKey)
    || normalizeWorkbookSolutionKey(initialResolved?.solutionKey);
  const solutionFileId = String(requestedSolutionFileId || initialResolved?.solutionFileId || '').trim();
  if (!normalizedSourceFileId || !solutionKey) {
    removeWorkbookUploadedFile(uploadedFile);
    return Promise.reject(createWorkbookHttpError(400, 'Некорректная привязка таблицы'));
  }
  return withWorkbookSolutionWriteLock(solutionKey, () => {
    try {
      if (requiredHelperSessionId || requiredHelperTokenHash) {
        const activeHelperSession = readWorkbookHelperSessionsDb().find((session) => (
          session.id === requiredHelperSessionId
           && session.tokenHash === requiredHelperTokenHash
           && session.studentId === String(student?.id || '').trim()
           && session.sourceFileId === normalizedSourceFileId
           && session.solutionKey === solutionKey
         ));
        if (!activeHelperSession) {
          throw createWorkbookHttpError(401, 'Привязка таблицы была отключена');
        }
      }
      if (!uploadedFile?.path || !fs.existsSync(uploadedFile.path)) {
        throw createWorkbookHttpError(400, 'Файл не найден');
      }
      const resolved = resolveWorkbookSourceForStudent(student, normalizedSourceFileId);
      if (!resolved || resolved.sourceFile.id !== normalizedSourceFileId) {
        throw createWorkbookHttpError(410, 'Исходная таблица больше недоступна');
      }
      const sourceFile = resolved.sourceFile;
      if (!isWorkbookFileName(uploadedFile.originalname)) {
        throw createWorkbookHttpError(415, 'Можно загружать только таблицы Excel или LibreOffice');
      }
      const sourceExtension = getWorkbookExtension(sourceFile.name);
      const uploadedExtension = getWorkbookExtension(normalizeFileName(uploadedFile.originalname));
      if (!sourceExtension || uploadedExtension !== sourceExtension) {
        throw createWorkbookHttpError(415, 'Формат решения должен совпадать с исходной таблицей');
      }
      const incomingContentHash = crypto
        .createHash('sha256')
        .update(fs.readFileSync(uploadedFile.path))
        .digest('hex');
      const claimedContentHash = normalizeWorkbookContentHash(providedContentHash);
      if (providedContentHash && claimedContentHash !== incomingContentHash) {
        throw createWorkbookHttpError(400, 'Контрольная сумма файла не совпадает');
      }

      const files = readFilesDb();
      const existing = findWorkbookSolutionEntry(
        files,
        student.id,
        sourceFile.id,
        solutionKey,
        solutionFileId
      );
      if (solutionFileId && !existing) {
        throw createWorkbookHttpError(410, 'Сохранённое решение больше недоступно');
      }
      const questionSolutions = sourceFile?.workbookQuestionContext
        ? getWorkbookQuestionSolutionEntries(files, student.id, sourceFile.id)
        : [];
      const existingQuestionSolution = existing
        ? questionSolutions.find(({ entry }) => entry.id === existing.id)
        : null;
      const questionSolutionSlot = existingQuestionSolution?.slot || (
        sourceFile?.workbookQuestionContext
          ? Array.from({ length: MAX_WORKBOOK_QUESTION_SOLUTIONS }, (_, index) => index + 1)
            .find((slot) => (
              buildWorkbookQuestionSolutionKey(student.id, sourceFile.id, slot) === solutionKey
            )) || 0
          : 0
      );
      if (!existing && sourceFile?.workbookQuestionContext && (
        !questionSolutionSlot
        || questionSolutions.length >= MAX_WORKBOOK_QUESTION_SOLUTIONS
        || questionSolutions.some(({ slot }) => slot === questionSolutionSlot)
      )) {
        throw createWorkbookHttpError(409, 'Можно сохранить не больше трёх решений');
      }
      const currentRevision = existing
        ? Math.max(0, Math.floor(Number(existing.workbookRevision) || 0))
        : 0;
      const existingContentHash = existing ? getWorkbookFileContentHash(existing) : '';
      const revisionDecision = resolveWorkbookRevisionWrite({
        currentRevision,
        currentContentHash: existingContentHash,
        expectedRevision,
        incomingContentHash,
      });
      if (revisionDecision.action === 'invalid') {
        throw createWorkbookHttpError(400, 'Некорректная ревизия таблицы');
      }
      if (revisionDecision.action === 'conflict') {
        throw createWorkbookHttpError(409, 'Файл уже был обновлён в другом месте', {
          revision: revisionDecision.revision,
          contentHash: revisionDecision.contentHash,
        });
      }
      if (revisionDecision.action === 'unchanged' && existing) {
        removeWorkbookUploadedFile(uploadedFile);
        return {
          entry: existing,
          revision: revisionDecision.revision,
          contentHash: revisionDecision.contentHash,
          unchanged: true,
        };
      }

      const rawSolutionName = String(requestedSolutionName || '').trim();
      const namedSolution = rawSolutionName
        ? buildNamedWorkbookSolutionName(rawSolutionName, sourceFile.name)
        : '';
      let entryName = String(existing?.name || '').trim();
      if (existing) {
        if (rawSolutionName && !namedSolution) {
          throw createWorkbookHttpError(400, 'Некорректное имя решения');
        }
        if (namedSolution && namedSolution.toLocaleLowerCase('ru-RU') !== entryName.toLocaleLowerCase('ru-RU')) {
          throw createWorkbookHttpError(409, 'Имя сохранённого решения нельзя изменить');
        }
        entryName ||= buildWorkbookSolutionName(sourceFile.name);
      } else if (questionSolutionSlot) {
        entryName = buildWorkbookQuestionSolutionName(sourceFile.name, questionSolutionSlot);
      } else if (requireSolutionName) {
        if (!namedSolution) {
          throw createWorkbookHttpError(400, 'Укажите короткое безопасное имя решения');
        }
        entryName = namedSolution;
      } else {
        entryName = buildWorkbookSolutionName(sourceFile.name);
      }
      if (!existing && files.some((entry) => (
        String(entry?.studentId || '').trim() === String(student.id || '').trim()
        && String(entry?.workbookSourceFileId || '').trim() === String(sourceFile.id || '').trim()
        && String(entry?.name || '').trim().toLocaleLowerCase('ru-RU') === entryName.toLocaleLowerCase('ru-RU')
      ))) {
        throw createWorkbookHttpError(409, 'Решение с таким именем уже существует');
      }

      const folder = ensureWorkbookSolutionFolder({
        studentId: student.id,
        taskNumber: sourceFile.taskNumber,
        category: sourceFile.category,
      });
      assertWorkbookSolutionCapacity({
        files,
        existing,
        student,
        sourceFile,
        folder,
        sizeBytes: uploadedFile.size,
      });

      const nowIso = new Date().toISOString();
      const normalizedSource = normalizeFileMemorySource(source, 'workbook-auto-sync');
      const savedBy = getFileMemoryActor(actor || {
        id: student.id,
        role: 'student',
        name: student.name,
      });
      const memory = normalizeFileMemory({
        ...(existing?.memory && typeof existing.memory === 'object' ? existing.memory : {}),
        ...(incomingMemory && typeof incomingMemory === 'object' ? incomingMemory : {}),
        kind: 'workbook-solution',
        title: entryName.replace(/\.[^.]+$/, ''),
        source: normalizedSource,
        savedBy,
        createdAt: existing?.memory?.createdAt || existing?.createdAt || nowIso,
      }, {
        taskNumber: sourceFile.taskNumber,
        source: normalizedSource,
        savedBy,
        createdAt: existing?.createdAt || nowIso,
      });
      const entry = {
        ...(existing || {}),
        id: existing?.id || crypto.randomUUID(),
        studentId: student.id,
        taskNumber: Number(sourceFile.taskNumber),
        category: String(sourceFile.category || '').trim(),
        folderId: folder.id,
        folderName: folder.name,
        name: entryName,
        size: formatSize(uploadedFile.size),
        sizeBytes: uploadedFile.size,
        date: existing?.date || new Date(nowIso).toLocaleDateString('ru-RU'),
        createdAt: existing?.createdAt || nowIso,
        updatedAt: nowIso,
        source: normalizedSource,
        savedBy,
        memory,
        url: `/uploads/${uploadedFile.filename}`,
        storageName: uploadedFile.filename,
        workbookSourceFileId: sourceFile.id,
        workbookSolutionKey: solutionKey,
        workbookRevision: existing
          ? revisionDecision.revision
          : Math.max(1, revisionDecision.revision),
        workbookContentHash: incomingContentHash,
        ...(sourceFile?.workbookQuestionContext ? {
          workbookQuestionContext: { ...sourceFile.workbookQuestionContext },
          workbookQuestionSolution: true,
          workbookQuestionSolutionSlot: questionSolutionSlot,
        } : {}),
        ...(String(sourceFile.category || '').trim() === 'class' ? {
          lessonStudentId: student.id,
          lessonSavedAt: nowIso,
        } : {}),
      };

      const nextFiles = [...files];
      if (existing) {
        const existingIndex = nextFiles.findIndex((candidate) => candidate?.id === existing.id);
        if (existingIndex >= 0) nextFiles[existingIndex] = entry;
        else nextFiles.unshift(entry);
      } else {
        nextFiles.unshift(entry);
      }
      writeFilesDb(nextFiles);
      if (existing?.storageName && existing.storageName !== entry.storageName) {
        fs.unlink(path.join(uploadsDir, path.basename(existing.storageName)), () => {});
      }
      if (entry.category === 'class') {
        appendLessonNoteActivity({
          studentId: student.id,
          teacherId: normalizeTeacherId(student.teacherId),
          taskNumber: entry.taskNumber,
          fileId: entry.id,
          source: normalizedSource,
          occurredAt: nowIso,
        });
      }
      return {
        entry,
        revision: entry.workbookRevision,
        contentHash: entry.workbookContentHash,
        unchanged: false,
      };
    } catch (error) {
      removeWorkbookUploadedFile(uploadedFile);
      throw error;
    }
  });
};

const pruneWorkbookHelperLaunchTickets = (nowMs = Date.now()) => {
  workbookHelperLaunchTickets.forEach((ticket, ticketHash) => {
    if (!ticket || Number(ticket.expiresAtMs) <= nowMs) {
      workbookHelperLaunchTickets.delete(ticketHash);
    }
  });
  if (workbookHelperLaunchTickets.size <= WORKBOOK_HELPER_MAX_TICKETS) return;
  const oldest = Array.from(workbookHelperLaunchTickets.entries())
    .sort((left, right) => Number(left[1]?.createdAtMs || 0) - Number(right[1]?.createdAtMs || 0));
  oldest
    .slice(0, workbookHelperLaunchTickets.size - WORKBOOK_HELPER_MAX_TICKETS)
    .forEach(([ticketHash]) => workbookHelperLaunchTickets.delete(ticketHash));
};

const createWorkbookHelperLaunchTicket = ({
  studentId,
  sourceFileId,
  launchFileId,
  solutionKey,
  solutionFileId = '',
  nameRequired = false,
  startsFresh = false,
}) => {
  pruneWorkbookHelperLaunchTickets();
  const ticket = createWorkbookHelperToken();
  const ticketHash = hashWorkbookHelperToken(ticket);
  const nowMs = Date.now();
  const entry = {
    studentId: String(studentId || '').trim(),
    sourceFileId: String(sourceFileId || '').trim(),
    launchFileId: String(launchFileId || sourceFileId || '').trim(),
    solutionKey: normalizeWorkbookSolutionKey(solutionKey),
    solutionFileId: String(solutionFileId || '').trim(),
    nameRequired: Boolean(nameRequired),
    startsFresh: Boolean(startsFresh),
    createdAtMs: nowMs,
    expiresAtMs: nowMs + WORKBOOK_HELPER_TICKET_TTL_MS,
  };
  workbookHelperLaunchTickets.set(ticketHash, entry);
  return { ticket, ticketHash, ...entry };
};

const WORKBOOK_HELPER_RATE_WINDOW_MS = 60 * 1000;
const WORKBOOK_HELPER_RATE_MAX_CLIENTS = 2000;

const pruneWorkbookHelperRateStore = (store, nowMs) => {
  store.forEach((timestamps, storedKey) => {
    const live = (Array.isArray(timestamps) ? timestamps : [])
      .filter((timestamp) => nowMs - Number(timestamp) < WORKBOOK_HELPER_RATE_WINDOW_MS);
    if (live.length > 0) store.set(storedKey, live);
    else store.delete(storedKey);
  });
};

const consumeWorkbookHelperRate = (store, req, limit) => {
  const nowMs = Date.now();
  const key = getClientKey(req);
  if (!store.has(key) && store.size >= WORKBOOK_HELPER_RATE_MAX_CLIENTS) {
    pruneWorkbookHelperRateStore(store, nowMs);
    if (store.size >= WORKBOOK_HELPER_RATE_MAX_CLIENTS) {
      Array.from(store.entries())
        .sort((left, right) => (
          Number(left[1]?.[left[1].length - 1] || 0)
          - Number(right[1]?.[right[1].length - 1] || 0)
        ))
        .slice(0, store.size - WORKBOOK_HELPER_RATE_MAX_CLIENTS + 1)
        .forEach(([storedKey]) => store.delete(storedKey));
    }
  }
  const recent = (store.get(key) || [])
    .filter((timestamp) => nowMs - Number(timestamp) < WORKBOOK_HELPER_RATE_WINDOW_MS);
  if (recent.length >= limit) {
    store.set(key, recent);
    return false;
  }
  recent.push(nowMs);
  store.set(key, recent);
  return true;
};

const consumeWorkbookHelperExchangeRate = (req) => (
  consumeWorkbookHelperRate(workbookHelperExchangeAttempts, req, 30)
);

const requireWorkbookHelperContentRate = (req, res, next) => {
  if (!consumeWorkbookHelperRate(workbookHelperContentAttempts, req, 120)) {
    res.setHeader('Retry-After', '60');
    return res.status(429).json({ error: 'Слишком много запросов к таблице. Повторите через минуту.' });
  }
  return next();
};

const findWorkbookHelperSessionByToken = (token) => {
  const tokenHash = hashWorkbookHelperToken(token);
  if (!tokenHash) return null;
  ensureWorkbookHelperSessionsCache();
  const session = workbookHelperSessionsByTokenHash.get(tokenHash) || null;
  if (!session) return null;
  const actualHash = Buffer.from(tokenHash, 'hex');
  const storedHash = Buffer.from(session.tokenHash, 'hex');
  if (actualHash.length !== storedHash.length || !crypto.timingSafeEqual(actualHash, storedHash)) {
    return null;
  }
  if (Number(session.expiresAtMs) <= Date.now()) {
    workbookHelperSessionsByTokenHash.delete(tokenHash);
    return null;
  }
  return session;
};

const updateWorkbookHelperSession = (sessionId, patch = {}, options = {}) => {
  const sessions = readWorkbookHelperSessionsDb();
  const index = sessions.findIndex((session) => session?.id === sessionId);
  if (index < 0) return null;
  const current = sessions[index];
  sessions[index] = {
    ...current,
    ...patch,
    id: current.id,
    tokenHash: current.tokenHash,
    studentId: current.studentId,
    sourceFileId: current.sourceFileId,
    launchFileId: current.launchFileId,
    solutionKey: current.solutionKey,
  };
  const saved = writeWorkbookHelperSessionsDb(sessions, options);
  return saved.find((session) => session.id === current.id) || null;
};

const removeWorkbookHelperSession = (sessionId) => {
  const sessions = readWorkbookHelperSessionsDb();
  const next = sessions.filter((session) => session?.id !== sessionId);
  if (next.length === sessions.length) return false;
  writeWorkbookHelperSessionsDb(next);
  return true;
};

const revokeWorkbookHelperSessionsForStudents = (studentIds = []) => {
  const targets = new Set(
    (Array.isArray(studentIds) ? studentIds : [studentIds])
      .map((studentId) => String(studentId || '').trim())
      .filter(Boolean)
  );
  if (targets.size === 0) return 0;
  const sessions = readWorkbookHelperSessionsDb();
  const next = sessions.filter((session) => !targets.has(String(session?.studentId || '').trim()));
  const removed = sessions.length - next.length;
  if (removed > 0) writeWorkbookHelperSessionsDb(next);
  workbookHelperLaunchTickets.forEach((ticket, ticketHash) => {
    if (targets.has(String(ticket?.studentId || '').trim())) {
      workbookHelperLaunchTickets.delete(ticketHash);
    }
  });
  return removed;
};

const getWorkbookHelperSessionContext = (session) => {
  const student = findStudentById(session?.studentId);
  if (!student) return null;
  const resolved = resolveWorkbookSourceForStudent(student, session?.sourceFileId);
  if (
    !resolved
    || resolved.sourceFile.id !== session.sourceFileId
  ) return null;
  const state = getWorkbookBindingState(student, resolved.sourceFile, resolved.files, {
    solutionKey: session.solutionKey,
    solutionFileId: session.solutionFileId,
    nameRequired: session.nameRequired,
  });
  if (
    state.solutionKey !== session.solutionKey
    || (session.solutionFileId && state.solutionFile?.id !== session.solutionFileId)
  ) return null;
  const launchContent = getWorkbookLaunchContent(
    resolved.sourceFile,
    state,
    session.startsFresh
  );
  if (!launchContent) return null;
  return {
    student,
    sourceFile: resolved.sourceFile,
    files: resolved.files,
    launchFile: launchContent.launchFile,
    launchContentHash: launchContent.contentHash,
    state,
  };
};

const persistWorkbookHelperSessionState = (session, state, options = {}) => {
  const nowMs = Date.now();
  const shouldTouch = options.force === true
    || nowMs - Number(session?.lastUsedAtMs || 0) >= 5 * 60 * 1000
    || String(session?.solutionFileId || '') !== String(state?.solutionFile?.id || '')
    || Boolean(session?.nameRequired) !== Boolean(state?.nameRequired)
    || Number(session?.revision || 0) !== Number(state?.revision || 0)
    || String(session?.contentHash || '') !== String(state?.contentHash || '');
  if (!shouldTouch) return session;
  return updateWorkbookHelperSession(session.id, {
    solutionFileId: String(state?.solutionFile?.id || ''),
    nameRequired: Boolean(state?.nameRequired),
    revision: Math.max(0, Math.floor(Number(state?.revision) || 0)),
    contentHash: normalizeWorkbookContentHash(state?.contentHash),
    lastUsedAtMs: nowMs,
  }) || session;
};

const requireWorkbookHelperSession = (req, res, next) => {
  const token = parseWorkbookHelperAuthorization(req.headers.authorization);
  if (!token) {
    return res.status(401).json({ error: 'Требуется токен Workbook' });
  }
  const session = findWorkbookHelperSessionByToken(token);
  if (!session) {
    return res.status(401).json({ error: 'Привязка таблицы истекла или была отключена' });
  }
  const context = getWorkbookHelperSessionContext(session);
  if (!context) {
    removeWorkbookHelperSession(session.id);
    return res.status(410).json({ error: 'Таблица больше недоступна. Откройте её с платформы заново.' });
  }
  const touchedSession = persistWorkbookHelperSessionState(session, context.state);
  req.workbookHelper = {
    token,
    tokenHash: session.tokenHash,
    session: touchedSession,
    ...context,
  };
  return next();
};

const sendWorkbookOperationError = (res, error) => {
  const statusCode = Number(error?.statusCode) || 500;
  const payload = { error: String(error?.message || 'Не удалось сохранить таблицу') };
  if (Number.isFinite(Number(error?.revision))) payload.revision = Number(error.revision);
  const contentHash = normalizeWorkbookContentHash(error?.contentHash);
  if (contentHash) payload.contentHash = contentHash;
  if (statusCode >= 500) console.error('[workbook-helper] operation failed:', error);
  return res.status(statusCode).json(payload);
};

app.post('/workbook-helper/v1/exchange', async (req, res) => {
  res.setHeader('Cache-Control', 'no-store');
  if (!req.is('application/json')) {
    return res.status(415).json({ error: 'Ожидался JSON-запрос' });
  }
  if (!consumeWorkbookHelperExchangeRate(req)) {
    return res.status(429).json({ error: 'Слишком много попыток. Откройте файл с платформы заново.' });
  }
  pruneWorkbookHelperLaunchTickets();
  const rawTicket = String(req.body?.ticket || '').trim();
  const ticketHash = hashWorkbookHelperToken(rawTicket);
  const ticket = ticketHash ? workbookHelperLaunchTickets.get(ticketHash) : null;
  if (!ticket || Number(ticket.expiresAtMs) <= Date.now()) {
    if (ticketHash) workbookHelperLaunchTickets.delete(ticketHash);
    return res.status(410).json({ error: 'Ссылка запуска истекла. Нажмите «Решать» ещё раз.' });
  }
  const student = findStudentById(ticket.studentId);
  const resolved = student
    ? resolveWorkbookSourceForStudent(student, ticket.sourceFileId)
    : null;
  if (!resolved || resolved.sourceFile.id !== ticket.sourceFileId) {
    workbookHelperLaunchTickets.delete(ticketHash);
    return res.status(410).json({ error: 'Таблица больше недоступна' });
  }
  const ticketSolutionKey = normalizeWorkbookSolutionKey(ticket.solutionKey);
  const state = getWorkbookBindingState(student, resolved.sourceFile, resolved.files, {
    solutionKey: ticketSolutionKey,
    solutionFileId: ticket.solutionFileId,
    nameRequired: ticket.nameRequired,
  });
  const launchContent = getWorkbookLaunchContent(
    resolved.sourceFile,
    state,
    ticket.startsFresh
  );
  if (
    !ticketSolutionKey
    || (ticket.solutionFileId && state.solutionFile?.id !== ticket.solutionFileId)
    || !launchContent
  ) {
    workbookHelperLaunchTickets.delete(ticketHash);
    return res.status(410).json({ error: 'Файл таблицы не найден' });
  }

  try {
    const sourceText = await serializeWorkbookHelperSourceText(resolveWorkbookHelperSourceText({
      student,
      sourceFile: resolved.sourceFile,
      files: resolved.files,
    }));
    const helperUserAgent = String(req.headers['user-agent'] || '');
    const helperVersionMatch = helperUserAgent.match(/IvanEgeWorkbookHelper\/(\d+)\.(\d+)/i);
    if (
      sourceText
      && helperVersionMatch
      && (
        Number(helperVersionMatch[1]) < 1
        || (Number(helperVersionMatch[1]) === 1 && Number(helperVersionMatch[2]) < 2)
      )
    ) {
      return res.status(426).json({
        error: 'Для заданий с текстом обновите помощник Excel и LibreOffice до версии 1.2 или новее.',
      });
    }
    const rawToken = createWorkbookHelperToken();
    const tokenHash = hashWorkbookHelperToken(rawToken);
    const nowMs = Date.now();
    const session = {
      id: crypto.randomUUID(),
      tokenHash,
      studentId: student.id,
      sourceFileId: resolved.sourceFile.id,
      launchFileId: String(ticket.launchFileId || resolved.sourceFile.id),
      solutionKey: ticketSolutionKey,
      solutionFileId: String(state.solutionFile?.id || ''),
      nameRequired: Boolean(state.nameRequired),
      startsFresh: Boolean(ticket.startsFresh),
      revision: state.revision,
      contentHash: state.contentHash,
      createdAtMs: nowMs,
      lastUsedAtMs: nowMs,
      expiresAtMs: nowMs + WORKBOOK_HELPER_SESSION_TTL_MS,
    };
    const sessions = readWorkbookHelperSessionsDb();
    sessions.unshift(session);
    writeWorkbookHelperSessionsDb(sessions);
    workbookHelperLaunchTickets.delete(ticketHash);
    return res.json({
      token: rawToken,
      workbookKey: session.solutionKey,
      fileName: state.fileName,
      solutionName: state.nameRequired ? '' : state.fileName,
      requiresName: Boolean(state.nameRequired),
      nameRequired: Boolean(state.nameRequired),
      revision: state.revision,
      contentHash: launchContent.contentHash,
      expiresAt: new Date(session.expiresAtMs).toISOString(),
      sourceText,
    });
  } catch (error) {
    if (Number(error?.statusCode) >= 400 && Number(error?.statusCode) < 500) {
      return sendWorkbookOperationError(res, error);
    }
    console.error('[workbook-helper] exchange failed:', error);
    return res.status(500).json({ error: 'Не удалось привязать помощник' });
  }
});

app.get(
  '/workbook-helper/v1/source-text',
  requireWorkbookHelperContentRate,
  requireWorkbookHelperSession,
  async (req, res) => {
    const { student, sourceFile, files } = req.workbookHelper;
    const sourceText = resolveWorkbookHelperSourceText({ student, sourceFile, files });
    if (!sourceText) {
      return res.status(404).json({ error: 'Исходный текстовый файл больше недоступен' });
    }
    if (sourceText.sizeBytes > WORKBOOK_HELPER_SOURCE_TEXT_MAX_BYTES) {
      return res.status(413).json({ error: 'Текстовый файл больше допустимых 16 МБ' });
    }
    let metadata;
    try {
      metadata = await serializeWorkbookHelperSourceText(sourceText);
    } catch (error) {
      return sendWorkbookOperationError(res, error);
    }
    const requestSize = getRangeSize(req.headers.range, metadata.sizeBytes);
    const usage = getStudentUsage(student.id);
    if (usage.enabled && (usage.remaining <= 0 || usage.used + requestSize > usage.limit)) {
      return res.status(429).json({ error: 'Превышен лимит трафика для ученика' });
    }
    if (usage.enabled && (usage.used / usage.limit >= STUDENT_TRAFFIC_WARN_RATIO)) {
      res.setHeader('X-Traffic-Warn', '1');
    }
    registerUsageOnFinish(student.id, res, requestSize);
    res.setHeader('Cache-Control', 'no-store');
    res.setHeader('X-Source-Text-Content-Hash', metadata.contentHash);
    res.setHeader('X-Source-Text-Size', String(metadata.sizeBytes));
    res.attachment(metadata.fileName);
    return res.sendFile(sourceText.filePath);
  }
);

app.get(
  '/workbook-helper/v1/content',
  requireWorkbookHelperContentRate,
  requireWorkbookHelperSession,
  (req, res) => {
    const { student, state, launchFile, launchContentHash } = req.workbookHelper;
    const filePath = getWorkbookStoredFilePath(launchFile);
    if (!filePath) {
      removeWorkbookHelperSession(req.workbookHelper.session.id);
      return res.status(410).json({ error: 'Файл таблицы больше недоступен' });
    }
    const stat = fs.statSync(filePath);
    const requestSize = getRangeSize(req.headers.range, stat.size);
    const usage = getStudentUsage(student.id);
    if (usage.enabled && (usage.remaining <= 0 || usage.used + requestSize > usage.limit)) {
      return res.status(429).json({ error: 'Превышен лимит трафика для ученика' });
    }
    if (usage.enabled && (usage.used / usage.limit >= STUDENT_TRAFFIC_WARN_RATIO)) {
      res.setHeader('X-Traffic-Warn', '1');
    }
    registerUsageOnFinish(student.id, res, requestSize);
    res.setHeader('Cache-Control', 'no-store');
    res.setHeader('X-Workbook-Key', state.solutionKey);
    res.setHeader('X-Workbook-Revision', String(state.revision));
    res.setHeader('X-Workbook-Content-Hash', launchContentHash);
    res.attachment(state.fileName);
    return res.sendFile(filePath);
  }
);

app.put(
  '/workbook-helper/v1/content',
  requireWorkbookHelperContentRate,
  requireWorkbookHelperSession,
  workbookHelperUpload.single('file'),
  async (req, res) => {
    if (!req.file) return res.status(400).json({ error: 'Файл не найден' });
    const activeSession = readWorkbookHelperSessionsDb()
      .find((session) => (
        session.id === req.workbookHelper.session.id
        && session.tokenHash === req.workbookHelper.tokenHash
      ));
    if (!activeSession) {
      removeWorkbookUploadedFile(req.file);
      return res.status(401).json({ error: 'Привязка таблицы была отключена' });
    }
    const rawExpectedRevision = req.body?.revision ?? req.headers['x-workbook-revision'];
    const providedContentHash = req.body?.contentHash ?? req.headers['x-workbook-content-hash'] ?? '';
    if (
      rawExpectedRevision === ''
      || rawExpectedRevision === null
      || typeof rawExpectedRevision === 'undefined'
    ) {
      removeWorkbookUploadedFile(req.file);
      return res.status(400).json({ error: 'Укажите ревизию таблицы' });
    }
    if (!normalizeWorkbookContentHash(providedContentHash)) {
      removeWorkbookUploadedFile(req.file);
      return res.status(400).json({ error: 'Укажите SHA-256 загружаемого файла' });
    }
    try {
      const result = await upsertWorkbookSolutionContent({
        student: req.workbookHelper.student,
        sourceFileId: req.workbookHelper.sourceFile.id,
        uploadedFile: req.file,
        actor: {
          id: req.workbookHelper.student.id,
          role: 'student',
          name: req.workbookHelper.student.name,
        },
        source: 'workbook-helper',
        expectedRevision: rawExpectedRevision,
        providedContentHash,
        solutionKey: activeSession.solutionKey,
        solutionFileId: activeSession.solutionFileId,
        solutionName: req.body?.solutionName,
        requireSolutionName: Boolean(activeSession.nameRequired),
        requiredHelperSessionId: activeSession.id,
        requiredHelperTokenHash: activeSession.tokenHash,
      });
      const nextState = getWorkbookBindingState(
        req.workbookHelper.student,
        req.workbookHelper.sourceFile,
        null,
        {
          solutionKey: activeSession.solutionKey,
          solutionFileId: result.entry?.id,
          nameRequired: false,
        }
      );
      updateWorkbookHelperSession(activeSession.id, {
        solutionFileId: String(result.entry?.id || ''),
        nameRequired: false,
        revision: result.revision,
        contentHash: result.contentHash,
        lastUsedAtMs: Date.now(),
      });
      return res.json({
        file: result.entry,
        revision: result.revision,
        contentHash: result.contentHash,
        unchanged: Boolean(result.unchanged),
        fileName: String(result.entry?.name || nextState.fileName),
        solutionName: String(result.entry?.name || nextState.fileName),
        requiresName: false,
        nameRequired: false,
        ...(nextState.solutionKey ? { workbookKey: nextState.solutionKey } : {}),
      });
    } catch (error) {
      return sendWorkbookOperationError(res, error);
    }
  }
);

const handleUploadRequest = (req, res) => {
  const token = getAuthTokenFromRequest(req);
  const session = getAuthSession(token);
  if (!session) {
    clearAuthSessionCookie(res);
    return res.status(401).send('Требуется авторизация');
  }
  req.auth = session.user;
  if (isLeadRole(req.auth)) {
    return res.status(403).send('Недостаточно прав');
  }

  const rawName = req.params.storageName || '';
  const safeName = path.basename(rawName);
  if (!safeName) return res.status(400).send('Некорректное имя файла');

  const filePath = path.join(uploadsDir, safeName);
  if (!fs.existsSync(filePath)) return res.status(404).send('Файл не найден');

  const isBoardAsset = safeName.startsWith('board-asset-');
  const ownedFile = isBoardAsset
    ? null
    : readFilesDb().find((entry) => (
      !isWorkbookQuestionVirtualSource(entry) && entry?.storageName === safeName
    ));
  const boardAssetGrants = isBoardAsset
    ? readBoardAssetsDb().filter((entry) => entry.storageName === safeName)
    : [];
  let boardAssetStudent = null;
  const boardAsset = boardAssetGrants.find((entry) => {
    const student = findBoardAssetStudentById(entry.studentId);
    if (student) boardAssetStudent = student;
    return Boolean(student && canAccessStudentByRole(req.auth, student, { allowDeleted: true }));
  }) || null;
  if (isBoardAsset && !boardAsset) {
    return res.status(404).send('Файл не найден');
  }
  let ownerStudentId = '';
  let ownerTeacherId = '';
  const ownerIsLessonShared = Boolean(ownedFile && isLessonSharedFile(ownedFile));
  if (boardAsset) {
    ownerStudentId = boardAsset.studentId;
    ownerTeacherId = normalizeTeacherId(boardAsset.teacherId);
  } else if (ownedFile) {
    if (ownerIsLessonShared) {
      ownerTeacherId = normalizeTeacherId(ownedFile.teacherId);
      if (!ownerTeacherId || !canReadLessonSharedByTeacher(req.auth, ownerTeacherId)) {
        return res.status(403).send('Недостаточно прав');
      }
    } else if (ownedFile.studentId) {
      const ownerStudent = findStudentById(ownedFile.studentId, { allowDeleted: true });
      if (!ownerStudent) return res.status(404).send('Файл не найден');
      if (!canAccessStudentByRole(req.auth, ownerStudent, { allowDeleted: true })) {
        return res.status(403).send('Недостаточно прав');
      }
      ownerStudentId = ownerStudent.id;
      ownerTeacherId = normalizeTeacherId(ownerStudent.teacherId);
    }
  }

  const stat = fs.statSync(filePath);
  const queryStudentId = typeof req.query.studentId === 'string' ? req.query.studentId.trim() : '';
  if (queryStudentId) {
    const student = findStudentById(queryStudentId);
    if (!student) return res.status(404).send('Ученик не найден');
    if (!canAccessStudentByRole(req.auth, student)) return res.status(403).send('Недостаточно прав');
    if (ownerIsLessonShared) {
      const studentTeacherId = normalizeTeacherId(student.teacherId);
      if (ownerTeacherId && studentTeacherId !== ownerTeacherId) {
        return res.status(400).send('Некорректный studentId');
      }
    } else if (ownerStudentId && queryStudentId !== ownerStudentId) {
      return res.status(400).send('Некорректный studentId');
    }
  }

  const usageStudentId = (() => {
    if (!isStudentRole(req.auth)) return '';
    if (ownerStudentId) return ownerStudentId;
    if (queryStudentId) return queryStudentId;
    return req.auth.id;
  })();
  if (usageStudentId) {
    const student = boardAssetStudent?.id === usageStudentId
      ? boardAssetStudent
      : findStudentById(usageStudentId);
    if (!student) return res.status(404).send('Ученик не найден');
    const requestSize = getRangeSize(req.headers.range, stat.size);
    const usage = getStudentUsage(usageStudentId);
    if (usage.enabled && (usage.remaining <= 0 || usage.used + requestSize > usage.limit)) {
      return res.status(429).json({ error: 'Превышен лимит трафика для ученика' });
    }
    if (usage.enabled && (usage.used / usage.limit >= STUDENT_TRAFFIC_WARN_RATIO)) {
      res.setHeader('X-Traffic-Warn', '1');
    }
    res.setHeader('X-Traffic-Used', String(usage.used));
    res.setHeader('X-Traffic-Limit', usage.enabled ? String(usage.limit) : 'unlimited');
    if (req.method === 'GET') {
      registerUsageOnFinish(usageStudentId, res, requestSize);
    }
  }

  if (hasForcedDownloadFlag(req.query.download)) {
    res.attachment(getUploadDownloadName(ownedFile, safeName));
  }

  if (boardAsset) {
    res.setHeader('Cache-Control', 'private, max-age=3600, immutable');
  }

  return res.sendFile(filePath);
};

app.get('/uploads/:storageName', handleUploadRequest);
app.head('/uploads/:storageName', handleUploadRequest);

app.post('/api/login', async (req, res, next) => {
  try {
  const { code } = req.body || {};
  const normalizedCode = normalizeAccessCode(code);
  if (!normalizedCode) return res.status(400).json({ error: 'Введите код доступа' });

  const clientKey = getClientKey(req);
  const rateInfo = getRateInfo(clientKey);
  if (rateInfo.blocked) {
    return res.status(429).json({
      error: 'Слишком много попыток. Попробуйте позже.',
      retryAfter: rateInfo.retryAfter,
    });
  }

  const codeLookupHash = getAccessCodeLookupHash(normalizedCode);
  const adminLookupHash = String(adminAuth?.adminCodeLookupHash || '').trim();
  const shouldVerifyAdmin = !adminLookupHash || adminLookupHash === codeLookupHash;
  if (shouldVerifyAdmin && await verifyCodeAsync(normalizedCode, adminAuth?.adminCodeHash)) {
    if (!adminLookupHash) {
      adminAuth = {
        ...adminAuth,
        adminCodeLookupHash: codeLookupHash,
        updatedAt: new Date().toISOString(),
      };
      writeAuthDb(adminAuth);
    }
    clearLoginFailures(clientKey);
    const session = createAuthSession({ id: 'admin1', name: ADMIN_NAME, role: 'admin' });
    return respondWithSession(res, session);
  }

  const teachers = readTeachersDb();
  const teacher = await findVerifiedAccessCodeRecord(
    getAccessCodeCandidates(teachers, codeLookupHash),
    normalizedCode
  );
  if (teacher) {
    if (!teacher.codeLookupHash) {
      const teacherIndex = teachers.findIndex((entry) => entry?.id === teacher.id);
      if (teacherIndex >= 0) {
        teachers[teacherIndex] = { ...teacher, codeLookupHash };
        writeTeachersDb(teachers);
      }
    }
    clearLoginFailures(clientKey);
    const session = createAuthSession({
      id: teacher.id,
      name: teacher.name,
      role: 'teacher',
      avatarDataUrl: normalizeTeacherAvatarDataUrl(teacher.avatarDataUrl),
    });
    return respondWithSession(res, session);
  }

  const students = readStudentsDb();
  const student = await findVerifiedAccessCodeRecord(
    getAccessCodeCandidates(students, codeLookupHash, (entry) => !entry?.deletedAt),
    normalizedCode
  );
  if (!student) {
    const deletedMatch = await findVerifiedAccessCodeRecord(
      getAccessCodeCandidates(students, codeLookupHash, (entry) => Boolean(entry?.deletedAt)),
      normalizedCode
    );
    if (deletedMatch) {
      if (!deletedMatch.codeLookupHash) {
        const deletedIndex = students.findIndex((entry) => entry?.id === deletedMatch.id);
        if (deletedIndex >= 0) {
          students[deletedIndex] = { ...deletedMatch, codeLookupHash };
          writeStudentsDb(students);
        }
      }
      return res.status(403).json({ error: 'Студент удалён. Обратитесь к учителю.' });
    }
    const blocked = registerLoginFailure(clientKey);
    if (blocked.blocked) {
      return res.status(429).json({
        error: 'Слишком много попыток. Попробуйте позже.',
        retryAfter: blocked.retryAfter,
      });
    }
    return res.status(401).json({ error: 'Неверный код доступа' });
  }

  if (!student.codeLookupHash) {
    const studentIndex = students.findIndex((entry) => entry?.id === student.id);
    if (studentIndex >= 0) {
      students[studentIndex] = { ...student, codeLookupHash };
      writeStudentsDb(students);
    }
  }
  clearLoginFailures(clientKey);
  const session = createAuthSession({
    id: student.id,
    name: student.name,
    role: 'student',
    teacherId: student.teacherId || null,
    grade: normalizeStudentGrade(student.grade),
    studyStatus: normalizeStudentStudyStatus(student.studyStatus, student.grade),
    avatarDataUrl: normalizeStudentAvatarDataUrl(getStudentData(student.id)?.avatarDataUrl),
  });
  return respondWithSession(res, session);
  } catch (error) {
    return next(error);
  }
});

app.post('/api/signup/login', (req, res) => {
  const rawGuestName = normalizeSignupGuestName(req.body?.name);
  const guestKey = normalizeSignupGuestKey(req.body?.guestKey);
  const chats = readSignupChatsDb();
  const nowIso = new Date().toISOString();
  let chat = null;

  if (guestKey) {
    const existingIdx = chats.findIndex((entry) => entry.guestKey && entry.guestKey === guestKey);
    if (existingIdx >= 0) {
      const existing = chats[existingIdx];
      let guestName = existing.guestName;
      if (rawGuestName) {
        if (rawGuestName.length > SIGNUP_GUEST_NAME_MAX_LENGTH) {
          return res.status(400).json({ error: `Имя слишком длинное (до ${SIGNUP_GUEST_NAME_MAX_LENGTH} символов)` });
        }
        if (/[/\\]/.test(rawGuestName)) return res.status(400).json({ error: 'Недопустимые символы в имени' });
        guestName = rawGuestName;
      }
      const restored = normalizeSignupChat({
        ...existing,
        guestName,
        updatedAt: nowIso,
        lastReadByLeadAt: nowIso,
      });
      if (restored) {
        chats[existingIdx] = restored;
        writeSignupChatsDb(chats);
        chat = restored;
      }
    }
  }

  if (!chat) {
    const guestName = rawGuestName;
    if (!guestName) return res.status(400).json({ error: 'Введите имя' });
    if (guestName.length > SIGNUP_GUEST_NAME_MAX_LENGTH) {
      return res.status(400).json({ error: `Имя слишком длинное (до ${SIGNUP_GUEST_NAME_MAX_LENGTH} символов)` });
    }
    if (/[/\\]/.test(guestName)) return res.status(400).json({ error: 'Недопустимые символы в имени' });

    const requestedTeacherId = typeof req.body?.teacherId === 'string' ? req.body.teacherId.trim() : '';
    const teacher = resolveSignupTeacher(requestedTeacherId);
    if (!teacher) {
      return res.status(503).json({ error: 'Пока нет преподавателя для записи. Попробуйте позже.' });
    }

    chat = normalizeSignupChat({
      id: crypto.randomUUID(),
      teacherId: teacher.id,
      guestUserId: crypto.randomUUID(),
      guestKey,
      guestName,
      createdAt: nowIso,
      updatedAt: nowIso,
      lastMessageAt: nowIso,
      lastMessagePreview: '',
      lastMessageSenderRole: '',
      lastReadByTeacherAt: null,
      lastReadByLeadAt: nowIso,
      messages: [],
    });
    if (!chat) return res.status(500).json({ error: 'Не удалось создать чат' });

    chats.unshift(chat);
    writeSignupChatsDb(chats);
  }

  const session = createAuthSession({
    id: chat.guestUserId,
    name: chat.guestName,
    role: 'lead',
    chatId: chat.id,
    teacherId: chat.teacherId,
  });
  return respondWithSession(res, session);
});

