app.post('/api/workbook-helper/launch', (req, res) => {
  res.setHeader('Cache-Control', 'no-store');
  if (!isStudentRole(req.auth)) return forbid(res);
  if (!req.is('application/json')) {
    return res.status(415).json({ error: 'Ожидался JSON-запрос' });
  }
  const requestedFileId = String(req.body?.fileId || '').trim();
  if (!requestedFileId) return res.status(400).json({ error: 'fileId required' });
  const student = findStudentById(req.auth.id);
  let resolved = student
    ? resolveWorkbookSourceForStudent(student, requestedFileId)
    : null;
  let opensSourceText = false;
  if (!resolved && student) {
    const files = readFilesDb();
    const textFile = files.find((entry) => String(entry?.id || '').trim() === requestedFileId);
    if (
      textFile
      && isWorkbookFileAccessibleToStudent(student, textFile)
      && isWorkbookTextAttachment(textFile.taskNumber, textFile.name)
      && getWorkbookStoredFilePath(textFile)
    ) {
      const ensured = ensureWorkbookTextMaterialSource({ student, textFile, files });
      resolved = resolveWorkbookSourceForStudent(student, ensured.source.id, ensured.files);
      opensSourceText = Boolean(resolved);
    }
  }
  if (!resolved) return res.status(404).json({ error: 'Таблица не найдена' });
  opensSourceText = opensSourceText || Boolean(resolveWorkbookHelperSourceText({
    student,
    sourceFile: resolved.sourceFile,
    files: resolved.files,
  }));
  const solutionFileId = String(resolved.solutionFile?.id || '');
  const solutionKey = solutionFileId
    ? resolved.solutionKey
    : createWorkbookSolutionBindingKey();
  const nameRequired = !solutionFileId;
  const state = getWorkbookBindingState(student, resolved.sourceFile, resolved.files, {
    solutionKey,
    solutionFileId,
    nameRequired,
  });
  if (!state.contentHash) {
    return res.status(410).json({ error: 'Файл таблицы больше недоступен' });
  }
  const launch = createWorkbookHelperLaunchTicket({
    studentId: student.id,
    sourceFileId: resolved.sourceFile.id,
    launchFileId: resolved.launchFile.id,
    solutionKey,
    solutionFileId,
    nameRequired,
  });
  return res.status(201).json({
    ticket: launch.ticket,
    expiresAt: new Date(launch.expiresAtMs).toISOString(),
    workbookKey: state.solutionKey,
    fileName: state.fileName,
    solutionName: state.nameRequired ? '' : state.fileName,
    suggestedName: state.nameRequired ? '' : state.fileName,
    requiresName: Boolean(state.nameRequired),
    nameRequired: Boolean(state.nameRequired),
    revision: state.revision,
    contentHash: state.contentHash,
    opensSourceText,
  });
});

app.get('/api/workbook-helper/question-solutions', (req, res) => {
  res.setHeader('Cache-Control', 'no-store');
  if (!isStudentRole(req.auth)) return forbid(res);
  const student = findStudentById(req.auth.id);
  if (!student) return res.status(404).json({ error: 'Ученик не найден' });
  const taskNumber = Number(req.query?.taskNumber);
  const levelId = normalizeWorkbookQuestionValue(req.query?.levelId, 100);
  const questionId = normalizeWorkbookQuestionValue(req.query?.questionId, 160);
  if (!Number.isFinite(taskNumber) || !levelId || !questionId) {
    return res.status(400).json({ error: 'Некорректные параметры задания' });
  }
  const studentData = getStudentData(student.id);
  const testsDb = getTestsDbWithStudentMockFollowups(studentData);
  const { question } = getQuestionEntryFromTestsDb(testsDb, taskNumber, levelId, questionId);
  if (!question) return res.status(404).json({ error: 'Вопрос не найден' });
  const context = { taskNumber, levelId, questionId };
  const files = readFilesDb();
  const matchingEntries = files.filter((entry) => (
      entry?.workbookQuestionSolution === true
      && String(entry?.studentId || '').trim() === String(student.id || '').trim()
      && workbookQuestionContextMatches(entry?.workbookQuestionContext, context, { includeAttachment: false })
    ));
  const sourceIds = new Set(matchingEntries.map((entry) => String(entry.workbookSourceFileId || '')));
  const solutions = Array.from(sourceIds)
    .flatMap((sourceFileId) => (
      getWorkbookQuestionSolutionEntries(files, student.id, sourceFileId)
        .filter(({ entry }) => workbookQuestionContextMatches(
          entry?.workbookQuestionContext,
          context,
          { includeAttachment: false }
        ))
        .map(({ entry, slot }) => serializeWorkbookQuestionSolution(entry, slot))
    ))
    .sort((left, right) => (
      String(left.attachmentId).localeCompare(String(right.attachmentId)) || left.slot - right.slot
    ));
  return res.json({ solutions });
});

app.post('/api/workbook-helper/question-launch', (req, res) => {
  res.setHeader('Cache-Control', 'no-store');
  if (!isStudentRole(req.auth)) return forbid(res);
  if (!req.is('application/json')) {
    return res.status(415).json({ error: 'Ожидался JSON-запрос' });
  }
  const student = findStudentById(req.auth.id);
  if (!student) return res.status(404).json({ error: 'Ученик не найден' });
  try {
    const target = getWorkbookQuestionTarget({
      student,
      taskNumber: req.body?.taskNumber,
      levelId: req.body?.levelId,
      questionId: req.body?.questionId,
      attachmentId: req.body?.attachmentId,
    });
    const ensured = ensureWorkbookQuestionSource({ student, target });
    const sourceFile = ensured.source;
    const savedSolutions = getWorkbookQuestionSolutionEntries(
      ensured.files,
      student.id,
      sourceFile.id
    );
    const requestedSolutionFileId = String(req.body?.solutionFileId || '').trim();
    const requestedSolution = requestedSolutionFileId
      ? savedSolutions.find(({ entry }) => entry.id === requestedSolutionFileId)
      : null;
    if (requestedSolutionFileId && !requestedSolution) {
      throw createWorkbookHttpError(404, 'Сохранённое решение не найдено');
    }
    const startFresh = req.body?.startFresh === true;
    const selectedSolution = requestedSolution || (!startFresh
      ? [...savedSolutions].sort((left, right) => (
        Date.parse(String(right.entry?.updatedAt || right.entry?.createdAt || ''))
        - Date.parse(String(left.entry?.updatedAt || left.entry?.createdAt || ''))
      ))[0]
      : null);
    const solutionSlot = startFresh
      ? Array.from({ length: MAX_WORKBOOK_QUESTION_SOLUTIONS }, (_, index) => index + 1)
        .find((slot) => !savedSolutions.some((saved) => saved.slot === slot))
      : (selectedSolution?.slot || 1);
    if (!solutionSlot) {
      throw createWorkbookHttpError(409, 'Уже сохранено три решения. Удалите одно, чтобы начать новое.');
    }
    const solutionFile = startFresh ? null : selectedSolution?.entry;
    const solutionKey = solutionFile
      ? (normalizeWorkbookSolutionKey(solutionFile.workbookSolutionKey)
        || buildWorkbookQuestionSolutionKey(student.id, sourceFile.id, solutionSlot))
      : buildWorkbookQuestionSolutionKey(student.id, sourceFile.id, solutionSlot);
    const resolved = resolveWorkbookSourceForStudent(
      student,
      sourceFile.id,
      ensured.files
    );
    if (!resolved) throw createWorkbookHttpError(410, 'Таблица больше недоступна');
    const solutionFileId = String(solutionFile?.id || '');
    const state = getWorkbookBindingState(student, sourceFile, ensured.files, {
      solutionKey,
      solutionFileId,
      nameRequired: false,
    });
    if (!state.contentHash) throw createWorkbookHttpError(410, 'Таблица больше недоступна');
    const launch = createWorkbookHelperLaunchTicket({
      studentId: student.id,
      sourceFileId: sourceFile.id,
      launchFileId: startFresh ? sourceFile.id : (solutionFile?.id || sourceFile.id),
      solutionKey,
      solutionFileId,
      nameRequired: false,
      startsFresh: startFresh,
    });
    return res.status(201).json({
      ticket: launch.ticket,
      expiresAt: new Date(launch.expiresAtMs).toISOString(),
      workbookKey: state.solutionKey,
      sourceFileId: sourceFile.id,
      fileName: state.fileName,
      solutionName: state.fileName,
      suggestedName: state.fileName,
      requiresName: false,
      nameRequired: false,
      revision: state.revision,
      contentHash: startFresh ? getWorkbookFileContentHash(sourceFile) : state.contentHash,
      hasSolution: savedSolutions.length > 0,
      solutionCount: savedSolutions.length,
      canCreateSolution: savedSolutions.length < MAX_WORKBOOK_QUESTION_SOLUTIONS,
      startsFresh: startFresh,
      solution: solutionFile ? serializeWorkbookQuestionSolution(solutionFile, solutionSlot) : null,
      opensSourceText: Boolean(target.blankForTextTask),
    });
  } catch (error) {
    return sendWorkbookOperationError(res, error);
  }
});

const requireStudentWorkbookSource = (req, res, next) => {
  if (!isStudentRole(req.auth)) return forbid(res);
  const student = findStudentById(req.auth.id);
  const resolved = student
    ? resolveWorkbookSourceForStudent(student, req.params?.sourceFileId)
    : null;
  if (!resolved) return res.status(404).json({ error: 'Исходная таблица не найдена' });
  req.workbookSolution = {
    student,
    sourceFile: resolved.sourceFile,
    solutionKey: resolved.solutionKey,
    solutionFileId: resolved.solutionFileId,
    files: resolved.files,
  };
  return next();
};

app.get(
  '/api/workbook-solutions/:sourceFileId/content',
  requireStudentWorkbookSource,
  (req, res) => {
    const {
      student,
      sourceFile,
      files,
      solutionKey,
      solutionFileId,
    } = req.workbookSolution;
    const state = getWorkbookBindingState(student, sourceFile, files, {
      solutionKey,
      solutionFileId,
    });
    const filePath = getWorkbookStoredFilePath(state.contentFile);
    if (!filePath || !state.contentHash) {
      return res.status(410).json({ error: 'Файл таблицы больше недоступен' });
    }
    const stat = fs.statSync(filePath);
    const requestSize = getRangeSize(req.headers.range, stat.size);
    const usage = getStudentUsage(student.id);
    if (usage.enabled && (usage.remaining <= 0 || usage.used + requestSize > usage.limit)) {
      return res.status(429).json({ error: 'Превышен лимит трафика для ученика' });
    }
    if (usage.enabled && (usage.used / usage.limit >= STUDENT_TRAFFIC_WARN_RATIO)) {
      res.setHeader('X-Traffic-Warn', '1');
    }
    registerUsageOnFinish(student.id, res, requestSize);
    res.setHeader('Cache-Control', 'no-store');
    res.setHeader('X-Workbook-Key', state.solutionKey);
    res.setHeader('X-Workbook-Revision', String(state.revision));
    res.setHeader('X-Workbook-Content-Hash', state.contentHash);
    res.attachment(state.fileName);
    return res.sendFile(filePath);
  }
);

app.put(
  '/api/workbook-solutions/:sourceFileId/content',
  requireStudentWorkbookSource,
  workbookHelperUpload.single('file'),
  async (req, res) => {
    if (!req.file) return res.status(400).json({ error: 'Файл не найден' });
    const rawExpectedRevision = req.body?.revision ?? req.headers['x-workbook-revision'];
    const expectedRevisionText = String(rawExpectedRevision ?? '').trim();
    if (!expectedRevisionText) {
      removeWorkbookUploadedFile(req.file);
      const state = getWorkbookBindingState(
        req.workbookSolution.student,
        req.workbookSolution.sourceFile,
        null,
        {
          solutionKey: req.workbookSolution.solutionKey,
          solutionFileId: req.workbookSolution.solutionFileId,
        }
      );
      return res.status(428).json({
        error: 'Перед сохранением получите актуальную ревизию таблицы',
        revision: state.revision,
        contentHash: state.contentHash,
      });
    }
    const expectedRevision = Number(expectedRevisionText);
    if (!Number.isInteger(expectedRevision) || expectedRevision < 0) {
      removeWorkbookUploadedFile(req.file);
      return res.status(400).json({ error: 'Некорректная ревизия таблицы' });
    }
    try {
      const result = await upsertWorkbookSolutionContent({
        student: req.workbookSolution.student,
        sourceFileId: req.workbookSolution.sourceFile.id,
        uploadedFile: req.file,
        actor: req.auth,
        source: normalizeFileMemorySource(req.body?.source, 'workbook-auto-sync'),
        memory: parseMemoryObject(req.body?.memory),
        expectedRevision,
        providedContentHash: req.body?.contentHash ?? req.headers['x-workbook-content-hash'] ?? '',
        solutionKey: req.workbookSolution.solutionKey,
        solutionFileId: req.workbookSolution.solutionFileId,
      });
      const [entryWithFolderPath] = enrichFilesWithFolderPath([result.entry], readFoldersDb());
      return res.json(entryWithFolderPath || result.entry);
    } catch (error) {
      return sendWorkbookOperationError(res, error);
    }
  }
);

