app.get('/api/student-social-chat-settings', (req, res) => {
  let teacherId = '';
  let teacher = null;
  if (isStudentRole(req.auth)) {
    const student = findStudentById(req.auth.id);
    if (!student?.teacherId) return res.status(404).json({ error: 'Ученик не найден' });
    teacherId = String(student.teacherId || '').trim();
    teacher = findTeacherById(teacherId);
    if (!teacher) return res.status(404).json({ error: 'Учитель не найден' });
  } else if (isTeacherRole(req.auth)) {
    teacherId = String(req.auth.id || '').trim();
  } else if (isAdminRole(req.auth)) {
    teacherId = String(req.query?.teacherId || '').trim();
  } else {
    return forbid(res);
  }

  if (!teacher) {
    teacher = ensureTeacherAccess(req, res, teacherId, { missingError: 'teacherId required' });
  }
  if (!teacher) return;
  return res.json({
    teacherId: teacher.id,
    settings: getStudentSocialChatSettings(teacher.id),
  });
});

app.patch('/api/student-social-chat-settings', (req, res) => {
  if (!isStaffRole(req.auth)) return forbid(res);
  const effectiveTeacherId = isTeacherRole(req.auth)
    ? req.auth.id
    : String(req.body?.teacherId || req.query?.teacherId || '').trim();
  const teacher = ensureTeacherAccess(req, res, effectiveTeacherId, { missingError: 'teacherId required' });
  if (!teacher) return;

  const patch = {};
  if (Object.prototype.hasOwnProperty.call(req.body || {}, 'directEnabled')) {
    patch.directEnabled = Boolean(req.body.directEnabled);
  }
  if (Object.prototype.hasOwnProperty.call(req.body || {}, 'groupEnabled')) {
    patch.groupEnabled = Boolean(req.body.groupEnabled);
  }
  if (!Object.prototype.hasOwnProperty.call(patch, 'directEnabled')
    && !Object.prototype.hasOwnProperty.call(patch, 'groupEnabled')) {
    return res.status(400).json({ error: 'Нет изменений' });
  }

  const settings = setStudentSocialChatSettings(teacher.id, patch);
  return res.json({
    ok: true,
    teacherId: teacher.id,
    settings,
  });
});

app.get('/api/teacher-social-group-chat', (req, res) => {
  if (!isStaffRole(req.auth)) return forbid(res);
  const effectiveTeacherId = isTeacherRole(req.auth)
    ? req.auth.id
    : String(req.query?.teacherId || '').trim();
  const db = readStudentSocialChatsDb();
  const access = ensureTeacherSocialGroupChatAccess(req, res, effectiveTeacherId, {
    db,
    chats: db.chats,
    persist: true,
  });
  if (!access) return;

  const { index, teacher, settings } = access;
  let chat = access.chat;
  let changed = access.changed || access.created;
  if (String(req.query?.markRead || '').trim() === '1') {
    const markResult = markStudentSocialChatReadByTeacher(chat);
    if (markResult.changed) {
      chat = normalizeStudentSocialChat(markResult.chat) || markResult.chat;
      db.chats[index] = chat;
      changed = true;
      broadcastStudentChatRead(chat, 'social-group', {
        role: 'teacher',
        id: req.auth.id,
        readAt: chat.lastReadByTeacherAt,
      });
    }
  }
  if (changed) writeStudentSocialChatsDb(db);

  const students = readStudentsDb()
    .filter((entry) => isCurrentStudent(entry) && String(entry.teacherId || '').trim() === teacher.id)
    .sort((left, right) => getStudentDisplayName(left).localeCompare(getStudentDisplayName(right), 'ru'))
    .map((student) => buildStudentPeerProfile(student, { exposeStudentNicknames: true }));
  const page = buildStudentChatMessagesPage(chat.messages, req.query);
  const responseOptions = buildStudentChatMessageResponseOptions(req.auth, { chat, teacher });

  return res.json({
    teacherId: teacher.id,
    settings,
    students,
    groupChat: buildStudentSocialChatSummary(chat, null, { settings, exposeStudentNicknames: true }),
    messages: enrichStudentSocialMessagesViewStats(chat, page.messages, {
      ...responseOptions,
      groupStudentIds: students.map((student) => student.id),
    }),
    pagination: page.pagination,
  });
});

app.post('/api/teacher-social-group-chat/messages', (req, res) => {
  if (!isStaffRole(req.auth)) return forbid(res);
  const text = normalizeStudentChatMessageText(req.body?.text);
  const attachmentPayload = normalizeStudentChatAttachmentPayload(req.body);
  const forwardSource = req.body?.forwardFrom
    ? resolveStudentChatForwardSource(req, res, req.body.forwardFrom)
    : null;
  if (res.headersSent) return;

  const messagePayload = mergeStudentChatForwardContent({ text, ...attachmentPayload }, forwardSource);
  const {
    text: messageText,
    imageDataUrl,
    imageName,
    fileDataUrl,
    fileName,
    fileMimeType,
    fileSize,
    code,
    codeLanguage,
  } = messagePayload;
  if (!messageText && !imageDataUrl && !fileDataUrl && !code) return res.status(400).json({ error: 'Введите сообщение или добавьте файл' });

  const effectiveTeacherId = isTeacherRole(req.auth)
    ? req.auth.id
    : String(req.body?.teacherId || req.query?.teacherId || '').trim();
  const db = readStudentSocialChatsDb();
  const access = ensureTeacherSocialGroupChatAccess(req, res, effectiveTeacherId, {
    db,
    chats: db.chats,
    persist: true,
  });
  if (!access) return;
  if (access.settings?.groupEnabled === false) {
    return res.status(403).json({ error: 'Общий чат группы отключён' });
  }

  const { index, teacher, settings } = access;
  const replyToMessageId = String(req.body?.replyToMessageId || '').trim();
  const replyTo = replyToMessageId
    ? buildStudentChatReplyReference(access.chat, replyToMessageId, {
      chatKind: 'group',
      chatTitle: getStudentSocialChatReferenceTitle(access.chat),
    })
    : null;
  if (replyToMessageId && !replyTo) return res.status(404).json({ error: 'Сообщение для ответа не найдено' });
  const senderName = String(teacher?.name || req.auth?.name || 'Преподаватель').trim() || 'Преподаватель';
  const message = createStudentTeacherChatMessage({
    senderRole: 'teacher',
    senderId: String(teacher?.id || req.auth?.id || '').trim(),
    senderName,
    text: messageText,
    imageDataUrl,
    imageName,
    fileDataUrl,
    fileName,
    fileMimeType,
    fileSize,
    code,
    codeLanguage,
    replyTo,
    forwardFrom: forwardSource?.reference,
  });
  if (!hasStudentTeacherChatMessageContent(message) || !message.senderId) {
    return res.status(400).json({ error: 'Некорректное сообщение' });
  }

  db.chats[index] = normalizeStudentSocialChat(appendStudentSocialChatMessage(access.chat, message)) || access.chat;
  writeStudentSocialChatsDb(db);
  const updatedChat = db.chats[index];
  broadcastStudentSocialChatMessageCreated(updatedChat, message);

  return res.json({
    ok: true,
    message: enrichStudentSocialMessageViewStats(updatedChat, message, {
      ...buildStudentChatMessageResponseOptions(req.auth, { chat: updatedChat, teacher }),
      groupStudentIds: getActiveStudentIdsForTeacher(updatedChat.teacherId),
    }),
    chat: buildStudentSocialChatSummary(updatedChat, null, { settings }),
  });
});

app.patch('/api/teacher-social-group-chat/messages/:messageId', (req, res) => {
  if (!isStaffRole(req.auth)) return forbid(res);
  const text = normalizeStudentChatMessageText(req.body?.text);
  if (!text) return res.status(400).json({ error: 'Введите сообщение' });
  const messageId = String(req.params?.messageId || '').trim();
  if (!messageId) return res.status(400).json({ error: 'messageId required' });

  const effectiveTeacherId = isTeacherRole(req.auth)
    ? req.auth.id
    : String(req.body?.teacherId || req.query?.teacherId || '').trim();
  const db = readStudentSocialChatsDb();
  const access = ensureTeacherSocialGroupChatAccess(req, res, effectiveTeacherId, {
    db,
    chats: db.chats,
    persist: true,
  });
  if (!access) return;

  const { index, teacher, settings } = access;
  const chat = access.chat;
  const messages = Array.isArray(chat.messages) ? [...chat.messages] : [];
  const messageIndex = messages.findIndex((message) => message?.id === messageId);
  if (messageIndex === -1) return res.status(404).json({ error: 'Сообщение не найдено' });

  const targetMessage = messages[messageIndex];
  if (!canModifyStudentSocialChatMessage(req.auth, chat, targetMessage)) {
    return res.status(403).json({ error: 'Недостаточно прав' });
  }

  if (targetMessage.text === text) {
    return res.json({
      ok: true,
      message: enrichStudentSocialMessageViewStats(chat, targetMessage, {
        ...buildStudentChatMessageResponseOptions(req.auth, { chat, teacher }),
        groupStudentIds: getActiveStudentIdsForTeacher(chat.teacherId),
      }),
      chat: buildStudentSocialChatSummary(chat, null, { settings }),
    });
  }

  const editedMessage = normalizeStudentTeacherChatMessage({
    ...targetMessage,
    text,
    editedAt: new Date().toISOString(),
  });
  if (!editedMessage) return res.status(400).json({ error: 'Некорректное сообщение' });

  messages[messageIndex] = editedMessage;
  db.chats[index] = rebuildStudentSocialChatAfterMessages(chat, messages);
  writeStudentSocialChatsDb(db);
  const updatedChat = db.chats[index];
  broadcastStudentChatMessageUpdated(updatedChat, editedMessage, 'social-group');

  return res.json({
    ok: true,
    message: enrichStudentSocialMessageViewStats(updatedChat, editedMessage, {
      ...buildStudentChatMessageResponseOptions(req.auth, { chat: updatedChat, teacher }),
      groupStudentIds: getActiveStudentIdsForTeacher(updatedChat.teacherId),
    }),
    chat: buildStudentSocialChatSummary(updatedChat, null, { settings }),
  });
});

app.post('/api/teacher-social-group-chat/messages/:messageId/reactions', (req, res) => {
  if (!isStaffRole(req.auth)) return forbid(res);
  const messageId = String(req.params?.messageId || '').trim();
  const emoji = normalizeStudentChatReactionEmoji(req.body?.emoji);
  if (!messageId) return res.status(400).json({ error: 'messageId required' });
  if (!emoji) return res.status(400).json({ error: 'Некорректная реакция' });

  const effectiveTeacherId = isTeacherRole(req.auth)
    ? req.auth.id
    : String(req.body?.teacherId || req.query?.teacherId || '').trim();
  const db = readStudentSocialChatsDb();
  const access = ensureTeacherSocialGroupChatAccess(req, res, effectiveTeacherId, {
    db,
    chats: db.chats,
    persist: true,
  });
  if (!access) return;

  const { index, teacher, settings } = access;
  const chat = access.chat;
  const actor = resolveStudentChatReactionActor(req.auth, { chat, teacher });
  if (!actor) return res.status(403).json({ error: 'Недостаточно прав' });

  const messages = Array.isArray(chat.messages) ? [...chat.messages] : [];
  const messageIndex = messages.findIndex((message) => message?.id === messageId);
  if (messageIndex === -1) return res.status(404).json({ error: 'Сообщение не найдено' });
  if (isStudentChatMessageAuthoredByActor(messages[messageIndex], actor)) {
    return res.status(403).json({ error: 'Нельзя реагировать на своё сообщение' });
  }

  messages[messageIndex] = applyStudentChatMessageReaction(messages[messageIndex], emoji, actor);
  db.chats[index] = rebuildStudentSocialChatAfterMessages(chat, messages);
  writeStudentSocialChatsDb(db);

  const updatedChat = db.chats[index];
  const updatedMessage = updatedChat.messages.find((message) => message?.id === messageId) || messages[messageIndex];
  broadcastStudentChatMessageUpdated(updatedChat, updatedMessage, 'social-group');
  return res.json({
    ok: true,
    message: enrichStudentSocialMessageViewStats(updatedChat, updatedMessage, {
      ...buildStudentChatMessageResponseOptions(req.auth, { chat: updatedChat, teacher }),
      groupStudentIds: getActiveStudentIdsForTeacher(updatedChat.teacherId),
    }),
    chat: buildStudentSocialChatSummary(updatedChat, null, { settings }),
  });
});

app.delete('/api/teacher-social-group-chat/messages/:messageId', (req, res) => {
  if (!isStaffRole(req.auth)) return forbid(res);
  const messageId = String(req.params?.messageId || '').trim();
  if (!messageId) return res.status(400).json({ error: 'messageId required' });

  const effectiveTeacherId = isTeacherRole(req.auth)
    ? req.auth.id
    : String(req.body?.teacherId || req.query?.teacherId || '').trim();
  const db = readStudentSocialChatsDb();
  const access = ensureTeacherSocialGroupChatAccess(req, res, effectiveTeacherId, {
    db,
    chats: db.chats,
    persist: true,
  });
  if (!access) return;

  const { index, settings } = access;
  const chat = access.chat;
  const messages = Array.isArray(chat.messages) ? [...chat.messages] : [];
  const messageIndex = messages.findIndex((message) => message?.id === messageId);
  if (messageIndex === -1) return res.status(404).json({ error: 'Сообщение не найдено' });

  const targetMessage = messages[messageIndex];
  const canDeletePinAnnouncement = canDeleteStudentChatPinAnnouncement(req.auth, chat, targetMessage, {
    teacher: findTeacherById(chat.teacherId),
  });
  if (!canDeletePinAnnouncement && !canModifyStudentSocialChatMessage(req.auth, chat, targetMessage)) {
    return res.status(403).json({ error: 'Недостаточно прав' });
  }
  if (!canDeletePinAnnouncement && !isStudentChatMessageDeleteAllowed(targetMessage)) {
    return res.status(403).json({ error: 'Удаление недоступно' });
  }

  messages.splice(messageIndex, 1);
  db.chats[index] = rebuildStudentSocialChatAfterMessages(chat, messages);
  writeStudentSocialChatsDb(db);
  const updatedChat = db.chats[index];
  broadcastStudentChatMessageDeleted(updatedChat, messageId, 'social-group');

  return res.json({
    ok: true,
    messageId,
    chat: buildStudentSocialChatSummary(updatedChat, null, { settings }),
  });
});

app.patch('/api/teacher-social-group-chat/messages/:messageId/pin', (req, res) => {
  if (!isStaffRole(req.auth)) return forbid(res);
  const messageId = String(req.params?.messageId || '').trim();
  if (!messageId) return res.status(400).json({ error: 'messageId required' });

  const effectiveTeacherId = isTeacherRole(req.auth)
    ? req.auth.id
    : String(req.body?.teacherId || req.query?.teacherId || '').trim();
  const db = readStudentSocialChatsDb();
  const access = ensureTeacherSocialGroupChatAccess(req, res, effectiveTeacherId, {
    db,
    chats: db.chats,
    persist: true,
  });
  if (!access) return;

  const { index, teacher, settings } = access;
  const chat = access.chat;
  const targetMessage = findStudentChatMessageById(chat, messageId);
  if (!targetMessage) return res.status(404).json({ error: 'Сообщение не найдено' });

  const pinned = chat.pinnedMessageId !== messageId;
  const announcement = pinned
    ? createStudentChatPinAnnouncementMessage({ auth: req.auth, teacher, chat, targetMessage })
    : null;
  const messages = announcement
    ? [...(Array.isArray(chat.messages) ? chat.messages : []), announcement]
    : chat.messages;
  db.chats[index] = rebuildStudentSocialChatAfterMessages({
    ...chat,
    pinnedMessageId: pinned ? messageId : '',
  }, messages);
  writeStudentSocialChatsDb(db);
  const updatedChat = db.chats[index];
  broadcastStudentChatMessagePinned(updatedChat, targetMessage, announcement, 'social-group', pinned);
  const responseOptions = {
    ...buildStudentChatMessageResponseOptions(req.auth, { chat: updatedChat, teacher }),
    groupStudentIds: getActiveStudentIdsForTeacher(updatedChat.teacherId),
  };

  return res.json({
    ok: true,
    pinned,
    message: enrichStudentSocialMessageViewStats(updatedChat, targetMessage, responseOptions),
    ...(announcement ? { announcement: enrichStudentSocialMessageViewStats(updatedChat, announcement, responseOptions) } : {}),
    chat: buildStudentSocialChatSummary(updatedChat, null, { settings }),
  });
});

app.get('/api/student-social-chats', (req, res) => {
  if (!isStudentRole(req.auth)) return forbid(res);
  const student = findStudentById(req.auth.id);
  if (!student?.id || !student?.teacherId) return res.status(404).json({ error: 'Ученик не найден' });

  const teacherId = String(student.teacherId || '').trim();
  const db = readStudentSocialChatsDb();
  const settings = getStudentSocialChatSettings(teacherId, db);
  const notificationSettings = getStudentChatNotificationSettings(student.id, db);
  const classmates = readStudentsDb()
    .filter((entry) => isCurrentStudent(entry) && String(entry.teacherId || '').trim() === teacherId)
    .sort((left, right) => getStudentPrimaryDisplayName(left).localeCompare(getStudentPrimaryDisplayName(right), 'ru'));
  const peers = classmates
    .filter((entry) => entry.id !== student.id)
    .map(buildStudentPeerProfile);
  const chatsById = new Map(db.chats.map((chat) => [chat.id, chat]));
  const peerById = new Map(peers.map((peer) => [peer.id, peer]));

  const groupChat = chatsById.get(buildStudentGroupChatId(teacherId))
    || createStudentSocialChat({ type: 'group', teacherId });
  const directChats = db.chats
    .filter((chat) => (
      chat?.type === 'direct'
      && String(chat.teacherId || '').trim() === teacherId
      && Array.isArray(chat.studentIds)
      && chat.studentIds.includes(student.id)
      && Array.isArray(chat.messages)
      && chat.messages.length > 0
    ))
    .map((chat) => {
      const peerId = chat.studentIds.find((item) => item !== student.id);
      const peer = peerById.get(peerId);
      if (!peer) return null;
      return buildStudentSocialChatSummary(chat, student, { peer, settings, notificationSettings });
    })
    .filter(Boolean);

  const sortedDirectChats = directChats
    .sort((left, right) => {
      const diff = getStudentSocialChatSortTimestamp(right) - getStudentSocialChatSortTimestamp(left);
      if (diff !== 0) return diff;
      return String(left.title || '').localeCompare(String(right.title || ''), 'ru');
    })
    .map((chat) => chat);

  return res.json({
    settings,
    notificationSettings,
    currentStudent: buildStudentPeerProfile(student),
    students: peers,
    groupChat: buildStudentSocialChatSummary(groupChat, student, { settings, notificationSettings }),
    directChats: sortedDirectChats,
  });
});

