const getLessonTopicsRange = (fromValue, toValue) => {
  const todayKey = normalizeLessonDayKey(getDatePartsInCalendarTimeZone(new Date())?.dayKey)
    || normalizeLessonDayKey(new Date().toISOString().slice(0, 10));
  const todayNumber = dayKeyToNumber(todayKey);
  const fallbackFrom = Number.isFinite(todayNumber) ? numberToDayKey(todayNumber - 14) : todayKey;
  const fallbackTo = Number.isFinite(todayNumber) ? numberToDayKey(todayNumber + 21) : todayKey;
  const fromDayKey = normalizeLessonDayKey(fromValue) || fallbackFrom;
  const toDayKey = normalizeLessonDayKey(toValue) || fallbackTo;
  const fromNumber = dayKeyToNumber(fromDayKey);
  const toNumber = dayKeyToNumber(toDayKey);
  if (
    !fromDayKey
    || !toDayKey
    || !Number.isFinite(fromNumber)
    || !Number.isFinite(toNumber)
    || toNumber < fromNumber
    || toNumber - fromNumber > 186
  ) {
    return null;
  }
  return { fromDayKey, toDayKey };
};

const getScheduleForLessonTopics = async (student, auth) => {
  const data = getStudentData(student.id);
  let schedule = Array.isArray(data.schedule) ? data.schedule : [];
  try {
    const syncResult = await syncStudentScheduleFromGoogleCalendar(student, auth, {
      force: false,
      persist: !isStudentRole(auth),
      rangeMode: GOOGLE_CALENDAR_SYNC_RANGE_UPCOMING,
      notify: false,
    });
    if (Array.isArray(syncResult?.schedule)) schedule = syncResult.schedule;
  } catch {
    // Local schedule and already persisted Google occurrences still provide a useful fallback.
  }
  return schedule;
};

const persistStudentLessonHistory = (studentId, items = [], tombstones = {}) => {
  const normalizedStudentId = String(studentId || '').trim();
  if (!normalizedStudentId) return;
  const store = readLessonHistoryStore();
  const nextOccurrences = { ...store.occurrences };
  const nextTombstones = { ...(store.tombstones || {}) };
  const normalizedTombstones = normalizeLessonHistoryStore(
    { tombstones },
    { timeZone: GOOGLE_CALENDAR_SYNC_TIME_ZONE }
  ).tombstones;
  const recordedAt = new Date().toISOString();
  let changed = false;
  Object.values(normalizedTombstones || {}).forEach((tombstone) => {
    if (tombstone?.studentId !== normalizedStudentId) return;
    const previous = nextTombstones[tombstone.key];
    const nextTombstone = {
      ...tombstone,
      recordedAt: previous?.recordedAt || tombstone.recordedAt || recordedAt,
    };
    if (JSON.stringify(previous || null) !== JSON.stringify(nextTombstone)) {
      nextTombstones[tombstone.key] = nextTombstone;
      changed = true;
    }
    if (nextOccurrences[tombstone.key]) {
      delete nextOccurrences[tombstone.key];
      changed = true;
    }
  });
  (Array.isArray(items) ? items : []).forEach((item) => {
    const previous = nextOccurrences[item?.key];
    const normalized = normalizeLessonHistoryRecord({
      ...item,
      studentId: normalizedStudentId,
      recordedAt: previous?.recordedAt || item?.recordedAt || recordedAt,
    }, { timeZone: GOOGLE_CALENDAR_SYNC_TIME_ZONE });
    if (!normalized || normalized.studentId !== normalizedStudentId) return;
    if (nextTombstones[normalized.key]) return;
    if (JSON.stringify(previous || null) === JSON.stringify(normalized)) return;
    nextOccurrences[normalized.key] = normalized;
    changed = true;
  });
  if (changed) writeLessonHistoryStore({ occurrences: nextOccurrences, tombstones: nextTombstones });
};

const updateLessonHistorySnapshotTopic = (occurrenceKey, topic) => {
  const key = String(occurrenceKey || '').trim();
  if (!key) return;
  const store = readLessonHistoryStore();
  const existing = store.occurrences[key];
  if (!existing) return;
  store.occurrences[key] = {
    ...existing,
    topic: topic || null,
  };
  writeLessonHistoryStore(store);
};

const buildResolvedStudentLessonHistory = async (student, auth, options = {}) => {
  const studentId = String(student?.id || '').trim();
  if (!studentId) return [];
  let schedule = Array.isArray(options.scheduleOverride)
    ? options.scheduleOverride
    : await getScheduleForLessonTopics(student, auth);
  schedule = Array.isArray(schedule) ? schedule : [];

  if (options.includeGoogle !== false && student.teacherId) {
    try {
      const googleEntries = (await fetchTeacherGoogleCalendarEntries(student.teacherId))
        .filter((entry) => doesPaymentScheduleEntryMatchStudent(entry, student));
      schedule = [...schedule, ...googleEntries];
    } catch {
      // Persisted schedule and previous history snapshots remain available offline.
    }
  }

  const topicStore = readLessonTopicsStore();
  const historyStore = readLessonHistoryStore();
  const financeDb = readTeacherFinanceDb();
  const teacherFinance = getTeacherFinanceTeacherEntry(financeDb, student.teacherId);
  const ledgerEntries = Object.values(teacherFinance.lessonLedger || {})
    .filter((entry) => String(entry?.studentId || '').trim() === studentId);
  const manualTopics = Object.values(topicStore.topics || {})
    .filter((entry) => String(entry?.studentId || '').trim() === studentId);
  const storedOccurrences = Object.values(historyStore.occurrences || {})
    .filter((entry) => String(entry?.studentId || '').trim() === studentId);
  const currentTombstones = collectLessonHistoryTombstones({
    studentId,
    schedule,
    recordedAt: new Date().toISOString(),
    timeZone: GOOGLE_CALENDAR_SYNC_TIME_ZONE,
  });
  const tombstones = {
    ...(historyStore.tombstones || {}),
    ...currentTombstones,
  };

  const occurrences = buildStudentLessonHistory({
    studentId,
    studentCreatedAt: student.createdAt,
    schedule,
    ledgerEntries,
    manualTopics,
    storedOccurrences,
    tombstones,
    nowMs: Date.now(),
    timeZone: GOOGLE_CALENDAR_SYNC_TIME_ZONE,
  });
  const resolvedTopics = resolveLessonTopicsForOccurrences({
    occurrences,
    manualTopics: topicStore.topics,
    activities: topicStore.activities,
    files: readFilesDb(),
  });
  const history = occurrences.map((occurrence) => ({
    ...occurrence,
    topic: resolvedTopics[occurrence.key] || occurrence.topic || null,
  }));
  if (options.persist !== false) persistStudentLessonHistory(studentId, history, tombstones);
  return history;
};

const getLessonReplayZonedParts = (timestampMs) => {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: GOOGLE_CALENDAR_SYNC_TIME_ZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23',
  }).formatToParts(new Date(timestampMs)).reduce((acc, part) => {
    if (part.type !== 'literal') acc[part.type] = part.value;
    return acc;
  }, {});
  return {
    dayKey: normalizeLessonDayKey(`${parts.year}-${parts.month}-${parts.day}`),
    time: normalizeLessonTime(`${parts.hour}:${parts.minute}`),
  };
};

const shiftLessonReplayDayKey = (dayKey, amount) => {
  const normalized = normalizeLessonDayKey(dayKey);
  if (!normalized) return '';
  const [year, month, day] = normalized.split('-').map(Number);
  const date = new Date(Date.UTC(year, month - 1, day + Number(amount || 0)));
  return `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, '0')}-${String(date.getUTCDate()).padStart(2, '0')}`;
};

const persistLessonReplayOccurrence = (occurrence) => {
  const normalized = normalizeLessonHistoryRecord({
    ...occurrence,
    source: occurrence?.source || 'lesson-replay',
    recordedAt: occurrence?.recordedAt || new Date().toISOString(),
  }, { timeZone: GOOGLE_CALENDAR_SYNC_TIME_ZONE });
  if (!normalized) return null;
  const store = readLessonHistoryStore();
  const previous = store.occurrences[normalized.key];
  store.occurrences[normalized.key] = {
    ...(previous || {}),
    ...normalized,
    subject: normalized.subject || previous?.subject || '',
    topic: previous?.topic || normalized.topic || null,
    recordedAt: previous?.recordedAt || normalized.recordedAt,
  };
  writeLessonHistoryStore(store);
  return normalized;
};

const getLessonReplaySchedule = async (student, auth) => {
  let schedule = await getScheduleForLessonTopics(student, auth);
  schedule = Array.isArray(schedule) ? schedule : [];
  if (!student?.teacherId) return schedule;
  try {
    const googleEntries = (await fetchTeacherGoogleCalendarEntries(student.teacherId))
      .filter((entry) => doesPaymentScheduleEntryMatchStudent(entry, student));
    return [...schedule, ...googleEntries];
  } catch {
    return schedule;
  }
};

const hasActivePlatformLessonCall = (student) => {
  const studentId = String(student?.id || '').trim();
  const teacherId = String(student?.teacherId || '').trim();
  if (!studentId || !teacherId) return false;
  const room = rtcRooms.get(`rtc:${teacherId}:${studentId}`);
  if (!room || room.size < 2) return false;
  let hasTeacher = false;
  let hasStudent = false;
  room.forEach((client) => {
    const role = String(client?.auth?.role || '').trim();
    const id = String(client?.auth?.id || '').trim();
    if (role === 'teacher' && id === teacherId) hasTeacher = true;
    if (role === 'student' && id === studentId) hasStudent = true;
  });
  return hasTeacher && hasStudent;
};

const resolveCurrentLessonReplayOccurrence = async (
  student,
  auth,
  nowMs = Date.now(),
  options = {}
) => {
  const studentId = String(student?.id || '').trim();
  if (!studentId) return null;
  const preferredOccurrenceKey = String(options?.preferredOccurrenceKey || '').trim().slice(0, 760);
  const preferActive = options?.preferActive === true;
  const allowFallback = options?.allowFallback !== false;
  const { dayKey } = getLessonReplayZonedParts(nowMs);
  const schedule = await getLessonReplaySchedule(student, auth);
  const occurrences = expandLessonScheduleOccurrences({
    studentId,
    schedule,
    fromDayKey: shiftLessonReplayDayKey(dayKey, -1),
    toDayKey: shiftLessonReplayDayKey(dayKey, 1),
    timeZone: GOOGLE_CALENDAR_SYNC_TIME_ZONE,
  });
  const candidates = occurrences
    .filter((occurrence) => (
      Number(nowMs) >= occurrence.startMs - 30 * 60 * 1000
      && Number(nowMs) <= occurrence.endMs + 2 * 60 * 60 * 1000
    ))
    .sort((left, right) => {
      const distance = (occurrence) => {
        if (nowMs < occurrence.startMs) return occurrence.startMs - nowMs;
        if (nowMs > occurrence.endMs) return nowMs - occurrence.endMs;
        return 0;
      };
      return distance(left) - distance(right) || left.startMs - right.startMs;
    });

  const active = activeLessonReplayOccurrenceByStudentId.get(studentId);
  const activeIsRecent = Boolean(
    active
    && Number(nowMs) - Number(active.lastSeenAt || 0) < 3 * 60 * 60 * 1000
    && Number(nowMs) >= Number(active.occurrence?.startMs || 0) - 30 * 60 * 1000
    && Number(nowMs) <= Number(active.occurrence?.endMs || 0) + 2 * 60 * 60 * 1000
  );
  const historyStore = readLessonHistoryStore();
  const preferredStored = preferredOccurrenceKey
    ? normalizeLessonHistoryRecord(historyStore.occurrences?.[preferredOccurrenceKey], {
      timeZone: GOOGLE_CALENDAR_SYNC_TIME_ZONE,
    })
    : null;
  const preferredOccurrence = occurrences.find((entry) => entry.key === preferredOccurrenceKey)
    || (activeIsRecent && active.occurrence?.key === preferredOccurrenceKey ? active.occurrence : null)
    || (
      preferredStored?.studentId === studentId
      && Number(nowMs) >= Number(preferredStored.startMs || 0) - 30 * 60 * 1000
      && Number(nowMs) <= Number(preferredStored.endMs || 0) + 2 * 60 * 60 * 1000
        ? preferredStored
        : null
    );

  let occurrence = preferredOccurrence
    || (preferActive && activeIsRecent ? active.occurrence : null)
    || candidates[0]
    || null;
  if (
    !occurrence
    && activeIsRecent
  ) occurrence = active.occurrence;
  if (!occurrence && !allowFallback) return null;
  if (!occurrence) {
    // A real platform call can be started outside the timetable. Keep it in the
    // same history instead of silently losing the replay.
    const zoned = getLessonReplayZonedParts(nowMs);
    occurrence = Object.values(historyStore.occurrences || {})
      .filter((entry) => (
        String(entry?.studentId || '').trim() === studentId
        && entry?.dayKey === zoned.dayKey
        && entry?.source === 'lesson-replay'
        && Number(nowMs) >= Number(entry?.startMs || 0) - 30 * 60 * 1000
        && Number(nowMs) <= Number(entry?.endMs || 0) + 2 * 60 * 60 * 1000
      ))
      .sort((left, right) => Number(right?.startMs || 0) - Number(left?.startMs || 0))[0]
      || normalizeLessonHistoryRecord({
        studentId,
        dayKey: zoned.dayKey,
        time: zoned.time,
        durationMinutes: 60,
        subject: 'Занятие на платформе',
        source: 'lesson-replay',
        recordedAt: new Date(nowMs).toISOString(),
      }, { timeZone: GOOGLE_CALENDAR_SYNC_TIME_ZONE });
  }
  const persisted = persistLessonReplayOccurrence({
    ...occurrence,
    studentId,
    source: occurrence?.source || 'lesson-replay',
  });
  if (!persisted) return null;
  activeLessonReplayOccurrenceByStudentId.set(studentId, {
    occurrence: persisted,
    lastSeenAt: Number(nowMs),
  });
  return persisted;
};

const serializeTelemostLessonReplayActivity = (entry, nowMs = Date.now()) => {
  if (!entry?.occurrence?.key) return null;
  const autoFinishAtMs = Number(entry.autoFinishAtMs || 0);
  return {
    active: autoFinishAtMs > Number(nowMs),
    mode: 'telemost',
    studentId: String(entry.studentId || '').trim(),
    occurrenceKey: entry.occurrence.key,
    occurrence: entry.occurrence,
    startedAt: String(entry.startedAt || '').trim(),
    autoFinishAt: Number.isFinite(autoFinishAtMs) && autoFinishAtMs > 0
      ? new Date(autoFinishAtMs).toISOString()
      : '',
    requestId: String(entry.requestId || '').trim(),
  };
};

const getTelemostLessonReplayEntry = (studentId, nowMs = Date.now()) => {
  const normalizedStudentId = String(studentId || '').trim();
  if (!normalizedStudentId) return null;
  const entry = activeTelemostLessonReplayByStudentId.get(normalizedStudentId);
  if (!entry || Number(entry.autoFinishAtMs || 0) <= Number(nowMs)) return null;
  return entry;
};

const activateTelemostLessonReplay = async ({
  student,
  auth,
  nowMs = Date.now(),
  preferredOccurrenceKey = '',
  requestId = '',
} = {}) => {
  const studentId = String(student?.id || '').trim();
  if (!studentId) {
    const error = new Error('Ученик не найден');
    error.statusCode = 404;
    throw error;
  }

  const current = getTelemostLessonReplayEntry(studentId, nowMs);
  if (
    current
    && (!preferredOccurrenceKey || current.occurrence?.key === preferredOccurrenceKey)
  ) {
    current.lastSeenAt = Number(nowMs);
    if (requestId) current.requestId = String(requestId).trim();
    return serializeTelemostLessonReplayActivity(current, nowMs);
  }

  const hasPlatformCall = hasActivePlatformLessonCall(student);
  const occurrence = await resolveCurrentLessonReplayOccurrence(student, auth, nowMs, {
    preferredOccurrenceKey,
    preferActive: true,
    allowFallback: hasPlatformCall,
  });
  if (!occurrence) {
    const error = new Error('Сейчас нет занятия, к которому можно привязать запись Телемоста');
    error.statusCode = 409;
    throw error;
  }
  const autoFinishAtMs = Number(occurrence.endMs || 0) + TELEMOST_LESSON_BUFFER_MS;
  if (!Number.isFinite(autoFinishAtMs) || autoFinishAtMs <= Number(nowMs)) {
    const error = new Error('Время этого занятия с запасом уже закончилось');
    error.statusCode = 409;
    throw error;
  }

  const entry = {
    studentId,
    teacherId: String(student.teacherId || '').trim(),
    occurrence,
    startedAt: new Date(nowMs).toISOString(),
    autoFinishAtMs,
    lastSeenAt: Number(nowMs),
    requestId: String(requestId || '').trim(),
  };
  activeTelemostLessonReplayByStudentId.set(studentId, entry);
  activeLessonReplayOccurrenceByStudentId.set(studentId, {
    occurrence,
    lastSeenAt: Number(nowMs),
  });
  return serializeTelemostLessonReplayActivity(entry, nowMs);
};

const isLessonReplaySessionWritable = (session, student, nowMs = Date.now()) => {
  if (hasActivePlatformLessonCall(student)) {
    session.lastPlatformActiveAt = Number(nowMs);
    return true;
  }
  const telemost = getTelemostLessonReplayEntry(student?.id, nowMs);
  if (telemost && telemost.occurrence?.key === session?.occurrenceKey) return true;
  return Boolean(
    session?.via === 'platform'
    && Number(session.lastPlatformActiveAt || 0) > 0
    && Number(nowMs) - Number(session.lastPlatformActiveAt) <= LESSON_REPLAY_PLATFORM_DISCONNECT_GRACE_MS
  );
};

const serializeLessonReplayForClient = (replay) => {
  if (!replay) return null;
  const summary = getLessonReplaySummary(replay.occurrence.key, replay);
  return {
    ...summary,
    occurrence: replay.occurrence,
    events: replay.events.map((event) => ({
      id: event.id,
      type: event.type,
      occurredAt: event.occurredAt,
      offsetMs: event.offsetMs,
      actor: {
        role: event.actor?.role || 'student',
        name: event.actor?.name || '',
      },
      payload: event.payload,
    })),
  };
};

const serializeStudentLessonHistoryEntry = (entry, replayStorage = null) => ({
  key: entry.key,
  dayKey: entry.dayKey,
  time: entry.time,
  durationMinutes: entry.durationMinutes,
  startMs: entry.startMs,
  endMs: entry.endMs,
  subject: entry.subject,
  topic: entry.topic || null,
  ...(replayStorage ? { replayStorage } : {}),
});

const getLessonMaterialFileStudentId = (file) => {
  const explicitStudentId = String(file?.lessonStudentId || file?.originalStudentId || '').trim();
  if (explicitStudentId) return explicitStudentId;
  if (isLessonSharedFile(file)) return '';
  return String(file?.studentId || '').trim();
};

const getLessonMaterialLegacyTimestamp = (file) => {
  const candidates = [
    file?.lessonSavedAt,
    file?.memory?.boardSnapshot?.createdAt,
    file?.createdAt,
  ];
  return candidates.reduce((latest, value) => {
    const parsed = Date.parse(String(value || '').trim());
    if (!Number.isFinite(parsed) || parsed <= latest) return latest;
    return parsed;
  }, Number.NEGATIVE_INFINITY);
};

const serializeStudentLessonMaterial = (file, activityEntries = [], fallbackSavedAtMs = NaN) => {
  const activityTimes = activityEntries
    .map((entry) => Date.parse(String(entry?.occurredAt || '').trim()))
    .filter(Number.isFinite);
  const savedAtMs = activityTimes.length > 0
    ? Math.max(...activityTimes)
    : fallbackSavedAtMs;
  return {
    id: String(file?.id || '').trim(),
    name: String(file?.name || '').trim(),
    taskNumber: Number.isFinite(Number(file?.taskNumber)) ? Number(file.taskNumber) : null,
    category: String(file?.category || '').trim(),
    folderId: file?.folderId || null,
    folderName: String(file?.folderName || '').trim(),
    folderPath: Array.isArray(file?.folderPath) ? file.folderPath : [],
    url: String(file?.url || '').trim(),
    size: String(file?.size || '').trim(),
    sizeBytes: Number.isFinite(Number(file?.sizeBytes)) ? Number(file.sizeBytes) : 0,
    createdAt: String(file?.createdAt || '').trim(),
    lessonSavedAt: String(file?.lessonSavedAt || '').trim(),
    savedAt: Number.isFinite(savedAtMs) ? new Date(savedAtMs).toISOString() : '',
    source: String(file?.source || file?.memory?.source || '').trim(),
    memory: file?.memory && typeof file.memory === 'object' && !Array.isArray(file.memory)
      ? file.memory
      : null,
    activitySources: Array.from(new Set(
      activityEntries
        .map((entry) => String(entry?.source || '').trim())
        .filter(Boolean)
    )),
  };
};

const collectStudentLessonMaterials = (student, occurrence) => {
  const studentId = String(student?.id || '').trim();
  const startMs = Number(occurrence?.startMs);
  const endMs = Number(occurrence?.endMs);
  if (!studentId || !Number.isFinite(startMs) || !Number.isFinite(endMs)) return [];

  const windowStartMs = startMs - LESSON_NOTE_LEAD_MS;
  const windowEndMs = endMs + LESSON_NOTE_TAIL_MS;
  const topicStore = readLessonTopicsStore();
  const allActivities = (Array.isArray(topicStore.activities) ? topicStore.activities : [])
    .map((entry) => normalizeLessonNoteActivity(entry))
    .filter(Boolean);
  const matchingActivitiesByFileId = new Map();
  const filesWithStoredActivity = new Set();

  allActivities.forEach((activity) => {
    if (activity.studentId !== studentId || !activity.fileId) return;
    filesWithStoredActivity.add(activity.fileId);
    const occurredAtMs = Date.parse(activity.occurredAt);
    if (
      !Number.isFinite(occurredAtMs)
      || occurredAtMs < windowStartMs
      || occurredAtMs > windowEndMs
    ) {
      return;
    }
    const entries = matchingActivitiesByFileId.get(activity.fileId) || [];
    entries.push(activity);
    matchingActivitiesByFileId.set(activity.fileId, entries);
  });

  const materials = [];
  enrichFilesWithFolderPath(readFilesDb(), readFoldersDb()).forEach((file) => {
    if (!file?.id || String(file?.category || '').trim() !== 'class') return;
    const fileStudentId = getLessonMaterialFileStudentId(file);
    const isSharedForTeacher = isLessonSharedFile(file)
      && normalizeTeacherId(file?.teacherId) === normalizeTeacherId(student?.teacherId);
    if (fileStudentId !== studentId && !isSharedForTeacher) return;

    const activityEntries = matchingActivitiesByFileId.get(String(file.id)) || [];
    if (activityEntries.length > 0) {
      materials.push(serializeStudentLessonMaterial(file, activityEntries));
      return;
    }

    // Older note files predate explicit activity records. Their saved timestamp is
    // still enough to associate them with the lesson, unless a newer activity log
    // already provides a more reliable history for that file.
    if (fileStudentId !== studentId || filesWithStoredActivity.has(String(file.id))) return;
    const legacySavedAtMs = getLessonMaterialLegacyTimestamp(file);
    if (
      !Number.isFinite(legacySavedAtMs)
      || legacySavedAtMs < windowStartMs
      || legacySavedAtMs > windowEndMs
    ) {
      return;
    }
    materials.push(serializeStudentLessonMaterial(file, [], legacySavedAtMs));
  });

  return materials.sort((left, right) => {
    const taskDiff = (Number(left.taskNumber) || 0) - (Number(right.taskNumber) || 0);
    if (taskDiff !== 0) return taskDiff;
    const timeDiff = Date.parse(left.savedAt || 0) - Date.parse(right.savedAt || 0);
    if (Number.isFinite(timeDiff) && timeDiff !== 0) return timeDiff;
    return left.name.localeCompare(right.name, 'ru');
  });
};

const STUDENT_SEARCH_DEFAULT_LIMIT = 30;
const STUDENT_SEARCH_MAX_LIMIT = 50;
const STUDENT_SEARCH_MAX_RESULTS_BEFORE_LIMIT = 240;
const STUDENT_SEARCH_MAX_FILES = 400;
const STUDENT_SEARCH_MAX_FILE_BYTES = 768 * 1024;
const STUDENT_SEARCH_MAX_TOTAL_FILE_BYTES = 8 * 1024 * 1024;
const STUDENT_SEARCH_FILE_CACHE_MAX_BYTES = 12 * 1024 * 1024;
const STUDENT_SEARCH_FILE_CACHE_MAX_ENTRIES = 320;
const STUDENT_SEARCH_TEXT_EXTENSIONS = new Set([
  '.py', '.pyw', '.txt', '.md', '.markdown', '.json', '.jsonl', '.csv', '.tsv',
  '.js', '.jsx', '.ts', '.tsx', '.html', '.htm', '.css', '.scss', '.sql',
  '.yaml', '.yml', '.toml', '.ini', '.cfg', '.log', '.xml', '.ipynb',
  '.c', '.cpp', '.h', '.hpp', '.java', '.kt', '.go', '.rs', '.php', '.rb',
  '.sh', '.ps1', '.bat',
]);
const STUDENT_SEARCH_PRIVATE_OBJECT_KEY_PATTERN = /^(?:answer.*|correct.*|expected.*|solution.*|output|codeHash|codeLookupHash|codeHint|storageName|url|imageDataUrl|avatarDataUrl)$/i;
const studentSearchFileCache = new Map();
let studentSearchFileCacheBytes = 0;

const isStudentSearchTextFile = (file) => {
  const extension = path.extname(String(file?.name || '')).toLowerCase();
  if (STUDENT_SEARCH_TEXT_EXTENSIONS.has(extension)) return true;
  const mimeType = String(file?.mimeType || '').trim().toLowerCase();
  return mimeType.startsWith('text/')
    || mimeType === 'application/json'
    || mimeType === 'application/xml';
};

const getStudentSearchFileTimestampMs = (file) => {
  const candidates = [file?.updatedAt, file?.lessonSavedAt, file?.memory?.createdAt, file?.createdAt];
  for (const candidate of candidates) {
    const parsed = Date.parse(String(candidate || '').trim());
    if (Number.isFinite(parsed)) return parsed;
  }
  return 0;
};

const pruneStudentSearchFileCache = () => {
  while (
    studentSearchFileCache.size > STUDENT_SEARCH_FILE_CACHE_MAX_ENTRIES
    || studentSearchFileCacheBytes > STUDENT_SEARCH_FILE_CACHE_MAX_BYTES
  ) {
    const oldestKey = studentSearchFileCache.keys().next().value;
    if (!oldestKey) break;
    const oldest = studentSearchFileCache.get(oldestKey);
    studentSearchFileCache.delete(oldestKey);
    studentSearchFileCacheBytes = Math.max(0, studentSearchFileCacheBytes - (Number(oldest?.sizeBytes) || 0));
  }
};

const readStudentSearchFileText = async (file, byteBudget) => {
  if (!isStudentSearchTextFile(file)) return { text: '', skipped: false, bytes: 0 };
  const safeStorageName = path.basename(String(file?.storageName || '').trim());
  if (!safeStorageName) return { text: '', skipped: false, bytes: 0 };
  const rootPath = `${path.resolve(uploadsDir)}${path.sep}`;
  const filePath = path.resolve(uploadsDir, safeStorageName);
  if (!filePath.startsWith(rootPath)) return { text: '', skipped: true, bytes: 0 };

  let stat;
  try {
    stat = await fs.promises.stat(filePath);
  } catch {
    return { text: '', skipped: false, bytes: 0 };
  }
  const sizeBytes = Math.max(0, Number(stat.size) || 0);
  if (
    !stat.isFile()
    || sizeBytes > STUDENT_SEARCH_MAX_FILE_BYTES
    || byteBudget.used + sizeBytes > STUDENT_SEARCH_MAX_TOTAL_FILE_BYTES
  ) {
    return { text: '', skipped: true, bytes: 0 };
  }
  byteBudget.used += sizeBytes;
  const cacheKey = `${safeStorageName}:${Number(stat.mtimeMs) || 0}:${sizeBytes}`;
  const cached = studentSearchFileCache.get(cacheKey);
  if (cached) {
    studentSearchFileCache.delete(cacheKey);
    studentSearchFileCache.set(cacheKey, cached);
    return { text: cached.text, skipped: false, bytes: sizeBytes };
  }

  let buffer;
  try {
    buffer = await fs.promises.readFile(filePath);
  } catch {
    return { text: '', skipped: false, bytes: sizeBytes };
  }
  if (buffer.includes(0)) return { text: '', skipped: true, bytes: sizeBytes };
  const text = buffer.toString('utf8');
  studentSearchFileCache.set(cacheKey, { text, sizeBytes });
  studentSearchFileCacheBytes += sizeBytes;
  pruneStudentSearchFileCache();
  return { text, skipped: false, bytes: sizeBytes };
};

const collectStudentSearchObjectText = (value, options = {}) => {
  const maxChars = Math.max(1000, Math.min(80_000, Number(options.maxChars) || 24_000));
  const chunks = [];
  const seen = new Set();
  let totalChars = 0;
  const visit = (current, depth) => {
    if (totalChars >= maxChars || depth > 5 || current === null || typeof current === 'undefined') return;
    if (typeof current === 'string' || typeof current === 'number') {
      const text = String(current).replace(/\0/g, '').trim();
      if (!text) return;
      const chunk = text.slice(0, maxChars - totalChars);
      chunks.push(chunk);
      totalChars += chunk.length + 1;
      return;
    }
    if (typeof current !== 'object' || seen.has(current)) return;
    seen.add(current);
    if (Array.isArray(current)) {
      current.slice(0, 120).forEach((entry) => visit(entry, depth + 1));
      return;
    }
    Object.entries(current).slice(0, 120).forEach(([key, entry]) => {
      if (STUDENT_SEARCH_PRIVATE_OBJECT_KEY_PATTERN.test(key)) return;
      visit(entry, depth + 1);
    });
  };
  visit(value, 0);
  return chunks.join('\n');
};

const getStudentSearchTaskTitle = (taskNumber, taskTitles, testsDb) => {
  const taskKey = String(taskNumber);
  const stored = taskTitles?.[taskKey] ?? testsDb?.[taskKey]?.title;
  if (typeof stored === 'string' && stored.trim()) return stored.trim();
  if (stored && typeof stored === 'object' && typeof stored.title === 'string' && stored.title.trim()) {
    return stored.title.trim();
  }
  return `Задание №${taskNumber}`;
};

const getStudentSearchFileTargetFolderId = (file, taskNumber) => {
  const storedFolderId = String(file?.folderId || '').trim();
  if (storedFolderId) {
    if (isLessonSharedFile(file) && Number.isFinite(taskNumber)) {
      const teacherId = normalizeTeacherId(file?.teacherId)
        || extractTeacherIdFromLessonSharedStudentId(file?.studentId);
      const sharedRootFolderId = teacherId ? buildLessonSharedFolderId(teacherId, taskNumber) : '';
      if (sharedRootFolderId && storedFolderId === sharedRootFolderId) return null;
    }
    return storedFolderId;
  }
  if (!isLessonSharedFile(file) || !Number.isFinite(taskNumber)) return null;
  return null;
};

const getStudentSearchFileKind = (file) => {
  const source = String(file?.source || file?.memory?.source || '').trim();
  const kind = String(file?.memory?.kind || '').trim();
  if (source === 'notes-cheatsheet' || kind === 'cheatsheet') {
    return { kind: 'cheatsheet', group: 'code', sourceLabel: 'Шпаргалка' };
  }
  if (source === 'collab-code' || kind === 'code' || isPyFileName(file?.name)) {
    return { kind: 'saved-code', group: 'code', sourceLabel: 'Сохранённый код' };
  }
  return { kind: 'file', group: 'notes', sourceLabel: 'Конспект' };
};

const collectStudentSavedCodeSearchCandidates = ({ student, studentData, taskTitles, testsDb, addCandidate }) => {
  const solvedByTask = studentData?.solvedByTask && typeof studentData.solvedByTask === 'object'
    ? studentData.solvedByTask
    : {};
  Object.entries(solvedByTask).forEach(([taskKey, taskEntry]) => {
    if (!taskEntry || typeof taskEntry !== 'object' || Array.isArray(taskEntry)) return;
    const taskNumber = Number(taskKey);
    if (!Number.isFinite(taskNumber)) return;
    const taskTitle = getStudentSearchTaskTitle(taskNumber, taskTitles, testsDb);
    const taskCode = taskEntry._taskCode && typeof taskEntry._taskCode === 'object'
      ? taskEntry._taskCode
      : null;
    if (taskCode && (String(taskCode.code || '').trim() || String(taskCode.input || '').trim())) {
      addCandidate({
        result: {
          id: `saved-code:task:${taskNumber}`,
          kind: 'saved-code',
          group: 'code',
          title: taskTitle,
          subtitle: 'Общий код задания',
          sourceLabel: 'Сохранённый код',
          timestamp: String(taskCode.updatedAt || ''),
          target: { kind: 'task', taskNumber, targetQuestions: null },
        },
        fields: [
          { name: 'title', text: taskTitle, weight: 650 },
          { name: 'content', text: [taskCode.code, taskCode.input].filter(Boolean).join('\n'), weight: 520 },
        ],
      });
    }
    Object.entries(taskEntry).forEach(([levelId, levelEntry]) => {
      if (levelId.startsWith('_') || !levelEntry || typeof levelEntry !== 'object' || Array.isArray(levelEntry)) return;
      const byQuestionId = levelEntry._questionCodeById && typeof levelEntry._questionCodeById === 'object'
        ? levelEntry._questionCodeById
        : {};
      Object.entries(byQuestionId).forEach(([questionId, savedCode]) => {
        if (!savedCode || typeof savedCode !== 'object') return;
        const content = [savedCode.code, savedCode.input].filter(Boolean).join('\n');
        if (!content.trim()) return;
        addCandidate({
          result: {
            id: `saved-code:question:${taskNumber}:${levelId}:${questionId}`,
            kind: 'saved-code',
            group: 'code',
            title: `${taskTitle} · задача ${questionId}`,
            subtitle: `Уровень: ${levelId}`,
            sourceLabel: 'Код задачи',
            timestamp: String(savedCode.updatedAt || ''),
            target: { kind: 'task', taskNumber, levelId, targetQuestions: [String(questionId)] },
          },
          fields: [
            { name: 'title', text: `${taskTitle} ${questionId} ${levelId}`, weight: 650 },
            { name: 'content', text: content, weight: 520 },
          ],
        });
      });

      const solvedCodeByQuestion = levelEntry.solvedCode && typeof levelEntry.solvedCode === 'object'
        && !Array.isArray(levelEntry.solvedCode)
        ? levelEntry.solvedCode
        : {};
      Object.entries(solvedCodeByQuestion).forEach(([questionId, solvedCode]) => {
        const content = String(solvedCode || '');
        if (!content.trim()) return;
        addCandidate({
          result: {
            id: `solved-code:question:${taskNumber}:${levelId}:${questionId}`,
            kind: 'solved-code',
            group: 'code',
            title: `${taskTitle} · решённая задача ${questionId}`,
            subtitle: `Уровень: ${levelId}`,
            sourceLabel: 'Отправленное решение',
            target: { kind: 'task', taskNumber, levelId, targetQuestions: [String(questionId)] },
          },
          fields: [
            { name: 'title', text: `${taskTitle} ${questionId} ${levelId}`, weight: 650 },
            { name: 'content', text: content, weight: 540 },
          ],
        });
      });
    });
  });

  const generalNote = String(studentData?.notes || '').trim();
  if (generalNote) {
    addCandidate({
      result: {
        id: `student-note:${student.id}:general`,
        kind: 'student-note',
        group: 'notes',
        title: 'Личная заметка',
        subtitle: 'Заметки об обучении',
        sourceLabel: 'Заметка',
        target: { kind: 'progress-section', progressSection: 'notes' },
      },
      fields: [
        { name: 'title', text: 'Личная заметка', weight: 650 },
        { name: 'content', text: generalNote, weight: 420 },
      ],
    });
  }
  Object.entries(studentData?.notesByTask || {}).forEach(([taskKey, note]) => {
    const taskNumber = Number(taskKey);
    if (!Number.isFinite(taskNumber) || !String(note || '').trim()) return;
    const taskTitle = getStudentSearchTaskTitle(taskNumber, taskTitles, testsDb);
    addCandidate({
      result: {
        id: `student-note:${student.id}:task:${taskNumber}`,
        kind: 'student-note',
        group: 'notes',
        title: taskTitle,
        subtitle: 'Заметка к заданию',
        sourceLabel: 'Заметка',
        target: { kind: 'progress-section', progressSection: 'notes', taskNumber },
      },
      fields: [
        { name: 'title', text: taskTitle, weight: 650 },
        { name: 'content', text: note, weight: 420 },
      ],
    });
  });
};

const collectStudentQuestionSearchCandidates = ({ testsDb, taskTitles, addCandidate }) => {
  Object.entries(testsDb || {}).forEach(([taskKey, taskEntry]) => {
    if (!taskEntry || typeof taskEntry !== 'object' || Array.isArray(taskEntry)) return;
    const taskNumber = Number(taskKey);
    if (!Number.isFinite(taskNumber)) return;
    const taskTitle = getStudentSearchTaskTitle(taskNumber, taskTitles, testsDb);
    const theoryBySubsection = taskEntry.pythonTheoryBySubsection
      && typeof taskEntry.pythonTheoryBySubsection === 'object'
      && !Array.isArray(taskEntry.pythonTheoryBySubsection)
      ? taskEntry.pythonTheoryBySubsection
      : {};
    Object.entries(theoryBySubsection).forEach(([subsectionId, theoryEntry]) => {
      const content = collectStudentSearchObjectText(theoryEntry, { maxChars: 64_000 });
      if (!content) return;
      const subsectionLabel = subsectionId === '__default__' ? 'Общая теория' : `Раздел ${subsectionId}`;
      addCandidate({
        result: {
          id: `theory:${taskNumber}:${subsectionId}`,
          kind: 'theory',
          group: 'tasks',
          title: `${taskTitle} · ${subsectionLabel}`,
          subtitle: 'Теория и шаблоны кода',
          sourceLabel: 'Теория Python',
          target: {
            kind: 'task',
            taskNumber,
            levelId: 'python',
            targetQuestions: null,
            subsectionId,
          },
        },
        fields: [
          { name: 'title', text: `${taskTitle} ${subsectionLabel}`, weight: 650 },
          { name: 'content', text: content, weight: 360 },
        ],
      });
    });
    Object.entries(taskEntry).forEach(([levelId, questions]) => {
      if (!Array.isArray(questions)) return;
      questions.forEach((question, index) => {
        if (!question || typeof question !== 'object') return;
        const questionId = String(question.id ?? index + 1);
        const questionTitle = String(question.title || '').trim();
        const title = questionTitle || `${taskTitle} · задача ${index + 1}`;
        const content = collectStudentSearchObjectText(question, { maxChars: 32_000 });
        if (!content) return;
        addCandidate({
          result: {
            id: `question:${taskNumber}:${levelId}:${questionId}`,
            kind: 'question',
            group: 'tasks',
            title,
            subtitle: `${taskTitle} · ${levelId}`,
            sourceLabel: 'Условие задачи',
            target: { kind: 'task', taskNumber, levelId, targetQuestions: [questionId] },
          },
          fields: [
            { name: 'title', text: `${title} ${taskTitle} ${questionId}`, weight: 650 },
            { name: 'content', text: content, weight: 300 },
          ],
        });
      });
    });
  });
};

const collectStudentMockSearchCandidates = ({ student, studentData, taskTitles, testsDb, addCandidate }) => {
  const visibleMocks = readMockExamsDb().filter((exam) => isMockExamVisibleToStudent(exam, student.id));
  visibleMocks.forEach((exam) => {
    const safeExam = sanitizeMockExamForStudent(exam);
    const examId = String(safeExam?.id || '').trim();
    if (!examId) return;
    const examTitle = String(safeExam.title || 'Пробник').trim();
    const badges = Array.isArray(safeExam.badges)
      ? safeExam.badges.map((badge) => String(badge?.label || badge || '').trim()).filter(Boolean).join(' ')
      : '';
    addCandidate({
      result: {
        id: `mock:${examId}`,
        kind: 'mock',
        group: 'mocks',
        title: examTitle,
        subtitle: badges || 'Пробник',
        sourceLabel: 'Пробник',
        timestamp: String(safeExam.updatedAt || safeExam.createdAt || ''),
        target: { kind: 'mock', examId },
      },
      fields: [
        { name: 'title', text: examTitle, weight: 680 },
        { name: 'metadata', text: [badges, safeExam.source].filter(Boolean).join(' '), weight: 180 },
      ],
    });
    Object.entries(safeExam.tasks || {}).forEach(([taskKey, question]) => {
      if (!question || typeof question !== 'object') return;
      const taskNumber = Number(taskKey);
      const taskTitle = Number.isFinite(taskNumber)
        ? getStudentSearchTaskTitle(taskNumber, taskTitles, testsDb)
        : `Задание ${taskKey}`;
      const content = collectStudentSearchObjectText(question, { maxChars: 32_000 });
      if (!content) return;
      addCandidate({
        result: {
          id: `mock-question:${examId}:${taskKey}`,
          kind: 'mock-question',
          group: 'mocks',
          title: `${examTitle} · ${taskTitle}`,
          subtitle: 'Задание пробника',
          sourceLabel: 'Пробник',
          timestamp: String(safeExam.updatedAt || safeExam.createdAt || ''),
          target: { kind: 'mock', examId, taskNumber: String(taskKey || '').trim() || null },
        },
        fields: [
          { name: 'title', text: `${examTitle} ${taskTitle}`, weight: 650 },
          { name: 'content', text: content, weight: 300 },
        ],
      });
    });
  });

  (Array.isArray(studentData?.mocks) ? studentData.mocks : []).forEach((mockResult, index) => {
    if (!mockResult || typeof mockResult !== 'object') return;
    const resultId = String(mockResult.id || mockResult.examId || index).trim();
    const examId = String(mockResult.examId || '').trim();
    const content = collectStudentSearchObjectText({
      title: mockResult.title,
      comment: mockResult.comment,
      date: mockResult.date,
      score: mockResult.score,
    });
    if (!content) return;
    addCandidate({
      result: {
        id: `mock-result:${resultId}`,
        kind: 'mock-result',
        group: 'mocks',
        title: String(mockResult.title || 'Результат пробника').trim(),
        subtitle: Number.isFinite(Number(mockResult.score)) ? `${Number(mockResult.score)} баллов` : 'Результат',
        sourceLabel: 'Результат',
        timestamp: String(mockResult.updatedAt || mockResult.createdAt || mockResult.date || ''),
        target: examId
          ? { kind: 'mock', examId }
          : { kind: 'progress-section', progressSection: 'mocks' },
      },
      fields: [
        { name: 'title', text: String(mockResult.title || 'Результат пробника'), weight: 650 },
        { name: 'metadata', text: content, weight: 220 },
      ],
    });
  });
};

const collectStudentHomeworkSearchCandidates = ({ studentData, addCandidate }) => {
  getStudentHomeworkNavItems(studentData).forEach((homework, index) => {
    if (!homework || typeof homework !== 'object') return;
    const content = collectStudentSearchObjectText({
      homeWork: homework.homeWork,
      goals: homework.goals,
      checklistItems: homework.checklistItems,
    });
    if (!content) return;
    const taskNumber = Number(homework.taskNumber);
    addCandidate({
      result: {
        id: `homework:${String(homework.id || index)}`,
        kind: 'homework',
        group: 'tasks',
        title: String(homework.title || homework.homeWork || 'Домашняя работа').trim().slice(0, 160),
        subtitle: Number.isFinite(taskNumber) ? `Задание №${taskNumber}` : 'Домашняя работа',
        sourceLabel: 'Домашняя работа',
        timestamp: String(homework.updatedAt || homework.issuedAt || homework.createdAt || ''),
        target: Number.isFinite(taskNumber)
          ? { kind: 'task', taskNumber, levelId: homework.levelId || undefined, targetQuestions: homework.targetQuestions || null }
          : { kind: 'navigate', view: 'schedule' },
      },
      fields: [
        { name: 'title', text: String(homework.title || homework.homeWork || 'Домашняя работа'), weight: 630 },
        { name: 'content', text: content, weight: 280 },
      ],
    });
  });
};

app.get('/api/student-search', async (req, res) => {
  if (!isAdminRole(req.auth) && !isTeacherRole(req.auth) && !isStudentRole(req.auth)) return forbid(res);
  const { studentId, q, limit } = req.query || {};
  const student = ensureStudentAccess(req, res, studentId, { missingError: 'studentId required' });
  if (!student) return;
  const rawQuery = typeof q === 'string' ? q : '';
  if (rawQuery.length > STUDENT_SEARCH_QUERY_MAX_LENGTH) {
    return res.status(400).json({ error: `Поисковый запрос длиннее ${STUDENT_SEARCH_QUERY_MAX_LENGTH} символов` });
  }
  const query = buildStudentSearchQuery(rawQuery);
  if (query.normalized.length < 2) {
    return res.status(400).json({ error: 'Введите минимум 2 символа для поиска' });
  }
  const parsedLimit = Number(limit);
  const resultLimit = Number.isFinite(parsedLimit)
    ? Math.max(1, Math.min(STUDENT_SEARCH_MAX_LIMIT, Math.floor(parsedLimit)))
    : STUDENT_SEARCH_DEFAULT_LIMIT;
  const results = [];
  const seenResultIds = new Set();
  let resultCollectionTruncated = false;
  const addCandidate = (candidate) => {
    if (results.length >= STUDENT_SEARCH_MAX_RESULTS_BEFORE_LIMIT) {
      resultCollectionTruncated = true;
      return;
    }
    const match = matchStudentSearchCandidate(candidate, query);
    const resultId = String(match?.id || '').trim();
    if (!match || !resultId || seenResultIds.has(resultId)) return;
    seenResultIds.add(resultId);
    results.push(match);
  };

  const rawTestsDb = getTestsDbWithPythonInfiniteTraining(readTestsDb());
  const testsDb = sanitizeTestsDbForStudent(rawTestsDb);
  const taskTitles = readTaskTitlesDb();
  const studentData = getStudentData(student.id);
  const teacherId = normalizeTeacherId(student.teacherId);
  const visibleFiles = enrichFilesWithFolderPath(
    readFilesDb().filter((file) => {
      if (isWorkbookQuestionVirtualSource(file)) return false;
      if (String(file?.studentId || '').trim() === student.id) return true;
      return isLessonSharedFile(file) && normalizeTeacherId(file?.teacherId) === teacherId;
    }),
    readFoldersDb()
  ).sort((left, right) => getStudentSearchFileTimestampMs(right) - getStudentSearchFileTimestampMs(left));

  const fileBudget = { used: 0 };
  let scannedFiles = 0;
  let skippedFiles = 0;
  for (const file of visibleFiles.slice(0, STUDENT_SEARCH_MAX_FILES)) {
    const memory = file?.memory && typeof file.memory === 'object' && !Array.isArray(file.memory)
      ? file.memory
      : {};
    const taskNumber = Number(file?.taskNumber ?? memory?.taskNumber);
    const taskTitle = Number.isFinite(taskNumber)
      ? getStudentSearchTaskTitle(taskNumber, taskTitles, testsDb)
      : 'Конспекты';
    const fileKind = getStudentSearchFileKind(file);
    const fileName = String(file?.name || memory?.title || 'Материал').trim();
    const displayTitle = String(memory?.title || fileName).trim() || fileName;
    const folderPath = String(file?.folderPath || file?.folderName || '').trim();
    const metadata = [
      fileName,
      folderPath,
      file?.category,
      file?.source,
      memory.title,
      memory.description,
      memory.tags,
      memory.kind,
      memory.source,
      memory.codePreview,
      memory.lastRunOutput,
      memory.savedBy?.name,
      memory.boardSnapshot?.name,
      taskTitle,
    ].flat(Infinity).filter(Boolean).join('\n');
    const contentResult = await readStudentSearchFileText(file, fileBudget);
    if (contentResult.bytes > 0) scannedFiles += 1;
    if (contentResult.skipped) skippedFiles += 1;
    addCandidate({
      result: {
        id: `file:${String(file?.id || '')}`,
        kind: fileKind.kind,
        group: fileKind.group,
        title: displayTitle,
        subtitle: [taskTitle, folderPath].filter(Boolean).join(' · '),
        sourceLabel: fileKind.sourceLabel,
        timestamp: String(file?.updatedAt || file?.lessonSavedAt || memory?.createdAt || file?.createdAt || ''),
        target: {
          kind: 'notes',
          location: {
            studentId: student.id,
            taskNumber: Number.isFinite(taskNumber) ? taskNumber : null,
            category: String(file?.category || 'class'),
            folderId: getStudentSearchFileTargetFolderId(file, taskNumber),
            fileId: String(file?.id || ''),
          },
        },
      },
      fields: [
        { name: 'title', text: displayTitle, weight: 700 },
        { name: 'metadata', text: metadata, weight: 300 },
        { name: 'content', text: contentResult.text, weight: 560 },
      ],
    });
  }
  if (visibleFiles.length > STUDENT_SEARCH_MAX_FILES) {
    skippedFiles += visibleFiles.length - STUDENT_SEARCH_MAX_FILES;
  }

  collectStudentSavedCodeSearchCandidates({ student, studentData, taskTitles, testsDb, addCandidate });
  collectStudentQuestionSearchCandidates({ testsDb, taskTitles, addCandidate });
  collectStudentMockSearchCandidates({ student, studentData, taskTitles, testsDb, addCandidate });
  collectStudentHomeworkSearchCandidates({ studentData, addCandidate });

  results.sort((left, right) => {
    const scoreDiff = Number(right.score || 0) - Number(left.score || 0);
    if (scoreDiff !== 0) return scoreDiff;
    const timeDiff = Date.parse(String(right.timestamp || '')) - Date.parse(String(left.timestamp || ''));
    if (Number.isFinite(timeDiff) && timeDiff !== 0) return timeDiff;
    return String(left.title || '').localeCompare(String(right.title || ''), 'ru');
  });
  const total = results.length;
  return res.json({
    query: query.raw,
    studentId: student.id,
    results: results.slice(0, resultLimit),
    total,
    truncated: total > resultLimit || skippedFiles > 0 || resultCollectionTruncated,
    scan: {
      visibleFiles: visibleFiles.length,
      scannedTextFiles: scannedFiles,
      skippedTextFiles: skippedFiles,
      scannedBytes: fileBudget.used,
    },
  });
});

const finishActiveLessonReplaySession = async (session, rawEvents = [], options = {}) => {
  if (!session?.id || !session?.occurrenceKey) return false;
  if (session.closing) return false;
  session.closing = true;
  const nowMs = Number(options.nowMs) || Date.now();
  try {
    await withLessonReplayWriteLock(session.occurrenceKey, () => {
      const replay = readLessonReplay(session.occurrenceKey);
      if (!replay) return;
      const context = {
        actorRole: session.actorRole,
        actorId: session.actorId,
        actorName: session.actorName,
        nowMs,
        normalizedReplay: true,
      };
      const withPending = appendLessonReplayEvents(replay, rawEvents, context).replay;
      const appended = appendLessonReplayEvents(withPending, [{
        id: `${session.id}:end`,
        type: 'session',
        occurredAt: new Date(nowMs).toISOString(),
        payload: {
          action: 'end',
          via: session.via === 'telemost' ? 'telemost' : 'platform',
        },
      }], context);
      writeLessonReplay(appended.replay, { normalized: true });
    });
    activeLessonReplaySessions.delete(session.id);
    const hasOtherOccurrenceSession = Array.from(activeLessonReplaySessions.values())
      .some((entry) => entry.occurrenceKey === session.occurrenceKey && !entry.closing);
    if (!hasOtherOccurrenceSession && !lessonReplayPersistTimerByOccurrenceKey.has(session.occurrenceKey)) {
      lessonReplayCacheByOccurrenceKey.delete(session.occurrenceKey);
      lessonReplayPersistFailureByOccurrenceKey.delete(session.occurrenceKey);
    }
    return true;
  } catch (error) {
    session.closing = false;
    throw error;
  }
};

const finishTelemostLessonReplay = async (studentId, options = {}) => {
  const normalizedStudentId = String(studentId || '').trim();
  if (!normalizedStudentId) return { finishedSessions: 0 };
  const entry = activeTelemostLessonReplayByStudentId.get(normalizedStudentId);
  const occurrenceKey = String(options.occurrenceKey || entry?.occurrence?.key || '').trim();
  if (!occurrenceKey) {
    activeTelemostLessonReplayByStudentId.delete(normalizedStudentId);
    return { finishedSessions: 0 };
  }
  const sessions = Array.from(activeLessonReplaySessions.values()).filter((session) => (
    session.studentId === normalizedStudentId && session.occurrenceKey === occurrenceKey
  ));
  let finishedSessions = 0;
  for (const session of sessions) {
    if (await finishActiveLessonReplaySession(session, [], options)) finishedSessions += 1;
  }
  activeTelemostLessonReplayByStudentId.delete(normalizedStudentId);
  const hasOtherStudentSession = Array.from(activeLessonReplaySessions.values())
    .some((session) => session.studentId === normalizedStudentId && session.expiresAt >= Date.now());
  if (!hasOtherStudentSession) activeLessonReplayOccurrenceByStudentId.delete(normalizedStudentId);
  return { finishedSessions, occurrenceKey };
};

const telemostLessonReplaySweepInterval = setInterval(() => {
  const nowMs = Date.now();
  activeTelemostLessonReplayByStudentId.forEach((entry, studentId) => {
    if (Number(entry?.autoFinishAtMs || 0) + TELEMOST_LESSON_DRAIN_MS > nowMs) return;
    if (hasActivePlatformLessonCall({ id: studentId, teacherId: entry?.teacherId })) return;
    void finishTelemostLessonReplay(studentId, { nowMs }).catch((error) => {
      console.error('[lesson-replay] failed to auto-finish Telemost lesson:', error);
    });
  });
}, 5 * 1000);
if (typeof telemostLessonReplaySweepInterval.unref === 'function') {
  telemostLessonReplaySweepInterval.unref();
}

app.get('/api/lesson-replay/activity', (req, res) => {
  const student = ensureStudentAccess(req, res, req.query?.studentId);
  if (!student) return;
  const nowMs = Date.now();
  const telemost = getTelemostLessonReplayEntry(student.id, nowMs);
  if (telemost) return res.json(serializeTelemostLessonReplayActivity(telemost, nowMs));
  if (hasActivePlatformLessonCall(student)) {
    const active = activeLessonReplayOccurrenceByStudentId.get(student.id);
    return res.json({
      active: true,
      mode: 'platform',
      studentId: student.id,
      occurrenceKey: String(active?.occurrence?.key || '').trim(),
      occurrence: active?.occurrence || null,
      autoFinishAt: '',
    });
  }
  return res.json({
    active: false,
    mode: '',
    studentId: student.id,
    occurrenceKey: '',
    occurrence: null,
    autoFinishAt: '',
  });
});

app.get('/api/lesson-replay/snapshot/:snapshotId', (req, res) => {
  const student = ensureStudentAccess(req, res, req.query?.studentId);
  if (!student) return;
  const occurrenceKey = String(req.query?.occurrenceKey || '').trim();
  const snapshotId = normalizeLessonReplaySnapshotId(req.params?.snapshotId);
  if (!occurrenceKey || occurrenceKey.length > 760 || !snapshotId) {
    return res.status(400).json({ error: 'Некорректный снимок занятия' });
  }
  const replay = readLessonReplay(occurrenceKey);
  if (!replay || replay.occurrence?.studentId !== student.id) {
    return res.status(404).json({ error: 'Запись занятия не найдена' });
  }
  const snapshotEvent = replay.events.find((event) => (
    event?.type === 'screen' && event.payload?.snapshotId === snapshotId
  ));
  if (!snapshotEvent) return res.status(404).json({ error: 'Снимок не найден' });
  const filePath = getLessonReplaySnapshotPath(
    occurrenceKey,
    snapshotId,
    snapshotEvent.payload?.mimeType
  );
  if (!filePath || !fs.existsSync(filePath)) {
    return res.status(404).json({ error: 'Снимок уже недоступен' });
  }
  res.setHeader('Cache-Control', 'private, no-store');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.type(snapshotEvent.payload?.mimeType === 'image/jpeg' ? 'jpeg' : 'webp');
  return res.sendFile(filePath);
});

app.post(
  '/api/lesson-replay/snapshot',
  (req, res, next) => {
    lessonReplaySnapshotUpload.single('file')(req, res, (error) => {
      if (!error) return next();
      if (error instanceof multer.MulterError && error.code === 'LIMIT_FILE_SIZE') {
        return res.status(413).json({ error: 'Снимок демонстрации слишком большой' });
      }
      return res.status(400).json({ error: 'Не удалось прочитать снимок демонстрации' });
    });
  },
  async (req, res) => {
    const sessionId = String(req.body?.sessionId || '').trim();
    const session = activeLessonReplaySessions.get(sessionId);
    if (!session) return res.status(410).json({ error: 'Сессия записи завершена' });
    if (session.closing) return res.status(410).json({ error: 'Сессия записи завершается' });
    if (
      session.actorId !== String(req.auth?.id || '').trim()
      || session.actorRole !== String(req.auth?.role || '').trim()
    ) return forbid(res);
    const student = ensureStudentAccess(req, res, session.studentId);
    if (!student) return;
    const nowMs = Date.now();
    if (session.via !== 'platform' || !isLessonReplaySessionWritable(session, student, nowMs)) {
      return res.status(410).json({ error: 'Демонстрация этого урока уже завершена' });
    }
    const buffer = req.file?.buffer;
    const mimeType = detectLessonReplaySnapshotMimeType(buffer);
    if (!mimeType || !Buffer.isBuffer(buffer) || buffer.length === 0) {
      return res.status(400).json({ error: 'Поддерживаются только снимки WebP и JPEG' });
    }
    const width = Math.max(1, Math.min(3840, Math.round(Number(req.body?.width) || 1280)));
    const height = Math.max(1, Math.min(2160, Math.round(Number(req.body?.height) || 720)));
    const sharedByRole = session.actorRole === 'student'
      ? 'student'
      : (req.body?.sharedByRole === 'teacher' ? 'teacher' : 'student');
    const sharedByName = String(req.body?.sharedByName || '').replace(/\0/g, '').trim().slice(0, 160);
    const checksum = crypto.createHash('sha256').update(buffer).digest('hex');
    const occurredAtMs = Date.parse(String(req.body?.occurredAt || '').trim());
    const occurredAt = new Date(Number.isFinite(occurredAtMs) ? occurredAtMs : nowMs).toISOString();

    try {
      const result = await withLessonReplayWriteLock(session.occurrenceKey, () => {
        if (session.closing || activeLessonReplaySessions.get(sessionId) !== session) {
          return { closed: true };
        }
        const replay = readLessonReplay(session.occurrenceKey);
        if (!replay || replay.occurrence?.studentId !== student.id) {
          const notFoundError = new Error('Запись занятия не найдена');
          notFoundError.statusCode = 404;
          throw notFoundError;
        }
        const latestSnapshot = [...replay.events].reverse().find((event) => event?.type === 'screen');
        if (
          latestSnapshot?.payload?.checksum === checksum
          && latestSnapshot?.payload?.sharedByRole === sharedByRole
        ) {
          return { duplicate: true, replay };
        }
        const referencedSnapshotUsage = replay.events.reduce((usage, event) => {
          if (event?.type !== 'screen') return usage;
          usage.count += 1;
          usage.bytes += Math.max(0, Number(event.payload?.sizeBytes) || 0);
          return usage;
        }, { count: 0, bytes: 0 });
        const indexedSnapshotBytes = Number(
          getLessonReplayStorageSummary(session.occurrenceKey)?.snapshotBytes
        ) || 0;
        const usage = {
          count: referencedSnapshotUsage.count,
          bytes: Math.max(referencedSnapshotUsage.bytes, indexedSnapshotBytes),
        };
        if (usage.count >= LESSON_REPLAY_SNAPSHOT_MAX_FILES) {
          const limitError = new Error('Для этого урока сохранено максимальное количество снимков');
          limitError.statusCode = 413;
          throw limitError;
        }
        if (usage.bytes + buffer.length > LESSON_REPLAY_SNAPSHOT_MAX_LESSON_BYTES) {
          const limitError = new Error('Для этого урока достигнут лимит снимков демонстрации');
          limitError.statusCode = 413;
          throw limitError;
        }
        if (!ensureLessonReplaySnapshotCapacity(buffer.length, session.occurrenceKey)) {
          const storageError = new Error('Общий лимит снимков демонстрации исчерпан');
          storageError.statusCode = 507;
          throw storageError;
        }

        const snapshotId = crypto.randomUUID();
        const folderPath = getLessonReplaySnapshotFolderPath(session.occurrenceKey);
        fs.mkdirSync(folderPath, { recursive: true });
        const filePath = getLessonReplaySnapshotPath(session.occurrenceKey, snapshotId, mimeType);
        const tempPath = `${filePath}.${process.pid}.${Date.now()}.tmp`;
        let stored = false;
        try {
          fs.writeFileSync(tempPath, buffer, { flag: 'wx' });
          fs.renameSync(tempPath, filePath);
          stored = true;
          const appended = appendLessonReplayEvents(replay, [{
            id: `${session.id}:screen:${snapshotId}`,
            type: 'screen',
            occurredAt,
            payload: {
              snapshotId,
              width,
              height,
              sizeBytes: buffer.length,
              mimeType,
              checksum,
              sharedByRole,
              sharedByName,
            },
          }], {
            actorRole: session.actorRole,
            actorId: session.actorId,
            actorName: session.actorName,
            nowMs,
            normalizedReplay: true,
          });
          if (appended.added !== 1) throw new Error('Screen snapshot event was rejected');
          const written = writeLessonReplay(appended.replay, { deferred: true, normalized: true });
          lessonReplaySnapshotStoredBytes += buffer.length;
          updateLessonReplayStorageIndex(session.occurrenceKey, {
            snapshotBytes: usage.bytes + buffer.length,
          });
          return { replay: written.replay, compressedBytes: written.compressedBytes, snapshotId };
        } catch (error) {
          try { if (fs.existsSync(tempPath)) fs.unlinkSync(tempPath); } catch {}
          try { if (stored && fs.existsSync(filePath)) fs.unlinkSync(filePath); } catch {}
          throw error;
        }
      });
      if (result?.closed) return res.status(410).json({ error: 'Запись этого урока уже завершена' });
      session.expiresAt = Date.now() + LESSON_REPLAY_SESSION_TTL_MS;
      const active = activeLessonReplayOccurrenceByStudentId.get(student.id);
      if (active) active.lastSeenAt = Date.now();
      return res.json({
        ok: true,
        duplicate: Boolean(result?.duplicate),
        snapshotId: result?.snapshotId || '',
        summary: summarizeLessonReplay(
          result.replay,
          result.compressedBytes ?? getLessonReplaySummary(session.occurrenceKey, result.replay).bytes,
          { normalized: true }
        ),
      });
    } catch (error) {
      const statusCode = Number(error?.statusCode) || 500;
      if (statusCode >= 500) {
        console.error('[lesson-replay] failed to save screen snapshot:', error);
      }
      return res.status(statusCode).json({
        error: statusCode >= 500 ? 'Не удалось сохранить снимок демонстрации' : error.message,
      });
    }
  }
);

app.get('/api/lesson-replay/audio/:audioId', async (req, res) => {
  const student = ensureStudentAccess(req, res, req.query?.studentId);
  if (!student) return;
  const occurrenceKey = String(req.query?.occurrenceKey || '').trim();
  const audioId = normalizeLessonReplayAudioId(req.params?.audioId);
  if (!occurrenceKey || occurrenceKey.length > 760 || !audioId) {
    return res.status(400).json({ error: 'Некорректный фрагмент аудиозаписи' });
  }
  const replay = readLessonReplay(occurrenceKey);
  if (!replay || replay.occurrence?.studentId !== student.id) {
    return res.status(404).json({ error: 'Запись занятия не найдена' });
  }
  const audioEvent = replay.events.find((event) => (
    event?.type === 'audio' && event.payload?.audioId === audioId
  ));
  if (!audioEvent) return res.status(404).json({ error: 'Фрагмент аудиозаписи не найден' });
  if (audioEvent.payload?.storage === 'local') {
    const localFilePath = getLessonReplayAudioLocalFilePath(
      occurrenceKey,
      audioId,
      audioEvent.payload?.mimeType
    );
    try {
      const stat = fs.statSync(localFilePath);
      if (!stat.isFile() || stat.size <= 0) throw new Error('missing');
      res.setHeader('Cache-Control', 'private, no-store');
      res.setHeader('X-Content-Type-Options', 'nosniff');
      res.setHeader('Content-Type', audioEvent.payload?.mimeType || 'audio/webm');
      res.setHeader('Content-Disposition', 'inline');
      return res.sendFile(localFilePath);
    } catch {
      return res.status(404).json({ error: 'Фрагмент аудиозаписи не найден на сервере' });
    }
  }
  if (!lessonReplayAudioS3) {
    return res.status(503).json({ error: 'Внешнее хранилище этой аудиозаписи не подключено' });
  }
  const objectKey = getLessonReplayAudioObjectKey(
    occurrenceKey,
    audioId,
    audioEvent.payload?.mimeType
  );
  try {
    const playbackUrl = await getSignedUrl(
      lessonReplayAudioS3,
      new GetObjectCommand({
        Bucket: lessonReplayAudioS3Config.bucket,
        Key: objectKey,
      }),
      { expiresIn: LESSON_REPLAY_AUDIO_URL_TTL_SECONDS }
    );
    res.setHeader('Cache-Control', 'private, no-store');
    return res.redirect(302, playbackUrl);
  } catch (error) {
    console.error('[lesson-replay] failed to sign audio playback:', error?.message || error);
    return res.status(503).json({ error: 'Аудиозапись временно недоступна' });
  }
});

app.post('/api/lesson-replay/audio/prepare', async (req, res) => {
  const sessionId = String(req.body?.sessionId || '').trim();
  const session = activeLessonReplaySessions.get(sessionId);
  if (!session || session.closing) {
    return res.status(410).json({ error: 'Сессия записи завершена' });
  }
  if (
    session.actorId !== String(req.auth?.id || '').trim()
    || session.actorRole !== String(req.auth?.role || '').trim()
  ) return forbid(res);
  const student = ensureStudentAccess(req, res, session.studentId);
  if (!student) return;
  const nowMs = Date.now();
  const expiredTelemost = activeTelemostLessonReplayByStudentId.get(student.id);
  const canDrainTelemost = Boolean(
    session.via === 'telemost'
    && expiredTelemost?.occurrence?.key === session.occurrenceKey
    && nowMs <= Number(expiredTelemost.autoFinishAtMs || 0) + TELEMOST_LESSON_DRAIN_MS
  );
  if (!isLessonReplaySessionWritable(session, student, nowMs) && !canDrainTelemost) {
    return res.status(410).json({ error: 'Запись этого урока уже завершена' });
  }
  const mimeType = normalizeLessonReplayAudioMimeType(req.body?.mimeType);
  const sizeBytes = Math.round(Number(req.body?.sizeBytes) || 0);
  const durationMs = Math.round(Number(req.body?.durationMs) || 0);
  if (!mimeType) return res.status(400).json({ error: 'Этот формат аудио не поддерживается' });
  if (sizeBytes <= 0 || sizeBytes > LESSON_REPLAY_AUDIO_MAX_SEGMENT_BYTES) {
    return res.status(413).json({ error: 'Фрагмент аудио слишком большой' });
  }
  if (durationMs < 250 || durationMs > 10 * 60 * 1000) {
    return res.status(400).json({ error: 'Некорректная длительность аудиофрагмента' });
  }
  const pendingForSession = Array.from(lessonReplayAudioUploadTickets.values())
    .filter((ticket) => (
      !ticket.completed
      && ticket.sessionId === sessionId
      && Number(ticket.expiresAt) >= nowMs
    ))
    .length;
  if (pendingForSession >= 4) {
    return res.status(429).json({ error: 'Предыдущий фрагмент аудио ещё загружается' });
  }
  const storedAudioBytes = Math.max(
    0,
    Number(getLessonReplayStorageSummary(session.occurrenceKey)?.audioBytes) || 0
  );
  const pendingAudioBytes = Array.from(lessonReplayAudioUploadTickets.values()).reduce((sum, ticket) => (
    !ticket.completed
      && ticket.occurrenceKey === session.occurrenceKey
      && Number(ticket.expiresAt) >= nowMs
      ? sum + Math.max(0, Number(ticket.sizeBytes) || 0)
      : sum
  ), 0);
  if (storedAudioBytes + pendingAudioBytes + sizeBytes > LESSON_REPLAY_AUDIO_MAX_LESSON_BYTES) {
    return res.status(413).json({ error: 'Для одного урока достигнут лимит аудиозаписи' });
  }
  const occurredAtMs = Date.parse(String(req.body?.occurredAt || '').trim());
  const audioId = crypto.randomUUID();
  const storage = lessonReplayAudioS3 ? 's3' : 'local';
  const objectKey = storage === 's3'
    ? getLessonReplayAudioObjectKey(session.occurrenceKey, audioId, mimeType)
    : '';
  const localFilePath = storage === 'local'
    ? getLessonReplayAudioLocalFilePath(session.occurrenceKey, audioId, mimeType)
    : '';
  const ticket = {
    audioId,
    sessionId,
    occurrenceKey: session.occurrenceKey,
    studentId: student.id,
    actorId: session.actorId,
    actorRole: session.actorRole,
    actorName: session.actorName,
    storage,
    objectKey,
    localFilePath,
    mimeType,
    sizeBytes,
    durationMs,
    occurredAt: new Date(Number.isFinite(occurredAtMs) ? occurredAtMs : nowMs).toISOString(),
    expiresAt: nowMs + LESSON_REPLAY_AUDIO_UPLOAD_TTL_MS,
  };
  if (storage === 'local') {
    if (!hasLessonReplayAudioDiskCapacity(sizeBytes)) {
      return res.status(507).json({ error: 'На сервере осталось слишком мало места для аудиозаписи' });
    }
    lessonReplayAudioUploadTickets.set(audioId, ticket);
    session.expiresAt = nowMs + LESSON_REPLAY_SESSION_TTL_MS;
    return res.json({
      audioId,
      storage,
      uploadUrl: `/api/lesson-replay/audio/upload/${encodeURIComponent(audioId)}`,
      headers: { 'Content-Type': mimeType },
      expiresAt: new Date(ticket.expiresAt).toISOString(),
    });
  }
  try {
    const uploadUrl = await getSignedUrl(
      lessonReplayAudioS3,
      new PutObjectCommand({
        Bucket: lessonReplayAudioS3Config.bucket,
        Key: objectKey,
      }),
      { expiresIn: Math.round(LESSON_REPLAY_AUDIO_UPLOAD_TTL_MS / 1000) }
    );
    lessonReplayAudioUploadTickets.set(audioId, ticket);
    session.expiresAt = nowMs + LESSON_REPLAY_SESSION_TTL_MS;
    return res.json({
      audioId,
      storage,
      uploadUrl,
      headers: { 'Content-Type': mimeType },
      expiresAt: new Date(nowMs + LESSON_REPLAY_AUDIO_UPLOAD_TTL_MS).toISOString(),
    });
  } catch (error) {
    console.error('[lesson-replay] failed to sign audio upload:', error?.message || error);
    return res.status(503).json({ error: 'Не удалось подготовить загрузку аудиозаписи' });
  }
});

app.put(
  '/api/lesson-replay/audio/upload/:audioId',
  express.raw({ type: () => true, limit: LESSON_REPLAY_AUDIO_MAX_SEGMENT_BYTES }),
  async (req, res) => {
    const audioId = normalizeLessonReplayAudioId(req.params?.audioId);
    const ticket = audioId ? lessonReplayAudioUploadTickets.get(audioId) : null;
    if (!ticket || Number(ticket.expiresAt) < Date.now()) {
      if (audioId) lessonReplayAudioUploadTickets.delete(audioId);
      return res.status(410).json({ error: 'Время загрузки аудиофрагмента истекло' });
    }
    if (ticket.storage !== 'local') {
      return res.status(400).json({ error: 'Некорректный способ загрузки аудиофрагмента' });
    }
    if (
      ticket.actorId !== String(req.auth?.id || '').trim()
      || ticket.actorRole !== String(req.auth?.role || '').trim()
    ) return forbid(res);
    const student = ensureStudentAccess(req, res, ticket.studentId);
    if (!student) return;
    const requestMimeType = normalizeLessonReplayAudioMimeType(req.headers['content-type']);
    if (!requestMimeType || requestMimeType !== ticket.mimeType) {
      return res.status(400).json({ error: 'Формат аудиофрагмента не совпадает' });
    }
    if (!Buffer.isBuffer(req.body) || req.body.length !== ticket.sizeBytes) {
      return res.status(400).json({ error: 'Аудиофрагмент загрузился не полностью' });
    }
    if (!hasLessonReplayAudioDiskCapacity(req.body.length)) {
      return res.status(507).json({ error: 'На сервере осталось слишком мало места для аудиозаписи' });
    }
    const localFilePath = getLessonReplayAudioLocalFilePath(
      ticket.occurrenceKey,
      audioId,
      ticket.mimeType
    );
    const audioRoot = `${path.resolve(lessonReplayAudioDir)}${path.sep}`;
    if (
      !localFilePath
      || localFilePath !== ticket.localFilePath
      || !path.resolve(localFilePath).startsWith(audioRoot)
    ) return res.status(400).json({ error: 'Некорректный путь аудиофрагмента' });

    const temporaryPath = `${localFilePath}.${crypto.randomUUID()}.upload`;
    try {
      await fs.promises.mkdir(path.dirname(localFilePath), { recursive: true });
      await fs.promises.writeFile(temporaryPath, req.body, { flag: 'wx' });
      await fs.promises.rename(temporaryPath, localFilePath);
      ticket.uploaded = true;
      return res.json({ ok: true, audioId });
    } catch (error) {
      console.error('[lesson-replay] failed to store local audio:', error?.message || error);
      return res.status(507).json({ error: 'Не удалось сохранить аудио на диске сервера' });
    } finally {
      fs.promises.rm(temporaryPath, { force: true }).catch(() => null);
    }
  }
);

app.post('/api/lesson-replay/audio/complete', async (req, res) => {
  const audioId = normalizeLessonReplayAudioId(req.body?.audioId);
  const ticket = audioId ? lessonReplayAudioUploadTickets.get(audioId) : null;
  if (!ticket || Number(ticket.expiresAt) < Date.now()) {
    if (audioId) lessonReplayAudioUploadTickets.delete(audioId);
    return res.status(410).json({ error: 'Время загрузки аудиофрагмента истекло' });
  }
  if (
    ticket.actorId !== String(req.auth?.id || '').trim()
    || ticket.actorRole !== String(req.auth?.role || '').trim()
  ) return forbid(res);
  const student = ensureStudentAccess(req, res, ticket.studentId);
  if (!student) return;
  if (ticket.completed && ticket.completedResponse) {
    return res.json(ticket.completedResponse);
  }
  try {
    let storedBytes = 0;
    if (ticket.storage === 'local') {
      if (!ticket.uploaded || !ticket.localFilePath) {
        return res.status(400).json({ error: 'Аудиофрагмент ещё не загружен' });
      }
      const expectedPath = getLessonReplayAudioLocalFilePath(
        ticket.occurrenceKey,
        audioId,
        ticket.mimeType
      );
      if (ticket.localFilePath !== expectedPath) {
        return res.status(400).json({ error: 'Некорректный аудиофрагмент' });
      }
      const stat = await fs.promises.stat(expectedPath);
      storedBytes = Math.round(Number(stat?.size) || 0);
    } else {
      if (!lessonReplayAudioS3) {
        return res.status(503).json({ error: 'Внешнее хранилище аудиозаписей не подключено' });
      }
      const head = await lessonReplayAudioS3.send(new HeadObjectCommand({
        Bucket: lessonReplayAudioS3Config.bucket,
        Key: ticket.objectKey,
      }));
      storedBytes = Math.round(Number(head?.ContentLength) || 0);
    }
    if (storedBytes <= 0 || storedBytes > LESSON_REPLAY_AUDIO_MAX_SEGMENT_BYTES) {
      return res.status(400).json({ error: 'Загруженный аудиофрагмент повреждён' });
    }
    const result = await withLessonReplayWriteLock(ticket.occurrenceKey, () => {
      const replay = readLessonReplay(ticket.occurrenceKey);
      if (!replay || replay.occurrence?.studentId !== student.id) {
        const notFoundError = new Error('Запись занятия не найдена');
        notFoundError.statusCode = 404;
        throw notFoundError;
      }
      const appended = appendLessonReplayEvents(replay, [{
        id: `${ticket.sessionId}:audio:${audioId}`,
        type: 'audio',
        occurredAt: ticket.occurredAt,
        payload: {
          audioId,
          durationMs: ticket.durationMs,
          sizeBytes: storedBytes,
          storage: ticket.storage,
          mimeType: ticket.mimeType,
        },
      }], {
        actorRole: ticket.actorRole,
        actorId: ticket.actorId,
        actorName: ticket.actorName,
        nowMs: Date.now(),
        normalizedReplay: true,
      });
      const stored = writeLessonReplay(appended.replay, { deferred: true, normalized: true });
      return { added: appended.added, replay: stored.replay, compressedBytes: stored.compressedBytes };
    });
    if (result.added > 0) {
      updateLessonReplayStorageIndex(ticket.occurrenceKey, {}, {
        audioBytes: storedBytes,
      });
    }
    const responsePayload = {
      ok: true,
      audioId,
      added: result.added,
      summary: summarizeLessonReplay(result.replay, result.compressedBytes, { normalized: true }),
    };
    ticket.completed = true;
    ticket.completedResponse = responsePayload;
    ticket.expiresAt = Date.now() + LESSON_REPLAY_AUDIO_UPLOAD_TTL_MS;
    return res.json(responsePayload);
  } catch (error) {
    const statusCode = Number(error?.statusCode) || 503;
    if (statusCode >= 500) {
      console.error('[lesson-replay] failed to complete audio upload:', error?.message || error);
    }
    return res.status(statusCode).json({
      error: statusCode === 404 ? error.message : 'Не удалось сохранить аудиофрагмент',
    });
  }
});

app.post('/api/lesson-replay/session', async (req, res) => {
  const student = ensureStudentAccess(req, res, req.body?.studentId);
  if (!student) return;
  if (!isTeacherRole(req.auth) && !isStudentRole(req.auth)) return forbid(res);
  try {
    const nowMs = Date.now();
    const requestedVia = req.body?.via === 'telemost' ? 'telemost' : 'platform';
    const requestedOccurrenceKey = String(req.body?.occurrenceKey || '').trim();
    const telemost = getTelemostLessonReplayEntry(student.id, nowMs);
    if (requestedVia === 'telemost' && !telemost) {
      return res.status(409).json({ error: 'Запись Телемоста уже не активна' });
    }
    if (requestedVia === 'platform' && !hasActivePlatformLessonCall(student)) {
      return res.status(409).json({ error: 'Запись начнётся после подключения учителя и ученика к звонку' });
    }
    if (
      requestedVia === 'telemost'
      && requestedOccurrenceKey
      && requestedOccurrenceKey !== telemost.occurrence?.key
    ) {
      return res.status(409).json({ error: 'Это занятие Телемоста уже не активно' });
    }
    const occurrence = requestedVia === 'telemost'
      ? telemost.occurrence
      : await resolveCurrentLessonReplayOccurrence(student, req.auth, nowMs, {
        preferredOccurrenceKey: requestedOccurrenceKey,
        preferActive: true,
      });
    if (!occurrence) return res.status(409).json({ error: 'Не удалось определить текущее занятие' });
    const actorRole = isTeacherRole(req.auth) ? 'teacher' : 'student';
    const actorId = String(req.auth.id || '').trim();
    const actorName = String(req.auth.name || (actorRole === 'teacher' ? 'Учитель' : student.name) || '').trim();
    const result = await withLessonReplayWriteLock(occurrence.key, () => {
      const reusable = Array.from(activeLessonReplaySessions.values()).find((session) => (
        session.occurrenceKey === occurrence.key
        && session.studentId === student.id
        && session.actorId === actorId
        && session.actorRole === actorRole
        && session.expiresAt >= nowMs
        && !session.closing
      ));
      if (reusable) {
        reusable.expiresAt = nowMs + LESSON_REPLAY_SESSION_TTL_MS;
        if (requestedVia === 'platform') reusable.lastPlatformActiveAt = nowMs;
        const replay = readLessonReplay(occurrence.key);
        let nextReplay = replay;
        if (reusable.via !== requestedVia && replay) {
          const switched = appendLessonReplayEvents(replay, [{
            id: `${reusable.id}:switch:${requestedVia}:${nowMs}`,
            type: 'session',
            occurredAt: new Date(nowMs).toISOString(),
            payload: { action: 'switch', via: requestedVia },
          }], {
            actorRole: reusable.actorRole,
            actorId: reusable.actorId,
            actorName: reusable.actorName,
            nowMs,
            normalizedReplay: true,
          });
          nextReplay = writeLessonReplay(switched.replay, { normalized: true }).replay;
          reusable.via = requestedVia;
        }
        return {
          session: reusable,
          replay: nextReplay,
          compressedBytes: getLessonReplaySummary(occurrence.key, nextReplay).bytes,
        };
      }

      const sessionId = crypto.randomUUID();
      const session = {
        id: sessionId,
        occurrenceKey: occurrence.key,
        studentId: student.id,
        actorId,
        actorRole,
        actorName,
        via: requestedVia,
        lastPlatformActiveAt: requestedVia === 'platform' ? nowMs : 0,
        createdAt: nowMs,
        expiresAt: nowMs + LESSON_REPLAY_SESSION_TTL_MS,
      };
      const replayOccurrence = {
        ...occurrence,
        startMs: Math.min(Number(occurrence.startMs) || nowMs, nowMs),
      };
      const currentReplay = readLessonReplay(occurrence.key) || createLessonReplay(replayOccurrence, nowMs);
      const appended = appendLessonReplayEvents(currentReplay, [{
        id: `${sessionId}:start`,
        type: 'session',
        occurredAt: new Date(nowMs).toISOString(),
        payload: { action: 'start', via: requestedVia },
      }], {
        actorRole: session.actorRole,
        actorId: session.actorId,
        actorName: session.actorName,
        nowMs,
        normalizedReplay: true,
      });
      const stored = writeLessonReplay(appended.replay, { normalized: true });
      activeLessonReplaySessions.set(sessionId, session);
      return { session, replay: stored.replay, compressedBytes: stored.compressedBytes };
    });
    const responseNowMs = Date.now();
    return res.json({
      sessionId: result.session.id,
      occurrenceKey: occurrence.key,
      occurrence,
      via: result.session.via,
      serverRequestReceivedAtMs: nowMs,
      serverNowMs: responseNowMs,
      serverNow: new Date(responseNowMs).toISOString(),
      summary: summarizeLessonReplay(result.replay, result.compressedBytes, { normalized: true }),
    });
  } catch (error) {
    console.error('[lesson-replay] failed to start session:', error);
    return res.status(500).json({ error: 'Не удалось начать запись действий урока' });
  }
});

app.post('/api/lesson-replay/switch', async (req, res) => {
  const sessionId = String(req.body?.sessionId || '').trim();
  const session = activeLessonReplaySessions.get(sessionId);
  if (!session) return res.status(410).json({ error: 'Сессия записи завершена' });
  if (session.closing) return res.status(410).json({ error: 'Сессия записи завершается' });
  if (
    session.actorId !== String(req.auth?.id || '').trim()
    || session.actorRole !== String(req.auth?.role || '').trim()
  ) return forbid(res);
  const student = ensureStudentAccess(req, res, session.studentId);
  if (!student) return;
  const via = req.body?.via === 'telemost' ? 'telemost' : 'platform';
  const nowMs = Date.now();
  if (via === 'telemost') {
    const telemost = getTelemostLessonReplayEntry(student.id, nowMs);
    if (!telemost || telemost.occurrence?.key !== session.occurrenceKey) {
      return res.status(409).json({ error: 'Запись Телемоста уже не активна' });
    }
  } else if (!hasActivePlatformLessonCall(student)) {
    return res.status(409).json({ error: 'Звонок на платформе уже не активен' });
  }
  if (session.via === via) return res.json({ ok: true, via, unchanged: true });
  try {
    await withLessonReplayWriteLock(session.occurrenceKey, () => {
      const replay = readLessonReplay(session.occurrenceKey);
      if (!replay) return;
      const appended = appendLessonReplayEvents(replay, [{
        id: `${session.id}:switch:${via}:${nowMs}`,
        type: 'session',
        occurredAt: new Date(nowMs).toISOString(),
        payload: { action: 'switch', via },
      }], {
        actorRole: session.actorRole,
        actorId: session.actorId,
        actorName: session.actorName,
        nowMs,
        normalizedReplay: true,
      });
      writeLessonReplay(appended.replay, { normalized: true });
    });
    session.via = via;
    if (via === 'platform') session.lastPlatformActiveAt = nowMs;
    session.expiresAt = nowMs + LESSON_REPLAY_SESSION_TTL_MS;
    return res.json({ ok: true, via });
  } catch (error) {
    console.error('[lesson-replay] failed to switch session mode:', error);
    return res.status(500).json({ error: 'Не удалось переключить режим записи' });
  }
});

app.post('/api/lesson-replay/events', async (req, res) => {
  const sessionId = String(req.body?.sessionId || '').trim();
  const session = activeLessonReplaySessions.get(sessionId);
  if (!session) return res.status(410).json({ error: 'Сессия записи завершена' });
  if (session.closing) return res.status(410).json({ error: 'Сессия записи завершается' });
  if (session.expiresAt < Date.now()) {
    activeLessonReplaySessions.delete(sessionId);
    return res.status(410).json({ error: 'Сессия записи истекла' });
  }
  if (
    session.actorId !== String(req.auth?.id || '').trim()
    || session.actorRole !== String(req.auth?.role || '').trim()
  ) return forbid(res);
  const student = ensureStudentAccess(req, res, session.studentId);
  if (!student) return;
  const nowMs = Date.now();
  const writable = isLessonReplaySessionWritable(session, student, nowMs);
  const expiredTelemost = activeTelemostLessonReplayByStudentId.get(student.id);
  const canDrainTelemost = Boolean(
    !writable
    && expiredTelemost?.occurrence?.key === session.occurrenceKey
    && nowMs <= Number(expiredTelemost.autoFinishAtMs || 0) + TELEMOST_LESSON_DRAIN_MS
  );
  if (!writable && !canDrainTelemost) {
    activeLessonReplaySessions.delete(sessionId);
    return res.status(410).json({ error: 'Запись этого урока уже завершена' });
  }
  const submittedEvents = Array.isArray(req.body?.events) ? req.body.events : [];
  const rawEvents = canDrainTelemost
    ? submittedEvents.filter((event) => {
      const occurredAtMs = Date.parse(String(event?.occurredAt || '').trim());
      return Number.isFinite(occurredAtMs) && occurredAtMs < Number(expiredTelemost.autoFinishAtMs || 0);
    })
    : submittedEvents;
  if (submittedEvents.length > LESSON_REPLAY_MAX_BATCH_EVENTS) {
    return res.status(400).json({ error: `За один раз можно сохранить не более ${LESSON_REPLAY_MAX_BATCH_EVENTS} событий` });
  }
  try {
    const result = await withLessonReplayWriteLock(session.occurrenceKey, () => {
      if (session.closing || activeLessonReplaySessions.get(sessionId) !== session) {
        return { closed: true };
      }
      const replay = readLessonReplay(session.occurrenceKey);
      if (!replay || replay.occurrence.studentId !== student.id) {
        const notFoundError = new Error('Запись занятия не найдена');
        notFoundError.statusCode = 404;
        throw notFoundError;
      }
      const appended = appendLessonReplayEvents(replay, rawEvents, {
        actorRole: session.actorRole,
        actorId: session.actorId,
        actorName: session.actorName,
        nowMs,
        normalizedReplay: true,
      });
      const finalReplay = canDrainTelemost
        ? appendLessonReplayEvents(appended.replay, [{
          id: `${session.id}:end`,
          type: 'session',
          occurredAt: new Date(Number(expiredTelemost.autoFinishAtMs || nowMs)).toISOString(),
          payload: { action: 'end', via: session.via === 'telemost' ? 'telemost' : 'platform' },
        }], {
          actorRole: session.actorRole,
          actorId: session.actorId,
          actorName: session.actorName,
          nowMs,
          normalizedReplay: true,
        })
        : appended;
      if (finalReplay.added > 0 || appended.added > 0) {
        const stored = writeLessonReplay(finalReplay.replay, {
          deferred: !canDrainTelemost,
          normalized: true,
        });
        return { appended, replay: stored.replay, compressedBytes: stored.compressedBytes };
      }
      return {
        appended,
        replay: appended.replay,
        compressedBytes: getLessonReplaySummary(session.occurrenceKey, appended.replay).bytes,
      };
    });
    if (result?.closed) {
      return res.status(410).json({ error: 'Запись этого урока уже завершена' });
    }
    if (canDrainTelemost) activeLessonReplaySessions.delete(sessionId);
    session.expiresAt = Date.now() + LESSON_REPLAY_SESSION_TTL_MS;
    const active = activeLessonReplayOccurrenceByStudentId.get(student.id);
    if (active) active.lastSeenAt = Date.now();
    return res.json({
      ok: true,
      added: result.appended.added,
      ended: canDrainTelemost,
      summary: summarizeLessonReplay(result.replay, result.compressedBytes, { normalized: true }),
    });
  } catch (error) {
    if (error?.statusCode === 404) return res.status(404).json({ error: error.message });
    console.error('[lesson-replay] failed to append events:', error);
    return res.status(500).json({ error: 'Не удалось сохранить ход занятия' });
  }
});

app.post('/api/lesson-replay/finish', async (req, res) => {
  const sessionId = String(req.body?.sessionId || '').trim();
  const session = activeLessonReplaySessions.get(sessionId);
  if (!session) return res.json({ ok: true, alreadyFinished: true });
  if (
    session.actorId !== String(req.auth?.id || '').trim()
    || session.actorRole !== String(req.auth?.role || '').trim()
  ) return forbid(res);
  const student = ensureStudentAccess(req, res, session.studentId);
  if (!student) return;
  const submittedEvents = Array.isArray(req.body?.events) ? req.body.events : [];
  if (submittedEvents.length > LESSON_REPLAY_MAX_BATCH_EVENTS) {
    return res.status(400).json({ error: `За один раз можно сохранить не более ${LESSON_REPLAY_MAX_BATCH_EVENTS} событий` });
  }
  const nowMs = Date.now();
  const telemost = activeTelemostLessonReplayByStudentId.get(student.id);
  const telemostCutoffMs = telemost?.occurrence?.key === session.occurrenceKey
    ? Number(telemost.autoFinishAtMs || 0)
    : 0;
  const shouldApplyTelemostCutoff = Boolean(
    telemostCutoffMs > 0
    && nowMs >= telemostCutoffMs
    && !hasActivePlatformLessonCall(student)
  );
  const rawEvents = shouldApplyTelemostCutoff
    ? submittedEvents.filter((event) => {
      const occurredAtMs = Date.parse(String(event?.occurredAt || '').trim());
      return Number.isFinite(occurredAtMs) && occurredAtMs < telemostCutoffMs;
    })
    : submittedEvents;
  try {
    await finishActiveLessonReplaySession(session, rawEvents, {
      nowMs: shouldApplyTelemostCutoff ? telemostCutoffMs : nowMs,
    });
    const hasOtherStudentSession = Array.from(activeLessonReplaySessions.values())
      .some((entry) => entry.studentId === student.id && entry.expiresAt >= Date.now());
    const hasTelemostLesson = Boolean(getTelemostLessonReplayEntry(student.id));
    if (!hasOtherStudentSession && !hasTelemostLesson) {
      activeLessonReplayOccurrenceByStudentId.delete(student.id);
    }
    return res.json({ ok: true });
  } catch (error) {
    console.error('[lesson-replay] failed to finish session:', error);
    return res.status(500).json({ error: 'Не удалось завершить запись действий' });
  }
});

app.post('/api/lesson-replay/lesson/finish', async (req, res) => {
  if (!isTeacherRole(req.auth)) return forbid(res);
  const student = ensureStudentAccess(req, res, req.body?.studentId);
  if (!student) return;
  const requestedOccurrenceKey = String(req.body?.occurrenceKey || '').trim();
  const telemost = activeTelemostLessonReplayByStudentId.get(student.id);
  if (
    requestedOccurrenceKey
    && telemost?.occurrence?.key
    && requestedOccurrenceKey !== telemost.occurrence.key
  ) {
    return res.status(409).json({ error: 'Сейчас записывается другое занятие' });
  }
  try {
    const result = await finishTelemostLessonReplay(student.id, {
      occurrenceKey: requestedOccurrenceKey || telemost?.occurrence?.key,
      nowMs: Date.now(),
    });
    return res.json({ ok: true, ...result });
  } catch (error) {
    console.error('[lesson-replay] failed to finish whole lesson:', error);
    return res.status(500).json({ error: 'Не удалось завершить запись урока' });
  }
});

app.get('/api/lesson-history/detail', async (req, res) => {
  const { studentId, occurrenceKey } = req.query || {};
  const student = ensureStudentAccess(req, res, studentId);
  if (!student) return;
  const normalizedOccurrenceKey = String(occurrenceKey || '').trim();
  if (!normalizedOccurrenceKey || normalizedOccurrenceKey.length > 760) {
    return res.status(400).json({ error: 'Некорректное занятие' });
  }
  try {
    const history = await buildResolvedStudentLessonHistory(student, req.auth);
    const occurrence = history.find((entry) => entry?.key === normalizedOccurrenceKey);
    if (!occurrence) {
      return res.status(404).json({ error: 'Занятие не найдено' });
    }
    return res.json({
      lesson: serializeStudentLessonHistoryEntry(occurrence),
      materials: collectStudentLessonMaterials(student, occurrence),
      replay: serializeLessonReplayForClient(readLessonReplay(occurrence.key)),
    });
  } catch (error) {
    console.error('[lesson-history] failed to build lesson detail:', error);
    return res.status(500).json({ error: 'Не удалось загрузить материалы занятия' });
  }
});

app.get('/api/lesson-history', async (req, res) => {
  const { studentId, offset, limit } = req.query || {};
  const student = ensureStudentAccess(req, res, studentId);
  if (!student) return;
  try {
    const history = await buildResolvedStudentLessonHistory(student, req.auth);
    const page = paginateStudentLessonHistory(history, { offset, limit });
    const includeReplayStorage = isTeacherRole(req.auth);
    const replayStorageByKey = new Map();
    let replayStorageTotalBytes = 0;
    let replayStoragePendingCount = 0;
    if (includeReplayStorage) {
      page.items.forEach((entry) => {
        getLessonReplayStorageSummary(entry?.key, { priority: true });
      });
      history.forEach((entry) => {
        const storage = getLessonReplayStorageSummary(entry?.key);
        if (!storage) {
          replayStoragePendingCount += 1;
          return;
        }
        replayStorageByKey.set(entry.key, storage);
        replayStorageTotalBytes += storage.totalBytes;
      });
    }
    return res.json({
      ...page,
      items: page.items.map((entry) => serializeStudentLessonHistoryEntry(
        entry,
        includeReplayStorage ? replayStorageByKey.get(entry.key) : null
      )),
      ...(includeReplayStorage ? {
        replayStorageTotalBytes: replayStoragePendingCount > 0 ? null : replayStorageTotalBytes,
        replayStorageKnownBytes: replayStorageTotalBytes,
        replayStorageStatus: replayStoragePendingCount > 0 ? 'indexing' : 'ready',
        replayStoragePendingCount,
      } : {}),
    });
  } catch (error) {
    console.error('[lesson-history] failed to build history:', error);
    return res.status(500).json({ error: 'Не удалось загрузить историю занятий' });
  }
});

app.get('/api/lesson-topics', async (req, res) => {
  const { studentId, from, to } = req.query || {};
  const student = ensureStudentAccess(req, res, studentId);
  if (!student) return;
  const range = getLessonTopicsRange(from, to);
  if (!range) {
    return res.status(400).json({ error: 'Некорректный период занятий' });
  }
  const schedule = await getScheduleForLessonTopics(student, req.auth);
  const scheduleOccurrences = expandLessonScheduleOccurrences({
    studentId: student.id,
    schedule,
    fromDayKey: range.fromDayKey,
    toDayKey: range.toDayKey,
    timeZone: GOOGLE_CALENDAR_SYNC_TIME_ZONE,
  });
  const store = readLessonTopicsStore();
  const manualOccurrences = expandLessonScheduleOccurrences({
    studentId: student.id,
    schedule: Object.values(store.topics).filter((entry) => entry?.studentId === student.id),
    fromDayKey: range.fromDayKey,
    toDayKey: range.toDayKey,
    timeZone: GOOGLE_CALENDAR_SYNC_TIME_ZONE,
  });
  const occurrences = Array.from(new Map(
    [...scheduleOccurrences, ...manualOccurrences].map((entry) => [entry.key, entry])
  ).values());
  const topics = resolveLessonTopicsForOccurrences({
    occurrences,
    manualTopics: store.topics,
    activities: store.activities,
    files: readFilesDb(),
  });
  return res.json({
    topics,
    from: range.fromDayKey,
    to: range.toDayKey,
  });
});

app.put('/api/lesson-topics', async (req, res) => {
  if (!ensureStaffWriteAccess(req, res)) return;
  const { studentId, dayKey, time, durationMinutes, text } = req.body || {};
  const student = ensureStudentAccess(req, res, studentId);
  if (!student) return;
  const normalizedDayKey = normalizeLessonDayKey(dayKey);
  const normalizedTime = normalizeLessonTime(time);
  const normalizedDuration = normalizeScheduleDurationMinutes(durationMinutes);
  const normalizedText = normalizeLessonTopicText(text);
  const occurrenceKey = buildLessonTopicOccurrenceKey({
    studentId: student.id,
    dayKey: normalizedDayKey,
    time: normalizedTime,
    durationMinutes: normalizedDuration,
  });
  if (!occurrenceKey) {
    return res.status(400).json({ error: 'Некорректное занятие' });
  }

  const store = readLessonTopicsStore();
  if (!normalizedText) {
    delete store.topics[occurrenceKey];
    writeLessonTopicsStore(store);
    updateLessonHistorySnapshotTopic(occurrenceKey, null);
    notifyScheduleSyncUpdate({
      scope: 'lesson-topic',
      action: 'deleted',
      teacherId: student.teacherId,
      studentId: student.id,
      occurrenceKey,
    });
    return res.json({ ok: true, occurrenceKey, topic: null });
  }

  const nowIso = new Date().toISOString();
  const existing = normalizeLessonTopicRecord(store.topics[occurrenceKey]);
  const topicRecord = normalizeLessonTopicRecord({
    studentId: student.id,
    teacherId: student.teacherId,
    dayKey: normalizedDayKey,
    time: normalizedTime,
    durationMinutes: normalizedDuration,
    text: normalizedText,
    createdAt: existing?.createdAt || nowIso,
    updatedAt: nowIso,
    updatedById: req.auth?.id,
    updatedByName: req.auth?.name,
  });
  store.topics[occurrenceKey] = topicRecord;
  writeLessonTopicsStore(store);
  updateLessonHistorySnapshotTopic(occurrenceKey, {
    text: topicRecord.text,
    source: 'teacher',
    taskNumbers: [],
    updatedAt: topicRecord.updatedAt,
  });
  notifyScheduleSyncUpdate({
    scope: 'lesson-topic',
    action: 'updated',
    teacherId: student.teacherId,
    studentId: student.id,
    occurrenceKey,
  });
  return res.json({
    ok: true,
    occurrenceKey,
    topic: {
      text: topicRecord.text,
      source: 'teacher',
      taskNumbers: [],
      updatedAt: topicRecord.updatedAt,
    },
  });
});

app.post('/api/student-schedule/google-sync', async (req, res) => {
  if (isStudentRole(req.auth)) {
    return res.status(403).json({ error: 'Синхронизация расписания доступна преподавателю.' });
  }
  const { studentId } = req.body || {};
  const student = ensureStudentAccess(req, res, studentId);
  if (!student) return;
  const teacherId = normalizeTeacherId(student.teacherId);
  if (!teacherId) {
    return res.status(400).json({ error: 'У ученика не указан преподаватель.' });
  }
  const teacher = ensureTeacherAccess(req, res, teacherId, { missingError: 'teacherId required' });
  if (!teacher) return;

  try {
    const syncResult = await syncStudentScheduleFromGoogleCalendar(student, req.auth, {
      force: true,
      rangeMode: GOOGLE_CALENDAR_SYNC_RANGE_UPCOMING,
    });
    if (syncResult.skippedReason === 'calendar-disabled') {
      return res.status(409).json({
        error: 'Google Calendar не подключён. Добавьте iCal-ссылку в настройках календаря преподавателя.',
        settings: syncResult.settings,
      });
    }
    if (syncResult.skippedReason === 'missing-teacher') {
      return res.status(400).json({ error: 'У ученика не указан преподаватель.' });
    }
    return res.json({
      ok: true,
      importedCount: syncResult.importedCount,
      matchedCount: syncResult.matchedCount,
      weekStart: syncResult.weekStart,
      weekEnd: syncResult.weekEnd,
      settings: syncResult.settings,
      schedule: await buildStudentSchedulePaymentResponse(student, syncResult.schedule),
    });
  } catch (error) {
    return res.status(502).json({
      error: error?.message || 'Не удалось загрузить Google Calendar.',
      settings: buildTeacherCalendarSyncSettingsResponse(getTeacherCalendarSyncSettings(teacher.id)),
    });
  }
});

app.get('/api/teacher-schedule', async (req, res) => {
  const { teacherId } = req.query || {};
  if (isStudentRole(req.auth)) return forbid(res);
  const resolvedTeacherId = isTeacherRole(req.auth) ? req.auth.id : teacherId;
  const teacher = ensureTeacherAccess(req, res, resolvedTeacherId, { missingError: 'teacherId required' });
  if (!teacher) return;
  const localEntries = getTeacherScheduleEntries(teacher.id);
  const googleEntries = await fetchTeacherGoogleCalendarEntries(teacher.id);
  return res.json([...localEntries, ...googleEntries]);
});

